/* 令和5年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r05.committeeSessions.push(...[{"id":"r05-20230309-3","meetingId":"r05-c-budget","date":"2023年3月9日","dateIso":"2023-03-09","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時４８分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を172件整理しています。","topics":[{"id":"topic-01","title":"予算特別委員会","agenda":"予算特別委員会","exchanges":[{"speaker":"江野下委員","kind":"質問・要望","question":"町会では、また担い手をどう増やしていけばよいかとの課題の一つの解決方法として、町会関係の方からアンケートを取ることになったと伺いました。３月５日のあるデジタル新聞では、地域を支えるには」との見出しの記事もありますので要望しますが、いかがか尋ねました。","respondent":"川島地域活動課長","answer":"伴走型支援は今年度新規事業で開始させていただいたものです。一律に支援を１年限りというふうにするということではなく、必要に応じて連続で支援を受けることも可能なスキームにしたいと考えています。","id":"exchange-001"},{"speaker":"江野下委員","kind":"提案","question":"続けて、１９１ページのコンテナ型喫煙所設置についてお伺いします。民間企業やＪＴ（日本たばこ産業）にもご協力いただいて、空き店舗を利用した喫煙所の設置などを提案しますが、いかがか尋ねました。","respondent":"森田生活安全担当課長","answer":"今様々検討を進めているところでございまして、以前にも少しご説明した機会がありますが、１回設置をしますと。いろいろなことを考えないといけないところがありますので、いろいろと努めていきながらやっていきたいと思っておるところです。","id":"exchange-002"},{"speaker":"江野下委員","kind":"提案","question":"例えば区のほうでその契約を２年間だけ定期借家というのですか、そういった悩みも解消していけるのではないかと考えております。提案というか、提案、要望としてとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"新妻委員","kind":"質問・要望","question":"所管課とも連携をしていただき、利用される世代の方々のお声を聞きながらつくり上げてほしいと求めましたが、見解を伺います。ぜひ所管課とも検討していただきながら、この団地への設置も進めてほしいと求めましたが、併せて見解を伺います。","respondent":"中西八潮まちづくり担当課長","answer":"ご質問にございました旧八潮南保育園跡地を活用しました在宅子育て支援施設のお話ですとか、コンテナ型喫煙所に関しましても。担当所管とも連携を密にしまして、よりよい施設、よりよいまちとなりますよう、私のほうでも努めてまいりたいと思います。","id":"exchange-004"},{"speaker":"新妻委員","kind":"質問・要望","question":"本定例会の代表質問で、おくやみコーナーの現庁舎での設置を改めて求めた際に、できるだけ早期の実現を目指すとのご答弁がありました。その方の支援を何か検討されているのか、お伺いをいたします。","respondent":"吉野戸籍住民課長","answer":"先行区の事例を参考にしながら進めていきたいと考えております。代理人がご家族以外の方でも、例えば高齢者であったりとか身体障害者施設の長が取りに行くことは可能になっております。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"そこをもう一歩、区としてできる取組をぜひ検討ほしいと求めましたので、よろしくお願いをいたします。そのときに、できたらそこのボルダリング場を活用して品川区の大会を開催していただきたいと要望させていただいた経緯がありますが、見解を伺います。","respondent":"吉野戸籍住民課長、辻スポーツ推進課長","answer":"今回、令和５年度なのですけれども、行政ＭａａＳについて予算に計上しています。もしくは商業施設に行ったりとか、そういった機動性を有効活用しながらいろいろと検討していきたいと考えております。こちらは、大きさは、幅が１２メートル、定員が１２名ということで、当面は月１回の初心者講習会を開く予定にはしております。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"１８３ページ、広町事業検討費について伺います。それとも中小企業センターのあるしながわ中央公園、下神明駅までの二葉の地域も指しているものなのか伺います。","respondent":"山下新庁舎整備課長","answer":"現庁舎跡など広町に係る事業調整を推進する部門といたしまして、広町事業担当並びに広町事業調整担当ということでの設置を予定しているものです。周辺敷地一帯の検討を進めていくということでお示ししておりますので、区有財産の部分を含めて広い検討が必要なものと考えています。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"収益性を追求するのではなく、区民の望む活用、区長の言葉を借りれば公共性に集中して追求すべきではないのか伺います。いかがか尋ねました。","respondent":"山下新庁舎整備課長","answer":"広域な検討と言ったときに、その周辺というところで、そういったところはやはり含んだ検討が今後必要になっていくものと捉えております。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"第二庁舎は平成６年、１９９４年竣工なので、築年数は２８年余だと思いますが、あと何年ぐらいもつ建物なのでしょうか。防災施設ということで起債を認められたと伺っておりますが、まだ使えるのに壊しても構わないのか、それとも縛りなどはあるのか、それぞれ伺います。","respondent":"山下新庁舎整備課長","answer":"第二庁舎の部分についてですけれども、事業費といたしましては７０億円余の負担があったものと考えています。他方で、一般的な庁舎という建物の構造の中で、５０年程度は使うようにもともとの段階では想定して建設をしていたものと認識しています。","id":"exchange-009"},{"speaker":"安藤委員","kind":"提案","question":"結局第二庁舎の今後というのは、連携相手の民間企業の考え方次第ということになるのではないでしょうか。伺いたいと思いますとの意見を述べました。","respondent":"山下新庁舎整備課長","answer":"事業費負担の面から、今回お出ししているものとしましては、現庁舎跡地等の活用につきまして区民の意見を聞きながら進めていきたいです。跡地検討委員会のようなものを設置しまして、種々検討を加えながら新たなまちづくりを進めていくという形になろうかと考えています。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"活用の大きな方向性は区や民間企業で決め、区民の意向はその補完程度というのは違うのではないでしょうか。その活用は区民の声を聞いて、一から検討すべきではないのか伺いたいと思います。","respondent":"山下新庁舎整備課長","answer":"現時点で、どういった形で賑わいの機能を創出していくかですとか、どういった施設類型にしていこうかというものは定まっているものではございません。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"区はそう思わないのでしょうか、伺いたいと思います。真っすぐ区民要望のための検討を、区民を入れて一から行うよう求めますが、いかがか尋ねました。","respondent":"山下新庁舎整備課長","answer":"るるご例示いただきましたけれども、東京都の事業におきましては、国家戦略特区等を使うというような形でかなり違った目線で進めているものです。区民の目線に立って区のために取り組んでいくものですので、今後、区民の意見を聞きながら丁寧に進めていきたいと考えています。","id":"exchange-012"},{"speaker":"松永委員","kind":"質問・要望","question":"時間がありましたら、１９３ページのハタチの龍馬ＰＲ事業について伺います。初めに、１８７ページの町会ホームページ運営支援等について伺いたいと思います。","respondent":"川島地域活動課長","answer":"加入促進支援の予算の中身ですが、それから、そういった物品を買ったりするような経費を加入促進支援のところで積ませていただいているものです。","id":"exchange-013"},{"speaker":"松永委員","kind":"確認","question":"これはどのような仕組みになっているのでしょうか。そうした町会・自治会の方々に対してはどのように進めていかれるのか尋ねました。","respondent":"川島地域活動課長","answer":"区の支援、明治大学の支援によりましてホームページを作成したのが２６町会、それから独自に作成されたのが２０町会と把握しています。独自支援につきましては、ということで、独自にあえて作っていらっしゃる町会もあるのかなと認識しています。","id":"exchange-014","title":"町会・自治会支援"},{"speaker":"松永委員","kind":"質問","question":"２０１町会・自治会がある中で、まだ４０町会強しかないということで、ぜひ進めてほしいと求めました。イベントがありますよとか、それとも自分たちの町会で更新しないといけないのか、そのことについて伺いたいと思います。","respondent":"川島地域活動課長","answer":"ホームページの更新につきましては、それぞれの町会でやっていただくということで、それがなかなかハードルが高く、ホームページは作ったのですけれどもなかなか更新されないというところも幾つかあるということで、大きな課題の一つだと認識しています。","id":"exchange-015","title":"町会・自治会支援"},{"speaker":"松永委員","kind":"質問","question":"そうしたところへ投げてやっていただけるような仕組みをぜひつくっていただければと考えていますので、どうぞよろしくお願い申し上げます。ホームページ作成など、様々な支援をされているのですけれども、ここ３年間の町会・自治会の加入率の推移を教えてほしいと求めました。","respondent":"川島地域活動課長","answer":"町会・自治会への加入率の推移ですが、過去３年間ということで申しますと、令和２年度が５８.３４％、令和３年度が６０.００％、令和４年度が５７.９３％ということでほぼ横ばい、少し減っている状況です。","id":"exchange-016","title":"町会・自治会支援"},{"speaker":"松永委員","kind":"質問","question":"町会・自治会に加入してほしいということで、例えば独自の手ぬぐいや帽子、ジャンパーを加入者に対してお渡ししてもよろしいのでしょうか。加入しなくても、その場で例えばその手ぬぐいとかをお渡ししてもよろしいのか、この事業について少しお伺いしたいと思います。","respondent":"川島地域活動課長","answer":"補助率は２分の１で、補助の上限が１０万円という形になってあります。ただ、イベント実施に当たっては、町会の加入とか未加入ということで対応が変わるようなことがないようにしていただくのはお願いしています。","id":"exchange-017","title":"町会・自治会支援"},{"speaker":"松永委員","kind":"質問・要望","question":"ここ３年で起きた品川区の被害額はどのようになっているのでしょうか。この事業によって未然に防げたことがあったのか、併せて伺います。","respondent":"森田生活安全担当課長","answer":"令和４年１月に私どもで補助金を使って設置をさせていただいたお宅において、警察と協力をした上で検挙したという事例があります。自動通話録音機をつけていただいている方は多いのですけれども、不審な電話がなくなったとか、そういったお話は受けているところです。","id":"exchange-018"},{"speaker":"澤田委員","kind":"質問・要望","question":"１６７ページの区施設営繕事務費、区有施設改修工事設計等委託についてお伺いします。ですので、まずは現在のエレベーターの状況をお伺いしたいと思います。","respondent":"小林施設整備課長、東野経理課長、大友新庁舎建設担当課長","answer":"やはりエレベーターにつきましては様々な方が使用されることがありますので、誰もが支障なく使用できることを目的に整備を進めているところです。… 庁舎におけるエレベーターですが、設置基数としましては、本庁舎が４基、第二庁舎が３基、第三庁舎、議会棟が１基ずつということになってあります。… 障害者の方への対応を目的とした設備の導入につきましては、投入設備の検討をしてまいりたいと考えています。","id":"exchange-019"},{"speaker":"澤田委員","kind":"質問・要望","question":"１９５ページ、外国人観光客誘致事業につきましてお伺いいたします。今年度の国際交流では新たな事業などは考えていらっしゃるのか尋ねました。","respondent":"古巻総務課長","answer":"来年度につきましては、オークランド市との交流の３０周年の事業ということで、オークランド市への派遣を考えております。国際交流につきましてはコロナ禍以前の状況にきちんと再開をしていく、まずそこから始めていきたいと考えております。","id":"exchange-020"},{"speaker":"澤田委員","kind":"質問","question":"それらバラエティに富んだ大使館等と連携し、パラリンピックとともに終わってしまったのでしょうか。現在もそちらのほうは行われているのでしょうか示すよう求めました。","respondent":"古巻総務課長","answer":"東京都の事業という認識をしておりまして、食を通じたそういった交流というのは身近な国際交流ということでは非常に有意義なことだと考えていますので、給食ということではなくて何か食を通じた交流みたいなものもできていければいいと考えておるところです。","id":"exchange-021"},{"speaker":"澤田委員","kind":"質問・要望","question":"ぜひ引き続き行っていただきたいとともに、世界の料理や文化を紹介し提供するイベントやフェスティバルなどを行うというのはいかがでしょうか。その国に興味を持つきっかけの一つとなり、グローバルな人材育成へとつなげることができるのではないか尋ねました。","respondent":"古巻総務課長","answer":"先ほども申し上げたとおり、食を通じた交流というのは非常に身近なところから国際理解が進むような交流になると思います。様々に工夫して国際交流が進むように事業を進めてまいりたいと考えております。","id":"exchange-022"},{"speaker":"澤田委員","kind":"質問・要望","question":"ぜひ進めてほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"いながき委員","kind":"質問","question":"補正予算の折、人権啓発課も早急にホームページ等で対応してくださるとのことでしたが、その後どうなっていますでしょうか。その後、国、総務省か厚労省かデジタル庁などからお知らせはあったのか尋ねました。","respondent":"加島人権啓発課長、吉野戸籍住民課長","answer":"１点目のホームページに関するお尋ねですけれども、当該情報が周知されるよう人権啓発課のほうにも今載せられるよう準備を図っているところです。それから、２点目のＤＶ相談のところでの説明なのですけれども… こちらのほうは鋭意情報提供させていただいているところでありますので、漏れのないように対応していきたいと考えております。これからも丁寧に対応していきたいと考えております。","id":"exchange-024"},{"speaker":"いながき委員","kind":"質問・要望","question":"なので、ぜひとも丁寧に進めてほしいと思います。改めて、品川区の見解を伺います。","respondent":"吉野戸籍住民課長","answer":"引き続きこの対応は続けたいと考えています。なので、引き続き慎重に対応していきます。","id":"exchange-025"},{"speaker":"いながき委員","kind":"質問","question":"そもそもなぜ新庁舎を建てるにあたって、大井町の駅に近い場所に建てようということにはならなかったのでしょうか。詳しい経緯を伺います。","respondent":"大友新庁舎建設担当課長、山下新庁舎整備課長","answer":"そちらのほうで、今回建設予定地となっている場所につきまして、行政機能・にぎわい集積ゾーンということで位置づけられております。このまちづくり方針に基づいて、新庁舎の建設予定地という形で計画しているものです。そういった行財政改革特別委員会でのご質疑等を踏まえまして、変更の内容といいますか、今回策定に至ったところについてご説明に上がったところです。","id":"exchange-026"},{"speaker":"いながき委員","kind":"質問・要望","question":"検討の経緯を伺っています。区として換地の際に、駅近くの土地にしてほしいという要望が出されたのか尋ねました。","respondent":"山下新庁舎整備課長、大友新庁舎建設担当課長","answer":"検討の経緯ということで、実際に策定というような形で、区としての決定に至ったものです。 その後同年の９月に開催している都市計画案の説明の中で丁寧な説明をしていると認識しております。その中では様々な意見があったものと受け止めております。","id":"exchange-027"},{"speaker":"いながき委員","kind":"質問・要望","question":"すみません。区として換地の際の要望をされたのかというお尋ねをしましたけれども、次の機会にそれは詳しくお尋ねをしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問・要望","question":"これは情報の管理、個人情報の管理というのは徹底していただきたいのですけれども、どうなっているか教えてください。２０７ページ、情報の管理を徹底していただきたいと思うのですけれども、お伺いします。","respondent":"大澤広報広聴課長、宮澤情報推進課長、吉野戸籍住民課長","answer":"これは区民の方にも浸透しておりまして、地域のイベント等でも広く活用されていることから、継続して活用したいと考えております。変更の必要性や… 委託を結ぶ際に、契約で個人情報保護に関する特記事項というのを結びまして、個人情報の保護について遵守するよう求めているところであります。… 戸籍住民課の窓口なのですけれども、こちらも委託事業者の方が対応しております。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"しながわ」に関しては、決算特別委員会のときも私が伺いました。けれども、まさに時宜にかなってない方法といいますかシステムだと私は思うのですけれども、その辺についてはいかがか尋ねました。","respondent":"鈴木選挙管理委員会事務局長","answer":"なので、それ以外の方が一般的に名簿を閲覧して個人情報を見るということはできないという規定があります。区の個人情報保護や情報公開の条例に従って事務は行いますが、それとは独立して、公職選挙法の規定の中で行うという制度です。","id":"exchange-030"},{"speaker":"藤原委員","kind":"確認","question":"そういうところが出ているのですから、あのような１時間とか２時間とか週何回とか月何回とか、回数はこのようなものでは済まないと思います。その辺については、いかがか尋ねました。","respondent":"鈴木選挙管理委員会事務局長","answer":"ただしご指摘のとおり、残念ながら区で対応できるところでありませんので、機会があるところで国や都にそういう話はしたいと考えます。そのようなことも含めまして、本日の質問も全てまた次回の委員会で報告をしまして、必要な対応はしたいと考えております。","id":"exchange-031"},{"speaker":"藤原委員","kind":"確認","question":"生活安全についてお伺いしますけれども、これは何回も質問しましたけれども、品川区に歩行喫煙等の条例があるわけですね。確認です。","respondent":"森田生活安全担当課長","answer":"個々の事案につきましては、個々に対応させていただいているところです。委員のご心配のようにまちでごみが増えないような、そういったところでは注意しながらやっていきたいと考えています。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問・要望","question":"これはいかがなものかという思いがあるので、これは来年度の予算ですから、また課長、この件に関しては来年１年かけてやっていきましょう。ですから、仕事はバランスですから、その辺についてはいかがか尋ねました。","respondent":"森田生活安全担当課長","answer":"委員の目にも触れているグッズもあるとは思いますが、様々これは引き継ぎ、やっていきたいと考えています。警視庁に戻っても仕事をさせていただきたいと考えていますが、まだ終わってはおりませんので、一生懸命引き続きやらせていただきます。","id":"exchange-033"},{"speaker":"藤原委員","kind":"質問","question":"次、１７８ページ、人事管理費なのですけれども、今出ている役職定年についてお伺いしますが、部長職でも役職定年になると課長補佐になってしまうのですね。","respondent":"崎村人事課長","answer":"委員のお話のとおり、部長職、課長職問わず管理職から外れるということで、課長補佐以下に降任するということになります。","id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"そして、この人事院勧告というのですか、古いですね。それをまた始めるというのは遅いと思うのですけれども、その辺についてはいかがだと思いますか。","respondent":"崎村人事課長","answer":"そういった経験が最大限生かせるような職場配置というものを人事としても考えていかなければいけないと考えております。今後については、役職定年制の導入は来年度から開始となりますけれども、こちらの制度については考えていく必要があるのではないかと捉えております。","id":"exchange-035"},{"speaker":"藤原委員","kind":"意見","question":"７割になってしまう。その辺考えていきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"松本委員","kind":"確認","question":"１７７ページ、特別職報酬等審議会経費について伺います。あるいはＮＰＯとか市民団体とか、あるいは地域の団体が入ってくるのか、その点をお伺いしたいと思います。","respondent":"山下新庁舎整備課長","answer":"特に特定の大企業を対象として行うというものではなくて、かなり幅広いスキームとして位置づけられているものとして認識しています。今の委員のご紹介のあった例えばＮＰＯ団体がその相手方になり得ないかというところにつきましては、必ずしもそうではないと認識しています。","id":"exchange-037"},{"speaker":"松本委員","kind":"意見","question":"やはり相手方も、では１社というか特定の企業が入っていくわけではなくて、その中でコンソーシアムを組んだり、いろいろやり方はあると思います。そのように自治体のほうでもうほぼ特に聞かなくてもやっていくようなことが可能なのか不可能なのか、お願いいたしますとの意見を述べました。","respondent":"山下新庁舎整備課長","answer":"いわゆる事業者の選定等々については、かなり後の段階での検討になってくるのかと思ってあります。今いただいたものについては今後検討しようと思いますけれども、委員会等で議論を交わしていくというところで進めていきたいと考えているものです。","id":"exchange-038"},{"speaker":"松本委員","kind":"質問","question":"私が伺ったのが、やろうと思えば、例えば自治体のトップの独断でどんどん進めていくということは従来方式でも可能ではないかと思います。これからそのようにやっていくかというところではなくて、そういうことが可能なのかどうか伺います。","respondent":"山下新庁舎整備課長","answer":"ご質問いただいているその進め方の部分につきまして、新たな担当を含めて今後検討が必要なのかと受け止めてあります。庁舎跡地の一体的な検討を進めることで、区民意見聴取を並行して進めながら、いろいろな検討を進めていくような形で考えてあります。","id":"exchange-039"},{"speaker":"松本委員","kind":"質問・要望","question":"次に、青少年健全育成事業について伺います。所管が地域活動課というところなのでここでお伺いしたいのですけれども、まずこの調査というのはどういう具体的な調査なのかと、お伺いいたします。","respondent":"川島地域活動課長","answer":"青少年を取り巻く健全育成の観点からの地域の調査ということで、６月から９月にかけまして各地区の地区委員が地域の中を回って調査結果をまとめまして、その結果につきましては管内の警察署のほうにその結果をお届けするというような内容になってあります。","id":"exchange-040"},{"speaker":"松本委員","kind":"質問","question":"広告物について有害なものを指定するというような条項はあるのですけれども、それはほとんどなされていないという状態かと思います。その中で、この看板とかポスターと掲げられているのですけれども、これはどういう法令の根拠に基づいてやられているのか伺います。","respondent":"川島地域活動課長","answer":"この条例は青少年の環境の整備を助長するとともにといったところになりますので、その目的を根拠としておりますが、細かなその様式等は整合性が取れていない部分もあるです。","id":"exchange-041"},{"speaker":"松本委員","kind":"質問・要望","question":"特定の親の目線で見たときに、これは子どもにとって不適切なものというのを親の思いで排除しようという動きというのもあったと。こういった調査をやったりしていくよりも、もっとほかの分野にお金を投資していただきたいと考えていて、いかがか尋ねました。","respondent":"川島地域活動課長","answer":"やはり今委員がおっしゃったとおり、区域内の自動販売機の数も今回ゼロということですけれども、よくなってきている。地区委員会連合会の役員の皆様とお話ししましても、私どもとしましても、この次の役員会等でそういった方向で話が進むものと認識しています。","id":"exchange-042"},{"speaker":"松本委員","kind":"質問","question":"次に、二十歳の集い式典経費について伺いたいのですけれども、来年度の予算を見ると９００万円を超えていて１００万円以上の増額になっています。ここはどうして増額になったのか伺います。","respondent":"古巻総務課長","answer":"令和２年度につきましては、コロナ禍の影響でございまして、直前で中止というような残念な形で、オンライン配信のみの実施となりました。","id":"exchange-043"},{"speaker":"松本委員","kind":"質問・要望","question":"すごいなとびっくりしたのですけれども、ではどういう人たちが来ているかといったら、これはやはり品川区が選んだ方たちが来ていると。参加したいですといったときに、そういう呼ばれていない人たちがこの新年賀詞交歓会に参加することができるのか、伺いたいと思います。","respondent":"古巻総務課長","answer":"そういった区との関わりの深い地域の団体であったりとか、様々な団体の構成員の方々をご招待という形で開催しているものです。なので、飛び入りでという形になるとなかなか整理がつかないという部分もありますので、そこはなかなか難しいのかなと考えているところです。","id":"exchange-044"},{"speaker":"松本委員","kind":"質問","question":"そうやって考えると、やはり区がある意味選んだ人たちに対して、アルコールとか食べ物を提供していたということになると思います。そうするとまた来年度以降、アルコールを提供するのかとも思えるのですが、ここは提供される想定で予算を組まれているのか尋ねました。","respondent":"古巻総務課長","answer":"形式については変更してやってありますけれども、今後どういった形で進めていくのがふさわしいのかということは様々な議論があるかと思いますので、やり方については考えていきたいと考えております。","id":"exchange-045"},{"speaker":"松本委員","kind":"質問・要望","question":"会員制にするべきだと思っているのですけれども、せっかく区長が代わられましたので、今後は区長と交流する場なのだと。そういう場というのをつくってほしいと求めましたが、ご意見を伺えればと思います。","respondent":"古巻総務課長","answer":"ただ、そういったセキュリティ上のことも踏まえて検討しなければいけないということで、課題はかなり多いのかなとも思います。区長と交流するという意味におきましては、今後もそういう交流がしっかりできるようなやり方について検討していきたいと思います。","id":"exchange-046"},{"speaker":"西村委員","kind":"提案","question":"コロナで３年がたち、区としても、以前のようなまちでの体験型観光を強化する提案を幾つかします。ツールや取組をがっちりと連携させることが重要と考えますが、現在の取組と区の考えを伺いますとの意見を述べました。","respondent":"山崎文化スポーツ振興部長","answer":"その中で、区のほうは観光協会などと連携しながら、おもてなし事業ということで展開してまいりました。まだまだ品川区には、この伝統工芸のすてきな方々もいますので、そうした魅力を最大限活用しながら取り組んでまいりたいなと考えているところです。","id":"exchange-047"},{"speaker":"西村委員","kind":"提案","question":"次に、小規模、５０から１００名くらい単位のＭＩＣＥの積極的な受入れを提案します。品川区での検討はいかがか尋ねました。","respondent":"山崎文化スポーツ振興部長","answer":"大井町の近隣ホテル、１０人、１５人で出展の関係者がよく来られておりました。先ほど来の体験なども含めて、商用のミーティングの中に区の魅力をはめ込んでいくような考え方、これは１つありかなと思っているところです。","id":"exchange-048"},{"speaker":"西村委員","kind":"提案","question":"森の木で子どもたちが作ったキーホルダーをエコルとごしで展示するですとか、森林環境譲与税を使った取組もできればとご提案差し上げたいところです。昨年私が品川区のキャンプ場開放事業に参加をさせていただいたのですが、１０倍以上か、相当な倍率だったと伺っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"横山委員","kind":"質問・要望","question":"区として、ＬＧＢＴＱ ＬＩＮＥ相談などのＳＮＳ相談をなるべく早急に実施していただきたいと要望いたしますが、区のお考えをお聞かせください。品川区でも新しい広聴の在り方の試行錯誤を始めていただきたいと要望いたしますが、区が把握している他自治体等の事例を確認したいと求めました。","respondent":"加島人権啓発課長、佐藤企画調整課長、大澤広報広聴課長","answer":"そういった状況を踏まえまして、多様な相談方法が用意されていることが望ましいということは認識しております。引き続き他区の状況など… ２点目の、オンライン上で意見を出すだけではなく、議論ができる仕組みは新しい試みであると認識をしております。したがいまして… 令和２年度以降、ホームページからご意見をお寄せいただく件数が多くなっており、区民の声は現在約９割がメールとなっております。","id":"exchange-050"},{"speaker":"横山委員","kind":"質問・要望","question":"４点目に監査委員費、住民監査請求についてお伺いをいたします。監査委員はじめ、１件の住民監査請求の手続に膨大な事務量と多くの時間を費やすなど、近年大きな負担を伴う業務となっているのではないか尋ねました。","respondent":"山崎文化スポーツ振興部長、高山監査委員事務局長","answer":"ただ、継続的な地域活動への還元レベルというのですか、そこまでは十分に達していないようなところも見受けられます。委員おっしゃったステップアップも含めて、踏んでいっていただけるように… お尋ねの同趣旨の請求が繰り返し行われた場合の対応につきましては、個別の対応ということにはなってまいりますが、要件が整った請求につきましては。事務局一同一丸となって、正確、迅速な対応に努めていく考えです。","id":"exchange-051"},{"speaker":"横山委員","kind":"質問・要望","question":"監査委員費、住民監査請求のところにつきましては、こちら大変な作業をしていただいているのだろうなというようなことが確認できました。ぜひ効率的に、強化していけるようにというところで進めていってほしいと求めましたので、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２０９ページ、２０７ページ、マイナンバーカードの区独自の活用メリット等について伺っていきます。マイナンバーカードの普及促進を求めまして、第３回定例会一般質問と、それに沿って状況を確認してまいりたいと思います。","respondent":"吉野戸籍住民課長","answer":"申請件数は３３万４,７４４件で、８２.９％になります。それから交付なのですけれども、２４万９,３５８枚で、６１.８％になります。","id":"exchange-053"},{"speaker":"あくつ委員","kind":"確認","question":"全国平均の７５.１％を上回っていることを確認しました。このコラボレーション事業について、品川区のご見解があれば説明を求めました。","respondent":"吉野戸籍住民課長","answer":"今年度なのですけれども、実施回数は５回になります。今後も行政書士の方のご尽力をいただけると、申請率などが伸びますので、今後も協力をしていただきたいというところであります。","id":"exchange-054"},{"speaker":"あくつ委員","kind":"質問・要望","question":"４点確認をしたいのですが、まず、車に乗り込んで現地に赴いて手続を行うのは、戸籍住民課などのしかるべき区の職員なのでしょうか。４つ目が、現在マイナポイントの付与期限が本年５月までとなっているのですが、どのような事態を想定されているのか伺います。","respondent":"吉野戸籍住民課長","answer":"車が空いているときには、戸籍住民課の職員など、そういったところも臨機応変に対応していきたいと考えているところです。こちらも引き続き実施していこうと考えております。","id":"exchange-055"},{"speaker":"あくつ委員","kind":"提案","question":"今後区民に愛されるサービスとしていくためには、このマルチタスク車両に区民公募で愛称をつけてはいかがでしょうかというご提案です。誰１人取り残さないという、この車は区民の下に区役所が向かっているのですよ、いかがか尋ねました。","respondent":"吉野戸籍住民課長","answer":"現時点では５月末なので、今後、その辺に関しましては、国の動向を注視していきたいなと考えております。ラッピングなどなのですけれども、こちらのほうも関係各課と調整といいますか、検討していきたいと思います。","id":"exchange-056"},{"speaker":"あくつ委員","kind":"質問","question":"一般質問で、地域センターでマイナポイント付与のお手伝いをしますと記載したのぼり旗等を立ててはいかがですか。区内地域センターでのマイナポイントの付与サポートの相談件数、また、周知の取組について教えてほしいと求めました。","respondent":"吉野戸籍住民課長","answer":"そのうち、地域センターのほうでは４,０００件のサポートをしていただいているような形になっております。９,４００件のうち４,２００件が、地域センターのほうでこの辺支援していただいておりますので、支援ができているのかなと考えています。","id":"exchange-057"},{"speaker":"あくつ委員","kind":"質問・要望","question":"最後に、前に一般質問のときに、やはりカードを持っているメリットというものは、区独自の利活用の創出が必要ではないかということを要望しました。この辺り、今検討状況はどうなっているのか、最後にお伺いします。","respondent":"吉野戸籍住民課長","answer":"今回、コンビニと同じマルチコピー機を導入いたします。これによりまして、窓口の混雑であったり、区民の方の利便性向上のほうに近づけていきたいなと考えている次第です。","id":"exchange-058"},{"speaker":"あくつ委員","kind":"質問・要望","question":"戸籍謄本、いわゆる戸籍全部事項証明書も取れるということで、それはいいのかなと思います。今後も、ぜひ独自の利活用策を検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"おくの委員","kind":"質問・要望","question":"区民の財産である学校跡地には、要望の強い特別養護老人ホームを建ててほしいと思いますけれども、いかがでしょうか。伺います。","respondent":"佐藤企画調整課長","answer":"ただ、可能な限り住み慣れた地域で在宅生活が継続できるよう、在宅生活を支える支援を充実させるということを基本として考えております。旧荏原第四中学校でも予定されておりますけれども、多くの地域の方々の意見を聞いて、しっかりと進めてまいりたいと考えております。","id":"exchange-060"},{"speaker":"おくの委員","kind":"質問・要望","question":"そのような検討は、大体、今もう始まっているのでしょうか。本格活用ということで、検討あるいは本格活用そのものはいつからということになっているのか、教えてほしいと求めました。","respondent":"佐藤企画調整課長","answer":"そして施設のほうは令和８年度まで、また、令和１０年度、令和１１年度までというところで、３つ施設をつくって、順次使わせていただくです。すぐ工事着工しても令和９年度というところになりますと、機能については、今後区民の方の意見を十分聞きながら検討していくです。","id":"exchange-061"},{"speaker":"おくの委員","kind":"質問","question":"それともう一つ、その検討事項の中に、特別養護老人ホームも選択肢として入っていると理解しておいてよろしいのでしょうか。伺います。","respondent":"佐藤企画調整課長","answer":"旧第一日野小学校に関しまして、例えば区民参加型の検討委員会を設置するという予定は来年度はございません。企画調整課のほうでどういったものが適しているのかということは、日頃から、内部で検討しています。","id":"exchange-062"},{"speaker":"おくの委員","kind":"質問・要望","question":"これ区有地という区民の財産の活用ですから、住民参加で行われるべきだと私は思うのですけれども、この点はいかがでしょうか。それから、住民の意思、それが十分に反映されるように、住民参加でやっていくべきだと思うのですけれども、いかがか尋ねました。","respondent":"佐藤企画調整課長","answer":"跡地の検討に対して、住民参加、区民の声をよく聴いてほしいですが、先ほど来答弁しているとおり、区として区民の声を聴くことは非常に重要だと考えておりますので、当然そういった形で進めていくです。","id":"exchange-063"},{"speaker":"おくの委員","kind":"質問・要望","question":"そうしますと、住民の要望、あるいは住民の意見、そのようなものを一体どのような方法で把握していくおつもりなのか。あるいはアンケートを取るとか、この地元住民の地域要望をどのような方法で把握していこうとお考えになっているのか、この点はいかがか尋ねました。","respondent":"佐藤企画調整課長","answer":"ワークショップであったり、アンケートであったり、あとそういったものを集約していくための検討委員会というものも必要になると考えています。そういったことも踏まえまして、より効率的に、また多くの区民の方の意見が聞けるような形を考えていくです。","id":"exchange-064"},{"speaker":"おくの委員","kind":"質問・要望","question":"この規模の特別養護老人ホームを、単純計算でいえば２つ建てられるほどの、なかなか手に入りにくい土地だと思います。ぜひともつくってほしいと求めましたけれども、いかがか尋ねました。","respondent":"佐藤企画調整課長","answer":"特別養護老人ホームも含めて、様々な行政ニーズを探りながら検討してまいります。","id":"exchange-065"},{"speaker":"芹澤委員","kind":"質問","question":"１８７ページの町会・自治会加入促進支援と、１７５ページ、１６７ページの公有地活用検討等についてお伺いをします。まずどう捉えていらっしゃるのかということと、地域で今ご説明されていると伺っているのですけれども、今後の区の考え方を説明するよう求めました。","respondent":"川島地域活動課長","answer":"住民の方とつながるきっかけになる、非常に意義のある取組だったと私どもは認識しております。区としましても様々検討はしたところではありますが、今各町会のほうにも、地域センターを通じて説明をしています。","id":"exchange-066","title":"町会・自治会支援"},{"speaker":"芹澤委員","kind":"質問・要望","question":"これは特別区長会など合わせて、ぜひ連携して模索していただきたい、これは要望で結構です。で、そのまま個人情報を提供していいですかと同意を取ることはなかなか難しいと思うのですが、お祝いの品を送っていいですかというようなことは。","respondent":"川島地域活動課長","answer":"法令遵守というものが我々の大事なところではありますが、今までのやってきたことの目的や、それから意義も含めて、可能性については探っていきたいと考えています。","id":"exchange-067"},{"speaker":"芹澤委員","kind":"提案","question":"今ご提案した方法でもなると思うので、どうしてもそれが難しいということであれば、区としては情報は持っているわけです。最後何か、お言葉があればとの意見を述べました。","respondent":"川島地域活動課長","answer":"同じような形での継続は非常に厳しいというところですけれども、考えていくということは分かりますが、ちょっと今の現状ではなかなかお答えするのが難しいところです。","id":"exchange-068"},{"speaker":"芹澤委員","kind":"確認","question":"新年賀詞交歓会についてお伺いをします。まず管理権限のところから確認をしてまいりますが、今回は品川区が所有者として建物全体を使ったというような認識でよろしいのか尋ねました。","respondent":"古巻総務課長","answer":"スクエア荏原ですけれども、指定管理の施設ということで、文化振興事業団が指定管理者として運営をしている状況です。ですから、区としましては、文化振興事業団のほうから施設の貸出しを受けて使用して、新年賀詞交歓会を実施いたしましたというような形になります。","id":"exchange-069"},{"speaker":"芹澤委員","kind":"質問・要望","question":"それはさすがにモラルがないのではないですかということは、やる側がモラルがないということで、私はそう思っています。来賓の方ですから、終わったことですから、そこのご見解を説明するよう求めました。","respondent":"古巻総務課長","answer":"新年賀詞交歓会、今委員からもご指摘がありましたとおり、区との関わりが深い方々をお呼びするです。確かにあまりふさわしい行為だとは考えられませんので、実施する側として注視、気をつけて実施をしていきたいと思います。","id":"exchange-070"},{"speaker":"芹澤委員","kind":"意見","question":"できれば、ドッグランも整備してほしいというようなお声が多くて、特にあそこは高速道路沿いなので、あまり騒音が周りの方も気になっていない。公園についても、その検討の施設として入ってくるのかだけ、最後ご見解を説明するよう求めました。","respondent":"佐藤企画調整課長","answer":"基本的に大規模用地は、区にとって貴重な財産であるです。地域の特性や中長期的な行政上の見通しを持って、地域の将来像を見ながら、様々な施設について区民の声を聴いて検討してまいります。","id":"exchange-071","title":"町会・自治会支援"},{"speaker":"せお委員","kind":"質問・要望","question":"このプロジェクトは、公有地等活用検討のための策定委員会などの設置運営なども行われるという理解でよろしいでしょうかということの確認が１点と。そもそもの話で申し訳ないのですけれども、グループホームに適した用地というのはどのようなものだとお考えか尋ねました。","respondent":"佐藤企画調整課長","answer":"１点目の検討委員会の経費も含まれるのかというところに関しましては、委員ご指摘のとおり、含まれるものです。異なることがないようというところで、そういった一定の要件があると認識をしております。","id":"exchange-072"},{"speaker":"せお委員","kind":"質問・要望","question":"コロナ感染拡大もあって、旧リボン旗の台店がワクチン接種会場で、大井町のほうも保健予防課で使用しているというお話は伺いました。特に、旧リボン大井町店は庁舎内ということで、どのような管轄というか、位置づけなのか尋ねました。","respondent":"東野経理課長","answer":"旧リボン大井町店のところにつきましては、閉店後、区としては当面会議室として使っていく方針がございました。今後コロナの終息に向けまして、どういった使い方ができるのかにつきましては、そういった動向を踏まえて検討をしていきたいと考えています。","id":"exchange-073"},{"speaker":"せお委員","kind":"質問・要望","question":"広い面積でなくても、区民の皆さんはこのように活用したらいいのではと、たくさん考えを巡らせてくれています。区民の声を何らかの形で広く伺いながら、今後の計画を進めていっていただきたいと考えますが、見解を伺います。","respondent":"佐藤企画調整課長","answer":"区では新時代の品川に向けまして、多様化する区民の価値観やニーズを的確に把握することが非常に重要だと考えております。小規模な用地に関しましても、どういった形で区民の方の声を聴いていくかということも、引き続き積極的に検討してまいりたいと思います。","id":"exchange-074"},{"speaker":"せお委員","kind":"質問・要望","question":"ギネスに挑戦というお話もありましたが、そういったところは全庁挙げて検討できるところだと思っていますので、そういった活発な活用をぜひお願いしたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"こんの委員","kind":"質問","question":"地域振興経費ですけれども、これは町会・自治会加入に関することをお伺いしてまいりたいと思います。これまで加入していたマンションや集合住宅が、町会を脱退をしますというようなことがあると伺いました。","respondent":"川島地域活動課長","answer":"それから伴走型支援という形で、新たな支援体制、専門のコンサルタントを町会に派遣するという形の支援を半年にわたって実施いたしました。","id":"exchange-076","title":"町会・自治会支援"},{"speaker":"こんの委員","kind":"質問","question":"今取り組まれていることのご紹介がありました。半年ですか、この伴走支援によって加入促進についての進み具合というものがどうなっていったのか、その辺の状況を説明するよう求めました。","respondent":"川島地域活動課長","answer":"なかなかこの半年の支援で全て解決するというわけではございませんが、１つの町会におきましては、住民アンケートを実施しまして。この課題解決支援、伴走型支援という中では、この取組のほうも参考にしていただければと思っているところです。","id":"exchange-077"},{"speaker":"こんの委員","kind":"質問","question":"それから町会との接点というのでしょうか、コミュニティとか、意外と形成しにくい状況もあると。５町会ですか、それから併せてお聞きしますけれども、そうしたものの１つの活動かと思います。","respondent":"川島地域活動課長","answer":"伴走型支援の実施の件数、５町会を支援させていただければと思いますが、それから成果のほうも見ながら検討していければと考えています。こちら１３地域センター管内ごとに組織している会議体という形になっておりますが、健康体操教室、そういったイベントを実施しています。","id":"exchange-078"},{"speaker":"こんの委員","kind":"確認","question":"一応５町会を予定されているということと、事例集ですか、その接点をどう結んでいくかというところの支援を引き続きよろしくお願いいたします。ぜひこのようなものも研究されてはどうでしょうかというところですけれども、いかがか尋ねました。","respondent":"川島地域活動課長","answer":"電子回覧板の情報、幾つか先行実施したところの自治体の状況等は確認しています。１つ、もう少し先行で実施したところの様子を見する、それから研究をさせていただければと思ってあります。","id":"exchange-079"},{"speaker":"こんの委員","kind":"確認","question":"こうしたものもこれからどんどん必要になってくるかなというところですので、よろしくお願いいたします。よろしいかどうかの確認と、２００町会の自治会、その辺はどのようにつかんでいらっしゃるのか状況を説明するよう求めました。","respondent":"森田生活安全担当課長","answer":"団体支援のところですけれども、自主的防犯団体活動助成金も含めまして、防犯カメラの設置で予算を組んでいるところです。なかなか進んでいないとか、こちらから足を向けていきまして、ご説明をさせていただいているところです。","id":"exchange-080"},{"speaker":"こんの委員","kind":"質問・要望","question":"足を運んでくださっているということですけれども、まだまだ、ここにもあそこにもつけたいというようなご要望も受けております。ですから、いわゆる１台にかかる費用が決まっておりますので、その辺のところが要望です。","respondent":"森田生活安全担当課長","answer":"他の区に比べまして、私どもの助成金のほうは１２分の１１ということで、多く補助をしておりますので、できる限りの助成はして、対応してまいりたいと考えています。","id":"exchange-081"},{"speaker":"松澤委員","kind":"提案","question":"こうした結果から、調査報告書の８４ページ、まとめの部分に、今後の支援施策というものが提案されておりました。今年度は５町会でやっている、そして伴走型を横展開してほしいということは、５町会から始まりますとの意見を述べました。","respondent":"川島地域活動課長","answer":"伴走型支援の対象町会数ですが、取りあえず、令和５年度は令和４年度と同じ５町会で実施させていただければと考えています。その支援の状況を見ながら、しっかり町会・自治会の皆様の悩み事に寄り添って、解決に向けてその支援をしていくという覚悟です。","id":"exchange-082"},{"speaker":"松澤委員","kind":"質問","question":"先ほどは横ばいということで、多分町会・自治会に関して、品川区の行政というものは大変多い支援をしていただいております。そこが弱くなってしまうと加入率が衰退してしまうのか、その辺答えづらいかもしれませんが、その辺の感覚というものを説明するよう求めました。","respondent":"川島地域活動課長","answer":"私どもとしましては、こちらいろいろな下支えの支援をしてきて、何とかこうなっているというような認識もありますので、引き続き支援の手を緩めることなく、施策を進めていければと思ってあります。","id":"exchange-083","title":"町会・自治会支援"},{"speaker":"松澤委員","kind":"質問","question":"ＮＰＯ法人と区の連携というものは、現在どのような状況になっているのか教えてください。区で活躍するＮＰＯ法人の状況を区はどの程度把握しているのか、２点説明を求めました。","respondent":"川島地域活動課長","answer":"このアンケートで、区との協働を希望する団体についてはヒアリング調査を実施して、行政との連携の推進に努めたいと思ってあります。アンケートを回答していただいたところはほとんど、品川区と何らかの形で連携したいというような意向を示していたところです。","id":"exchange-084"},{"speaker":"松澤委員","kind":"質問","question":"区民に周知する期間というのですか、広報、例えば町会の好事例というものは先日出していただいたではないですか。例えばこのような協働の部分でしっかり頑張っていますよという部分をどこかで広報する、そういったことというのは区でやっているのか尋ねました。","respondent":"川島地域活動課長","answer":"２月２５日に行われました、それから活動状況も定期的にご紹介するニュースのようなものを発行しておりますので、そういった形で活動のお手伝いはしています。","id":"exchange-085"},{"speaker":"松澤委員","kind":"質問","question":"延長が決まりまして、もうその期間も近づいてきたと思いますけれども、その間どのような活動が行われてきたのでしょうか。今後の予定を説明するよう求めました。","respondent":"辻スポーツ推進課長","answer":"新しいボランティアのところで活躍してくださいということで解散する予定だったのですが、それも１年過ぎまして、あと１年です。来年度同じように、そういったネットワークの紹介等を行いつつ、ボランティアに従事していただくというような予定をしております。","id":"exchange-086"},{"speaker":"松澤委員","kind":"質問・要望","question":"ですから、地域のボランティアリーダーの育成をしていく、これがボランティアレガシーの継続になっていくかと考えています。そういった部分を品川区でぜひフォローしてほしいと求めましたが、ご見解を説明するよう求めました。","respondent":"辻スポーツ推進課長","answer":"各スポーツ団体、私どももシティマラソンをこれから計画していますので、そういったところにご協力をいただくことも考えられると思います。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、１６７ページの旧荏原第四中学校活用方針検討、２１１ページ、区議会議員選挙執行費に関わって、投票権の保障を求めて質問をします。いかがか尋ねました。","respondent":"佐藤企画調整課長","answer":"旧荏原第四中学校跡地の活用検討に関するご質問です。区民ニーズを踏まえた区有施設の整備の検討というところで、ワークショップを開催したり、区民のご意見をお伺いしていろいろと検討していきたいです。","id":"exchange-088"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ今要望したもの、今言われました予算にも１,１００万円盛り込まれ、プレス発表されました。基本方針策定委員会の人数が１１名となっていますが、地元の方は何人参加をするのか、伺います。","respondent":"佐藤企画調整課長","answer":"１点目のワークショップの内容ですが、私どももできるだけ多くの区民の方、一般に公募をかけて参加を募っていきたいというところです。２点目の検討委員会のメンバーですが、学識経験者２名程度と、しっかりと運営をしていきたいと考えております。","id":"exchange-089"},{"speaker":"のだて委員","kind":"質問・要望","question":"地元の方に参加していただいて、その住民要望を反映していっていただきたいと思うのですが、そこを伺いたいと思います。このワークショップ、何回開催をしていくのか伺います。","respondent":"佐藤企画調整課長","answer":"１点目のアンケートの実施に関しましては、アンケートがいいのか、違う形がいいのかも含めて検討してまいります。大体２０人ぐらいの方で１回というところで、複数回やっていきたいと考えておりまして、応募状況を見ながら柔軟に考えていきたいと考えています。","id":"exchange-090"},{"speaker":"のだて委員","kind":"質問・要望","question":"それも踏まえていただきながら、策定委員会のほうでも、この住民要望を反映できるようにしていってほしいと求めました。この旧荏原第四中学校跡地のワークショップでも、分野に応じて分科会を設置して検討すべきだと思いますが、いかがか尋ねました。","respondent":"佐藤企画調整課長","answer":"分科会設置に関するご質問です、こちらに関しましても、ワークショップで出たご意見の状況や、検討委員会のメンバーの方々のご意見等を踏まえて、検討していきたいと考えております。","id":"exchange-091"},{"speaker":"のだて委員","kind":"質問・要望","question":"住民要望をしっかりと反映した検討を行って、住民に愛される活用をしていっていただきたいと、これは要望しておきたいと思います。体の不自由な人や、投票所に行くことが困難な人、こうした人の投票権を保障することが必要だと思いますが、いかがか尋ねました。","respondent":"鈴木選挙管理委員会事務局長","answer":"ご質問の、投票に行くために支援が必要な方への対応ということだと思いますが、現在選挙の制度の中で、郵便による投票という制度があります。","id":"exchange-092"},{"speaker":"のだて委員","kind":"質問・要望","question":"対応もぜひしていただきたいのですが、私が伺ったのが、区としての認識として、投票権を保障することが必要だと考えているかどうか伺います。","respondent":"鈴木選挙管理委員会事務局長","answer":"選挙管理委員会の大きな職務の１つに、ご指摘の投票権の確保、またはその機会の確保ということがありますので、当然、区の選挙管理委員会としてもそのことは重要に考えております。","id":"exchange-093"},{"speaker":"のだて委員","kind":"質問・要望","question":"そこでまず郵便投票の対象が、今要介護５や、障害に応じてですが、障害者手帳１級から３級などの方ということで、とても限定されています。その対象拡大を国に求めてほしいと求めましたが、いかがか尋ねました。","respondent":"鈴木選挙管理委員会事務局長","answer":"その関連法令等で定められているものですので、区で裁量を持って変えることはできないものです。そのような機会を生かして、国に意見、要望を上げたいと考えております。","id":"exchange-094"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひどこでも、どの投票所でも同じ支援が受けられるようにしてほしいと求めましたが、いかがでしょうか。どういった研修などをやっているのか、マニュアルなど作成していくということが必要ではないかと思うのですが、いかがか尋ねました。","respondent":"鈴木選挙管理委員会事務局長","answer":"障害のある方の支援団体等で行っている選挙公報の作成や模擬投票に関しては、実施の状況を把握しておりません。事前に実施をした上で従事するようにということで徹底はしておりますが、その状況によって、多少ばらつきが出てしまうということは認識しています。","id":"exchange-095"},{"speaker":"のだて委員","kind":"質問・要望","question":"期日前投票のほうは業者の方がやっているということなので、それはしっかりと対応できるようにしてほしいと求めました。代理投票などできるということも周知していくことが、投票権保障にもなると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"},{"speaker":"木村委員","kind":"質問","question":"全体的に増えているのかどうか、なぜこの二十何億円が増えたのか、それとも幾つかの事業に集中しているのでしょうか。それも説明するよう求めました。","respondent":"黒田財政課長","answer":"令和５年度の総務費では、新庁舎建設のために基金の積立てを行っておりますので、そういった意味で、当初予算が伸びているというような状況です。","id":"exchange-097"},{"speaker":"木村委員","kind":"質問","question":"４０周年からお聞きをいたしますけれども、まず最初に、この予算の内容をお聞かせください。その理由もついでに説明を求めました。","respondent":"大澤広報広聴課長","answer":"区民憲章板は区内に７０基、しながわ百景はそれぞれの箇所に案内板がありますので、その清掃、また、破損があった場合には修理を行っております。記念事業を実施したため、令和５年度におきましては、予算額としては減少しているものです。","id":"exchange-098"},{"speaker":"木村委員","kind":"意見","question":"今度はこの区民憲章、今お話もありましたけれども、区民憲章４０周年ということでありました。記念事業に対する区民の皆さんの反応、そのようなことに対して何か感じるようなことがあるのかどうか、説明を求めました。","respondent":"大澤広報広聴課長","answer":"さらに区民憲章板を巡るスタンプラリーを実施しております。区としましても、区民憲章に込められた思いを伝える大切さを再認識したところです。","id":"exchange-099"},{"speaker":"木村委員","kind":"質問・要望","question":"次に、しながわ百景ですけれども、これはいつ、どのようにして活用してきたのでしょうか。どのようなところ、また、どのような部分をリニューアルしたのか尋ねました。","respondent":"大澤広報広聴課長","answer":"リニューアルの理由ですが、しながわ百景を選定した当時から３０年がたちまして、時間の経過とともに消えてしまった風景もございました。そのために、新しく生まれた風景を加えまして、再度区民の方による投票を行い、その結果、１０余りの風景の入替えを行ったものです。","id":"exchange-100"},{"speaker":"木村委員","kind":"質問・要望","question":"これは品川区民だけのことなのか、それとも他区からもそのことを見ることができるのかどうか、これはどのようになっているのか、お聞かせください。高齢者が大変多いと思うのですが、一応若い方も大変興味があるのかどうか、そのようなこともお聞かせをほしいと求めました。","respondent":"大澤広報広聴課長","answer":"トーキョーさんぽの動画は、これまで１万８,０００回ほどの視聴回数となっております。中には、ぜひ行ってみたいというコメントもあることから、区外の方へのＰＲにもなっていると考えられると認識しています。","id":"exchange-101"},{"speaker":"木村委員","kind":"質問・要望","question":"ぜひとも１人でも多くの方々に視聴をしていただいて、品川のよさを分かってほしいと求めました。本区のこの花に対しての気持ちは、どのようなお考えで平和の花壇を作ったのか、お聞かせをほしいと求めました。","respondent":"古巻総務課長","answer":"しながわ平和の花壇ですけれども、この提案を受けて、平成２７年度から平成３０年度にかけまして設置をさせていただいたものです。昨年の夏には、ウクライナへの支援というような意味合いを込めまして、ウクライナの国の花でありますヒマワリの植栽も実施をさせていただきました。","id":"exchange-102"},{"speaker":"木村委員","kind":"質問・要望","question":"この予算でどのような対応を行っているのでしょうか。令和４年度もほぼ同額の予算でしたけれども、令和４年度の結果もまたお聞かせをほしいと求めました。","respondent":"古巻総務課長","answer":"消毒液でありますとか、マスクでありますとか、そういったものの購入に充てているものです。５月以降５類への移行というようなことが言われておりまして、令和５年度につきましても、予算を編成させていただいたものです。","id":"exchange-103"},{"speaker":"木村委員","kind":"質問・要望","question":"そして令和５年度は山北町６２２万円余、早川町が１８６万円余ですけれども、令和４年度の予算から早川町は減額しております。この減額の原因はコロナが影響しているのかどうか、お聞かせをほしいと求めました。","respondent":"古巻総務課長","answer":"早川町につきましては、平成２年の４月ということで、それぞれ三十数年の日付がたっているです。必要な経費ということで、全体的に精査をしながら予算を編成させていただいたですので、そのような結果ということでご理解いただければと思います。","id":"exchange-104"},{"speaker":"木村委員","kind":"質問・要望","question":"どちらにしても、区民の日頃の疲れを癒やす場所、そのような場所として、品川区の財産として、またしっかりと管理をしてほしいと求めました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"},{"speaker":"小芝委員","kind":"質問","question":"１８９ページの地域センターの改築に関連しまして、１９９ページ、歴史館運営費についてお伺いします。そこでお聞きしますが、この地域センターに携帯電話ないしスマートフォンが配備され始めたいきさつについて、教えていただけばと思います。","respondent":"川島地域活動課長","answer":"あまり過去の部分では分からないのですけれども、平成２１年には１３地域センターに１台ずつ、ガラケーと言われるような携帯電話を配備しています。","id":"exchange-106"},{"speaker":"小芝委員","kind":"質問","question":"ですから、この地域センターとの連絡手段が残されているようであれば、これほど地域の方々にとっても心強いものはないと思います。先ほどお祭りの話も出ましたけれども、その時々において使うものなのか、その辺教えてもらってもよろしいか尋ねました。","respondent":"川島地域活動課長","answer":"誰か職員が１人持っていたりということで、緊急連絡用ということですので、できれば常に身につけていていただければです。","id":"exchange-107"},{"speaker":"小芝委員","kind":"質問","question":"先ほど課長もおっしゃっていたと思いますが、あまり厳格な基準を設けずに、これからもぜひ見守ってもらいたいと思います。もう今の時代になくてはならないものですので、ぜひ積極的に利用してもらいたいという立場ですが、区の見解について教えてほしいと求めました。","respondent":"川島地域活動課長","answer":"災害時等も、緊急時等もですけれども、連絡手段というものは必要です。１台スマホ等があることによって、非常に役立っていると思いますので、しっかり積極的に活用していきたいと思ってあります。","id":"exchange-108"},{"speaker":"小芝委員","kind":"質問・要望","question":"続きまして、品川歴史館の運営について伺います。取組、一時的なものかどうかも含めて、教えてほしいと求めました。","respondent":"山崎文化スポーツ振興部長","answer":"現在ホームページのほうで、リアルな展示の実体験ができないということで、ご案内のバーチャルツアーと銘打ってやっております。コロナ禍だからこそ、こういった発想が逆に展開の動機づけになったかなというところでやらせていただいているところです。","id":"exchange-109"},{"speaker":"小芝委員","kind":"提案","question":"私も再三一般質問等で提案をさせていただきましたが、板垣退助など、歴史の偉人をぜひ取り上げてもらいたいと思います。例えば伊藤公の命日に当たります１０月２６日に、その辺りどのようにお考えか、説明を求めました。","respondent":"山崎文化スポーツ振興部長","answer":"物流の拠点品川という１つの大きな捉えで、リニューアル後常設展示のほうは、しっかりそれを分かっていただくような展示を１つ考えています。","id":"exchange-110"},{"speaker":"小芝委員","kind":"質問・要望","question":"その地蔵にランドセルをしょわすという物語でございまして、これは今でも７月になりますと、八王子にあるお寺で供養祭が行われているそうです。そういった歴史も、ぜひ歴史館の中で取り扱ってほしいと求めましたが、お考えをほしいと求めました。","respondent":"山崎文化スポーツ振興部長","answer":"そういった書物、絵本の展示なども、そういったところでしたら可能かななどというところも思った次第です。様々工夫しながら、区民の皆様に愛される歴史館として、しっかり取り組んでまいる所存です。","id":"exchange-111"},{"speaker":"たけうち委員","kind":"質問","question":"１７５ページの非核平和都市品川宣言事業、１８１ページ、庁舎管理費、１８３ページ、庁舎計画費で伺います。非核平和都市品川宣言２０周年の記念事業として、これはいつ頃開けるのか、お聞きしたいと思います。","respondent":"古巻総務課長","answer":"当時の区内の小学６年生の各クラスによる、平成１６年度ですけれども、そういったものが入っているという記録になってあります。開けるのは５０周年記念事業の際ということですので、２０周年からすると３０年後という設定で埋めたものと認識をしております。","id":"exchange-112"},{"speaker":"たけうち委員","kind":"質問・要望","question":"広場の改修工事で予定より１０年早く返還を呼びかけてやったのですが、３００枚ほど返還されたのですが、１,４００枚が残念ながら残ってしまった。１２年後、タイムカプセルを開封していくのか、お知らせをほしいと求めました。","respondent":"古巻総務課長","answer":"１２年後ということでございまして、５０周年に向けて、しっかりタイムカプセルの開封ができるような形での引継ぎをしています。","id":"exchange-113"},{"speaker":"たけうち委員","kind":"提案","question":"４０周年、２年後にしていったらどうかなと考えていますが、いかがでしょうか。そうした方々の発信もいただいたらどうでしょうかというご提案をさせていただいた、そうしたことも４０周年、いかがか尋ねました。","respondent":"古巻総務課長","answer":"今から２年後ぐらいになろうかと思いますけれども、様々な形で検討はする必要があるかなと思っています。やり方につきましてはこれからの検討になろうかと思いますけれども、様々、取組については考えてまいりたいと考えています。","id":"exchange-114"},{"speaker":"たけうち委員","kind":"質問・要望","question":"次に、庁舎管理費と庁舎計画費ですけれども、本庁舎や第二庁舎にタイムカプセル的なものが埋まっているのでしょうか。定礎という言葉の意味を教えてほしいと求めました。","respondent":"東野経理課長","answer":"定礎ですが、こちらは、建築工事の開始を記念しまして、建物の安泰を祈るために行われる定礎式というものが、明治時代から日本に入ってきました。本庁舎のほうは見つけることができませんでした。","id":"exchange-115"},{"speaker":"たけうち委員","kind":"質問・要望","question":"もしくは定礎で定礎箱に何か入れる等も、検討はこれからだと思うのですが、検討いただきたいと思うのです。個人情報のこともありますが見られるようにするとか、何かいろいろな工夫があるのかなと思うのですが、その辺のお考えをお聞きしたいと思います。","respondent":"大友新庁舎建設担当課長","answer":"今のところは考えていないところではありますけれども、定礎箱の中に建築図面とかを入れるほか、建設当時をしのぶものを入れることも多々あります。そういうこともありますので、委員のお話でいただいたことも踏まえながら、今後検討してまいりたいと考えております。","id":"exchange-116"},{"speaker":"たけうち委員","kind":"質問・要望","question":"区民の方のそういった賛同をいただいたということのあかしとしても、また品川区の発展のためにも、そういったものを検討ほしいと求めました。要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-117"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"財源計画の起債について今までもお伺いしてきましたけれども、公用施設、つまり庁舎の整備には起債が認められないのではないかとお伺いしました。そこで、この中の「庁舎に係る起債対象事業」とは具体的にどのような事業なのか、教えてほしいと求めました。","respondent":"黒田財政課長","answer":"実際にどの部分が起債対象事業になるかということにつきましては、起債をする段階で、協議先であります東京都と協議することになろうかと考えています。","id":"exchange-118"},{"speaker":"高橋（し）委員","kind":"意見","question":"この１事業の内容は、今言いましたけれども、この事業１つしか起債できないと読めるのですが、その点について。それから、もしそれが可能だとすると、約４００億円のうちのどのぐらいのパーセンテージになるのか、お尋ねしますとの意見を述べました。","respondent":"黒田財政課長","answer":"先日も、基本計画ができたところで東京都の担当所管と打合せをしまして、そういったやり取りをしています。","id":"exchange-119"},{"speaker":"高橋（し）委員","kind":"質問","question":"地方財政計画のその他の事業ということですね。そうすると、それのどういう事業で起債ができるかということを、東京都とお話ししているのか尋ねました。","respondent":"黒田財政課長","answer":"いわゆる庁舎というのですかね、そういったものについては、地方財政法上の規定の中で起債ができるとなっています。庁舎の中に、そういった意味では、庁舎として機能するものについては一般事業債で起債の対象になると確認しているものです。","id":"exchange-120"},{"speaker":"高橋（し）委員","kind":"質問","question":"ですから、緊急防災・減災事業債については先ほどの１つの事業の中にあって、全体の床面積のどれだけかとかで起債をしていける。私、課長に比べるとなかなか理解が悪いもので、もう一度お願いしたいのですが。","respondent":"黒田財政課長","answer":"総務省の地方債同意等基準でも庁舎という表現が出てまいりまして、そこの部分は庁舎ではありませんから起債の対象にならないというようなところは、起債の対象になると考えています。","id":"exchange-121"},{"speaker":"高橋（し）委員","kind":"質問","question":"では、今のご説明だと、お店とか、そういう行政機能に関わらないところに関しては、先ほどのお話にあった、地方財政計画のその他の事業で起債できるというお答えでよろしいか尋ねました。","respondent":"黒田財政課長","answer":"いわゆる地方債同意等基準の中では、「一般事業については、地方単独事業のうち他の事業区分に属する事業の対象とならない事業を対象とするもの」と記載がありますので、そこに庁舎建設が当たるというものです。","id":"exchange-122"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、そこが庁舎建設に当たるというお話でしたが、それは、約４００億円の中のどれぐらいの割合でできるのかということを、当然いろいろ検討されながら、今お話しされているのではないかと思うのですが、いかがか尋ねました。","respondent":"黒田財政課長","answer":"起債の充当率は、一般事業の場合は７５％が上限ということになりますから、その建設費の７５％までが上限で起債できると。ただ、制度の中の７５％が充当率の上限ですので、どこの部分に起債をしていくかということが決まってくるのではないかなと考えています。","id":"exchange-123"},{"speaker":"高橋（し）委員","kind":"質問","question":"勉強させていただいて、お尋ねしたいと思います。７５％がマックスということなので、東京都とか国は置いておいて、ああいう基金の積立て計画を立てていらっしゃるのか尋ねました。","respondent":"黒田財政課長","answer":"建設事業費は基本構想の中で約４００億円となっておりまして、その中で自己資金として１２０億円という形ですが、充当率が７５％ということですので、そのほかに、分担があれば分担金を差し引いていくというところで、そういった計画を立てているです。","id":"exchange-124"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"新庁舎整備に備えてしっかりと財源確保をしてほしいということは思っていて、私は質問させていただいているので、そういうのではなくて着実に。大変な金額を進めていくわけですから、そのために、今のご説明だと、区民の方に説明しても、私、説明し切れないところがあるので、また勉強します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-125"},{"speaker":"鈴木（博）委員","kind":"質問","question":"現在の品川区の広報活動についてお伺いいたします。その評価等は行われているのか尋ねました。","respondent":"大澤広報広聴課長","answer":"ふれあい掲示板等７００か所でのポスター掲示や、町会・自治会の回覧板によるチラシなど、紙媒体による情報発信も行っているところです。今年度実施しました世論調査におきましては、回覧板、ＳＮＳの順となっております。","id":"exchange-126"},{"speaker":"鈴木（博）委員","kind":"質問","question":"アナログの両面で情報発信を行っているとのことですが、コロナ禍以降、どのぐらいの情報発信がなされてきたのでしょうか。ご説明をお願いいたします。","respondent":"大澤広報広聴課長","answer":"ホームページにおきましては、コロナに関する新規ページを１２回開設しております。プレスリリースは１２９回行っておりまして、区民の皆様が必要な情報を手に入れられるよう、複数の手段を組み合わせて発信してきたところです。","id":"exchange-127"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そのようなフェイクニュースに関して、区はどのように捉えているのでしょうか。ご説明をお願いいたします。","respondent":"大澤広報広聴課長","answer":"様々なものがフェイクニュースと言われていると思いますけれども、受け手がその情報によって何らかのデメリットを負う状況になることが、大きな問題となるという認識です。","id":"exchange-128"},{"speaker":"鈴木（博）委員","kind":"意見","question":"２０１６年に世界的に発生した偽ニュースの氾濫と、事実かどうか分からない情報の代名詞として、フェイクニュースという言葉が使われ始めました。このような状況の中で、フェイクニュースに対する公的情報の提供者である品川区の現在の対応について、ご説明をお願いいたしますとの意見を述べました。","respondent":"大澤広報広聴課長","answer":"フェイクニュースに対しての区の対応ですが、それに対する正しい情報や、区としての考えを発信する場合もあります。昨今は、区がそれと認識しないままに、これは十分留意をすることが必要になってくると考えています。","id":"exchange-129"},{"speaker":"鈴木（博）委員","kind":"質問","question":"全くご説明のとおりだと思うのですが、フェイクニュースに振り回されないためには、情報リテラシーが非常に大切だということが言われております。区として、情報リテラシーに関して何か取組などを行っているのか尋ねました。","respondent":"大澤広報広聴課長","answer":"区では現在、学校において、情報リテラシーについて学習していると聞いております。ただ、今後は子どもだけではなく、その上の世代にも、情報リテラシーについて普及啓発していく必要があるということは、今、感じているところです。","id":"exchange-130"},{"speaker":"鈴木（博）委員","kind":"質問","question":"日系社会学者のタモツ・シブタニ氏は『流言と社会』で、危険なデマが拡大していくこともあると述べています。情報加害者に翻弄されないように区民を守るために、今後の情報発信をしっかりとするようにお願いして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-131"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私からは、１７８ページの人事管理費のところから、保健師の定数増と、それから、会計年度任用職員の待遇改善を求めて質問をしたいと思います。２０２１年の１０月の決算特別委員会で私が伺ったときは、１２名足りないということでしたが、教えてほしいと求めました。","respondent":"崎村人事課長","answer":"認識としては、なるべく早く２３区の平均に近づけるように、これからも進めていきたいと考えております。２３区の平均ですとか人口動向、そういったところも含めて、今後も採用については続けていきたいと考えております。","id":"exchange-132"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"だからこそ、日本看護協会で「自治体保健師の人材確保ガイド」を出されているのは、ご覧になられているでしょうかということを伺いたいと思います。早急に、１４名も足りないというところの解決には向かっていかないのではないかと思うのですが、伺いたいと思います。","respondent":"崎村人事課長","answer":"特に保健師を所管します健康課などとも情報交換を行いながら、委員がおっしゃいましたような、検討してきたところです。１４名足りないというところで、それはそれでまた現場の負担になってまいりますので、少しずつ強化を図っていく必要があると認識しております。","id":"exchange-133"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そして、継続的に増員してほしいと求めました。平成２５年の指針の中に、統括保健師というのは、品川区ではどういう配置の状況になっているのか伺います。","respondent":"崎村人事課長","answer":"なかなかお答えしづらいのですけれども、３保健センターですとか保健師の人材育成等を担っているというところで、その方が実際に動かれているのかなと考えております。","id":"exchange-134"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それを充実させるためにも、２３区で２２位というこの状況を、一日も早く改善を求めたいと思います。１つは、３年目の壁ということで今年言われていると書かれているのですが、品川区は上限回数をどう定めているかというのを１つ伺いたいと思います。","respondent":"崎村人事課長","answer":"委員のお話にありました公募によらない再度の任用というのは、区では実施をしておりませんので、上限回数等も定めているものではございません。","id":"exchange-135"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それから、退職金もない。職員の地域手当というのは賃金の何％になるのかも伺いたいのと、地域手当が会計年度任用職員についていない、その理由についても伺います。","respondent":"崎村人事課長","answer":"地域手当につきましては、常勤職員の場合は給料月額の２０％ということで、設定されております。会計年度任用職員については、報酬額を決定する際に、地域手当も含めて算定しています。","id":"exchange-136"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それで、今回、４月に賃上げがされると聞きました。賃上げがされると言いながら賃上げがされない職種というか、ところもあるのですが、それはなぜなのかについても伺います。","respondent":"崎村人事課長","answer":"会計年度任用職員の報酬額の改定をする予定でございまして、１つは、報酬額についても引上げになる職があります。制度開始から３年が経過いたしまして、民間との人材確保競争などもございまして、募集をしてもなかなか応募が集まらないような職がございました。","id":"exchange-137"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そういった方も決して高いわけではないと思うのです。物価高とか負担増が大きい中で、ぜひともそういう方も含めて賃上げをお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-138","title":"町会・自治会支援"},{"speaker":"若林委員","kind":"質問・要望","question":"その真意が伝わっているか否かを確認する、そういったやり取りの作業も、今後必要になってくるのではないかなと思います。一つの方向を目指して一丸となってやっていく、こういった取組についても、ぜひお考えをお聞かせほしいと求めました。","respondent":"山崎文化スポーツ振興部長、佐藤企画調整課長","answer":"１００を超える活力ある商店街、品川区の持つそういった日常の魅力をしっかり捉えて発信してまいるという視点で、展開をしてまいりました。来訪者が区民と触れ合って交流することで繰り返し訪れて、楽しい観光都市を目指すということで… 施政方針で区長から、ここに向かって来年度、しっかり職員が各施策に取り組んでいかなければならないです。","id":"exchange-139"},{"speaker":"若林委員","kind":"質問・要望","question":"これについて、時間の関係があるかもしれませんけれども、ご答弁ほしいと求めました。なりませんけれどもということを私が発言すること自体がもうおかしいわけであって、そういう意味では、ご答弁を再度ほしいと求めました。","respondent":"山崎文化スポーツ振興部長","answer":"外から来るイベントが多いのか、中の方々が多いのかというような緻密な数字も持っておりましたので、よろしくお願いいたします。大変すみませんでした。","id":"exchange-140"},{"speaker":"渡部委員","kind":"質問","question":"私に話された人は、もういいよ、どうせ使わないからと諦めてしまっている人もいるのです。できないところでできるようにしてほしいなと思いまして、そういう意味で件数も聞いているのですが、説明を求めました。","respondent":"吉野戸籍住民課長","answer":"数値のほうが、今、持ち合わせておりませんでして、確かに一定数、区民の方からの問合せがありまして、実際には一定数の方が窓口にいらっしゃいます。一応マイキーＩＤなど、そういったところに関しましては、毎日やはり一定数、約１００人程度の方がいらっしゃっております。","id":"exchange-141"},{"speaker":"渡部委員","kind":"質問","question":"１３地域センターでパスワードの照合ですとか、やって差し上げてほしいなというところがあって、少し時間を取らせていただきました。スポーツ協会のホームページを見ると、何か記念誌は作るみたいなことは書いてあったのですが、その辺を説明するよう求めました。","respondent":"辻スポーツ推進課長","answer":"来年度のスポーツ協会助成金の中で、３０周年記念事業ということで２００万円を計上しております。山下さんが来たときほどではないですが、講演会やいろいろな催しというものも準備していると聞いております。","id":"exchange-142"},{"speaker":"渡部委員","kind":"質問・要望","question":"では、例えばそういうニュースポーツの３０周年の記念大会とか、スポーツ協会と一緒になって。どんどん参加してもらえるような形のイベントも、ぜひ検討していただきたいと思うのですが、いかがか尋ねました。","respondent":"辻スポーツ推進課長","answer":"委員のご指摘のようなニュースポーツ、モルックは先日、体験会をやりましたら、非常にたくさんの方が喜んで集まっていらっしゃいました。３０周年の記念事業ですが、内容について決めてまいりますので、考えていきたいと考えています。","id":"exchange-143"},{"speaker":"渡部委員","kind":"質問・要望","question":"そういう人が普通に足を運べるようなイベントを、これからもいろいろ考えて増やしてほしいなというところで、これは要望します。どーんとやって、できたものが出来上がりとなるのですよということになるのか、その辺の考え方を説明するよう求めました。","respondent":"山下新庁舎整備課長","answer":"建物の形状、ＪＲの部分については灰色の形でお示しをしているところで、それは双方調整の上でこのような形になっているものです。今般予定しております組織改正の中では、課の中で連携を取りながら、それぞれ調整に臨んでまいりたいと考えています。","id":"exchange-144"},{"speaker":"渡部委員","kind":"質問","question":"みんな歩くというのはどういうことかといったら、今まで歩いてもらっていたところを歩かなくなってしまうわけですよ。あり方検討会というのですか、正しいかどうかは分からないけれども、その辺の考え方。","respondent":"山下新庁舎整備課長","answer":"どちらがどっちということではなくて、この地域一帯という捉え方をされるということは、ご指摘のとおりと思います。いわゆる大井町駅周辺のまちづくりを進めているところがありますので、大井一丁目ですとか、常に考えていく必要があるものと認識しています。","id":"exchange-145"},{"speaker":"吉田委員","kind":"質問・要望","question":"質問に関連して、情報をぜひ残していただきたいと改善を求めたところ、素早く対応していただいたことは評価をいたします。せめて選定された事業者ぐらいは情報として掲載していただきたかったのですが、それも難しいということなのでしょうか、まずそれを伺います。","respondent":"東野経理課長","answer":"令和３年度でいきますと２５０件ほどありますので、経理課内で行いまして、現在のような形で掲載をしているものです。そういったものが分かれば、所管のほうへご案内ができると考えておりますので、ご理解いただければと思います。","id":"exchange-146"},{"speaker":"吉田委員","kind":"質問・要望","question":"ただ、例えばどういう手続が必要なのか、誰でも、この契約についてどうなったのかというのを聞けば、窓口で特に手続なく聞けるのでしょうか。例えばメールでの問合せとか、何かそういうことは可能なのか、伺いたいと思います。","respondent":"東野経理課長","answer":"もう公表されている情報ということになりますので、その辺を踏まえた上で、所管のほうで対応が可能かと思われます。情報公開請求、また議員の皆様におきましては区議会事務局を通しての請求などもありますので、そういったものをご利用いただければと考えます。","id":"exchange-147"},{"speaker":"吉田委員","kind":"質問・要望","question":"では、一般の区民の方は、情報公開請求の手続を取らなければ駄目ということなのでしょうか。例えば東京都はＣＤで、１枚１００円で、かなりの分量が入りますので、そういう形で提供しているようですけれども、その辺についてはいかがでしょう。","respondent":"大澤広報広聴課長","answer":"現在、情報公開に関しましては紙媒体でのお返しとなっておりますが、ＣＤ等については今後の検討課題とさせていただきたいと考えています。","id":"exchange-148"},{"speaker":"吉田委員","kind":"質問・要望","question":"次に、１９５ページのしながわ観光大使関連事業について伺います。サンリオが、具体的な一つ一つの事業、個別協定書で一つ一つ合意しながら進めるという理解でよろしいか尋ねました。","respondent":"山崎文化スポーツ振興部長","answer":"委員のおっしゃられる理解で結構かと思います。基本的には、平成３０年４月１日に基本協定を締結しまして、毎年、変化がある部分については、年度協定的に個別協定を結んでいるです。","id":"exchange-149"},{"speaker":"吉田委員","kind":"質問","question":"では、基本協定は毎年結ぶように読めたのですが、そうではなくて、基本協定というのは１回で終わりということでしょうかね。つまり、シナモロールを品川区の観光大使として使ってもよいけれども、他の自治体が使っては駄目とは言っていないよという理解でいいか尋ねました。","respondent":"山崎文化スポーツ振興部長","answer":"事前申請し、許諾を得るということではありますが、品川区に対してのみ許諾を行うものではないという委員のご理解で結構です。１年ごとの自動更新で来ているよということと、それから、年度協定的に毎年やらせていただいているというご理解でお願いいたします。","id":"exchange-150"},{"speaker":"吉田委員","kind":"確認","question":"今回計上されている２,３４１万４,０００円はどんな事業を想定したものなのか、伺いたいと思います。しかも２回やったので、２回デザインが違ったと思うのですけれども、その辺についても伺いたいと思います。","respondent":"山崎文化スポーツ振興部長","answer":"それから、合計４１８万円がロイヤリティーとして、サンリオ側に区から支出をさせていただいている関係になります。所管で物理的に作成をする経費は、ロイヤリティーとは別の作成経費というものはありますけれども、そういったご理解でよろしくお願いいたします。","id":"exchange-151"},{"speaker":"吉田委員","kind":"質問","question":"さっき伺いましたか。もし、ざっくりとでもいいので伺えたら。","respondent":"山崎文化スポーツ振興部長","answer":"先ほどのロイヤリティーの４１８万円で、契約が平成３０年度からですから、約２,０００万円ということになります。","id":"exchange-152"},{"speaker":"吉田委員","kind":"質問","question":"それは基本ロイヤリティーだけですよね。何かその後、サンリオから、いや、それは個別の協定が必要でしょうと言われたものは、では、なかったということですか、この間。","respondent":"山崎文化スポーツ振興部長","answer":"そういう範囲でありましたら、その金額です。これはノベルティを作るということになりますので、例えば製作費の３０％をお支払いするとかという、個別のものは発生しています。","id":"exchange-153"},{"speaker":"吉田委員","kind":"質問・要望","question":"大分分かってきました。その事業に関係するところには、お金のことについては報告を出してほしいと求めましたが、その点についてはいかがでしょう。","respondent":"山崎文化スポーツ振興部長","answer":"全体の事業の金額の内訳として出てくるところですので、いろいろ表記については工夫なり、分かりやすく表現するというのも考慮したいなとは思っております。","id":"exchange-154"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"当然、議会に対してはどういうふうに説明していただけるのか、そのタイミングはどうなのかなということを確認させてほしいと求めました。それ以外に今、区の公有地として活用できる部分というのはどこかあるのかというのが、１つ確認です。","respondent":"大澤広報広聴課長、佐藤企画調整課長","answer":"区民アンケートですが、集計の結果につきましては、まずは議会に報告する予定です。その後、区長の記者会見や広報紙やホームページでの公表という順番になります。 ２点目のご質問の、都有地等の関係ですが、例えば東品川三丁目に品川消防署の出張所跡地があります。平成２９年３月当時に更地になったタイミングで、区から一応、今は都のほうでそういった駐車場を運用しています。","id":"exchange-155"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"東品川文化センターを直したばかりですから、その辺の別の場所の改築のときに使ってもらえると、一番ありがたいなと考えています。最初に私が聞いている中で、何か施策的に進捗があったのかどうか、この辺を説明するよう求めました。","respondent":"古巻総務課長","answer":"しながわ大学連携推進協議会などというものも立ち上げて、様々なこういう連携を進めてきていたところですけれども、現在に至っているところです。","id":"exchange-156"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それは十分な成果があると思いますので、この辺、引き続きまた研究してほしいと求めました。少し望みも高いかもしれませんが、うまくできれば、進めていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-157"},{"speaker":"石田委員","kind":"質問","question":"私は、１７８ページ、人権啓発費からパートナーシップ制度について、関連して性的マイノリティへの支援について伺いたいと思います。区はどのように受け止めているか、伺いたいと思います。","respondent":"加島人権啓発課長","answer":"今、委員からございました元首相秘書官の発言につきましては、既に首相のほうで対応がされているもので、一自治体としての見解は控えたいと思います。","id":"exchange-158"},{"speaker":"石田委員","kind":"質問・要望","question":"実施してほしいということを求めてきましたので、なぜ都の制度活用なのかということで、昨年の決算特別委員会でも中塚委員がお聞きしました。今後、区としてのパートナーシップ制度をつくっていくこともあるということなのか、伺います。","respondent":"加島人権啓発課長","answer":"それから、希望に応じて証明書にお子さんの名前を特記事項に記載できるなど、当事者の方の生活上の不便をより軽減できる内容となっております。そのため、区として東京都パートナーシップ宣誓制度の活用を進めていく、そのように決定いたしまして、プレス発表も行いました。","id":"exchange-159"},{"speaker":"石田委員","kind":"質問","question":"そうすると、現段階というよりは、ずっとこの東京都のパートナーシップ宣誓制度でいくと、区としてつくる考えはないということでよろしいでしょうか。伺います。","respondent":"加島人権啓発課長","answer":"先ほどの答弁と一部重なりますが、オンラインでの手続が可能であることはアウティングの防止にもつながります。子どもに関する困り事に対応するため、区としては東京都パートナーシップ宣誓制度の活用を進めてまいります。","id":"exchange-160"},{"speaker":"石田委員","kind":"質問","question":"そういうことでつくられているという声を伺いました。それが当事者の方々に伝わることが必要だと思うので、都に限らず区としてパートナーシップ制度をつくるべきだと思いますけれども、いかがか尋ねました。","respondent":"加島人権啓発課長","answer":"委員からもございましたとおり、都制度につきましては、既存のパートナーシップ制度の特徴が結集されていると考えております。都制度の活用を進めること、それが一番区民にとって利便性が高い、当事者の方の生活の不便を解消するのに近道だと考えました。","id":"exchange-161"},{"speaker":"石田委員","kind":"質問","question":"２０２１年の１２月に、第１７期品川区行動計画推進会議の報告書が出されておりまして、故に安心して暮らすことができる保障となります。都は制度の特徴が結集されているというのは分かるのですが、区の姿勢としてというところで伺っているので、そこを、答えるよう求めました。","respondent":"加島人権啓発課長","answer":"それから総合実施計画等、計画を通して区民、区内外に示されていると考えております。それから、そういったものを通して当事者の方のお悩みに寄り添う姿勢、区はそういったものを大事にしております。","id":"exchange-162"},{"speaker":"石田委員","kind":"提案","question":"ぜひそこはコメントするべきだし、またその周りを支える皆さんに示していくということになりますので、そこは重要ではないかなと思います。性的マイノリティ支援宣言として「レインボー宣言しながわ」が提案されていますけれども、これは今現在、検討はされているのか尋ねました。","respondent":"加島人権啓発課長","answer":"それから、「レインボー宣言しながわ」についての検討というところですけれども、様々な啓発の方向についての提言がございました。そういったものを、区としてこれから総合的に検討してまいります。","id":"exchange-163"},{"speaker":"塚本委員","kind":"質問","question":"トータルとして、令和５年度としてどれぐらいの手数料の支払いを見込んでいるのかということをお伺いします。まず、令和５年度においてどこまで進捗として進める予定となっているのかということで、お伺いをいたします。","respondent":"宮澤情報推進課長","answer":"高齢者のスマホ教室等を実施しているところですが、そちらの国の動きというのも注視しながら、活用できるものは活用していきたいです。","id":"exchange-164"},{"speaker":"塚本委員","kind":"質問・要望","question":"これは要望です。令和５年度の進捗を伺いましたけれども、歳出で計上されている区としてのシステム維持管理費、現時点で分かる範囲で教えてほしいと求めました。","respondent":"宮澤情報推進課長","answer":"現在、国はシステム標準化の基本方針の中でも、平成３０年度比で３割程度の削減をというところを見込んでおります。そこの改修にかかる経費というのが削減されるというのが見込まれているところでありますが、現状では申し上げることができない状況です。","id":"exchange-165"},{"speaker":"塚本委員","kind":"質問","question":"シビックプライドみたいなものというのですか、そういうものを醸成するという意味で、大変に意味のある企画だなとも思いました。これについてどういう、この名がついた由来があるのかというのをお聞きするのと、捉えているのかということをお伺いしたいと思います。","respondent":"山崎文化スポーツ振興部長","answer":"それぞれ伝承ということではありますが、平安時代に源氏の武将がというような、まつわる陣を敷いて旗を立てた。それから、旗岡八幡神社が源氏由来の神社なので、それの御前というようなことで認識しています。","id":"exchange-166"},{"speaker":"塚本委員","kind":"質問・要望","question":"いわゆる八幡太郎義家とかもあそこで旗を立てて、源氏前という由来になっているので、この「あつまれ！えばら」で源氏のパレード等も、ぜひこれはやれば盛り上がるのではないかなということで、ご答弁の時間がないので、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-167"},{"speaker":"渡辺委員","kind":"質問","question":"１６７ページ、公有地活用検討等と指定管理者制度経費、それと、２０１ページ、ジュニアスポーツの拡大・定着プロジェクト、この２点を伺います。この辺の内容を説明するよう求めました。","respondent":"佐藤企画調整課長","answer":"１点目の公有地活用検討等の６,０００万円に関しましては、より精緻な検討分析が必要になった場合の経費として、計上させていただいているものです。来年度、今年度と比較して対象事業者が大幅に増える関係で、経費が上がっているところです。","id":"exchange-168"},{"speaker":"渡辺委員","kind":"質問","question":"そのチェックで何かが判明する、それは改善すべきものだとか、そういうことはどれぐらいあったのかどうか。そういう中では、この調査項目にどんな問いがあるのか、そんなところを説明するよう求めました。","respondent":"佐藤企画調整課長","answer":"直接、所管のほうで対応する場合もありますし、企画調整課にまず第一報が入ることもあります。その都度、その立地でありましたり広さでありましたりタイミングによって、私どもで調整する場合もありますし、所管で直接対応する場合もあります。","id":"exchange-169"},{"speaker":"渡辺委員","kind":"質問","question":"それと、先ほどの利用者満足度調査のところで、先ほどのチェックのところはどういう方が担っているのかだけ教えてください。恐らく労務環境であれば社労士であろうし、この利用者満足度調査はどういう方が担っているか、そこも説明を求めました。","respondent":"佐藤企画調整課長","answer":"公共施設等総合計画の改訂というのを予定しておりまして、最新の人口動向、今後の行政ニーズ等を踏まえた計画の改訂を考えております。その中で、委員ご指摘のような用地の確保に関しましても、すみ分け等をはっきり、検討して記載する方向で考えていきたいと考えています。","id":"exchange-170"},{"speaker":"渡辺委員","kind":"質問","question":"それと、２０１ページのジュニアスポーツの拡大・定着も伺います。今日伺いたい中には、特に少年少女スポーツのニーズをどのように、地域スポーツの観点からで把握されているのか。","respondent":"久保田企画部長、辻スポーツ推進課長","answer":"そういったものにつきましては、専門のチームがそれぞれ編成を組んで、積極的に取り組んでやっているところです。民間も含めまして、区の施策に活用できないかということを検討しながら進めているところでありまして… スポーツ推進委員が様々活動する中で見聞きしたことから、その需要を把握することもあります。テレビやニュース等、そういったことでの話題からもニーズを把握するというような、様々な面でいろいろな興味の対象を見ているところです。","id":"exchange-171"},{"speaker":"渡辺委員","kind":"質問","question":"公有地の検討の制度の、今、見通しと決意を伺って、本当に期待していますし、本当にやりやすいように私たちも応援したいと思います。特にタブレット活用などとも連携ができたら最高かなと思うのですが、その点だけ制度面で説明を求めました。","respondent":"辻スポーツ推進課長","answer":"ダンスチーム、地域のイベントでも非常に多くの団体が出ておりまして、男女を問わず人気がある分野かなと考えています。どんなジャンルのダンスがいいかとか、そのあたりのことも、地域のニーズを捉えながらいろいろな展開をしていきたいなと考えています。","id":"exchange-172"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/756395?Template=document&Id=1166#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":128793,"voices":391}},{"id":"r05-20230310-3","meetingId":"r05-c-budget","date":"2023年3月10日","dateIso":"2023-03-10","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時３５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を169件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"江野下委員","kind":"質問・要望","question":"歳入でも質問されていましたが、どのようにして関わっていくことが必要なのか等、ご見解をお伺いします。誰もが生きがいを感じ、区民アンケートも実施するのですから、ヤングケアラーに関しての項目も入れていただけるように要望します。","respondent":"染谷子ども家庭支援センター長","answer":"アンケート調査の対象につきましては、該当する年齢の方、全員、全児童生徒向けに実施する予定でおります。教員向けのアンケート調査を実施してございまして、９２２人の先生から回答を得た中で、いると回答した割合が６.２％ということでしたので。","id":"exchange-001"},{"speaker":"江野下委員","kind":"確認","question":"一定数やはり品川区内にもヤングケアラーの児童生徒がいるということ、確認できました。コーディネーターも設置するとお伺いしましたが、一番相談しやすいのは、学校の先生などや、周りの大人や友人だと思います。","respondent":"染谷子ども家庭支援センター長","answer":"各家庭に関わる、学校の先生以外にも介護や医療などの様々な関係機関の職員が、ヤングケアラーからの相談を受けるということが想定されます。","id":"exchange-002"},{"speaker":"江野下委員","kind":"質問","question":"その理由と、可能であれば、区で小中学生に配付しているタブレットを活用することはできないのでしょうか。ほかの関係機関など、今もご答弁いただきましたけれども、連携についてはどうお考えか尋ねました。","respondent":"染谷子ども家庭支援センター長","answer":"相談の入り口に、どのような媒体などのツールが活用できるかということについては、今後も積極的に検討してまいりたいと考えております。連携に関する部分に関しましては、今年度から、支援における連携の在り方について議論を進めているところです。","id":"exchange-003"},{"speaker":"江野下委員","kind":"提案","question":"啓発や周知のためにも、区民が受講できる、ヤングケアラー支援研修みたいなものを行うのはいかがでしょうか。区のご見解をお伺いしますとの意見を述べました。","respondent":"染谷子ども家庭支援センター長","answer":"広く、研修を区民の方にしていくことにつきましても、検討させていただければと考えています。民間の団体によるヤングケアラーの学習支援等を協力しながら行っているような事例もありますので、十分検討してまいりたいと考えております。","id":"exchange-004"},{"speaker":"江野下委員","kind":"質問・要望","question":"地域全体で支援していく体制を要望いたします。本人とその家族の声を聞くしかないとは思いますが、区としても、声を聞き取り、寄り添った支援を要望して、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問","question":"２４１ページ、２６５ページ、時間のある限りお伺いをしていきます。最初に、中等度難聴児発達支援事業についてお伺いをいたします。","respondent":"松山障害者支援課長","answer":"私から、中等度難聴児発達支援事業についての目的、実績についてご説明いたします。令和３年度の助成人数が１５人、令和４年の１２月末で１０人の方に助成を行っております。","id":"exchange-006"},{"speaker":"新妻委員","kind":"確認","question":"それで、この予算についてなのですけれども、ただいま利用人数を確認させていただきました。１５人、こういう該当者がどういうふうにいらっしゃるのかという把握をどういうふうにされているのか、お伺いをしたいと思います。","respondent":"松山障害者支援課長","answer":"実態の把握が非常に難しいということになります。あるいは耳の大きさも成長とともに変化してまいりますので、ホームページや団体、それから相談員のほうに周知を図ってまいります。","id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"平成２５年の１１月から開始した事業で、これまで要望があった中で、品川区は東京都のこの事業を活用する形で実施をしていると認識をしております。この東京都の補助金を活用するに当たっての条件ですとか、何かそういうものがあって、この１８歳未満にしているのかというところを示すよう求めました。","respondent":"松山障害者支援課長","answer":"東京都の条件といたしましても、同じように１８歳未満の中等度の難聴児となっておりますので、東京都の要件と同じように考えております。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"ニーズを確認しながら、１８歳以上の対象にもこの補助金をつなげていかれるような、そういうこともぜひご検討を進めてほしいと求めました。この増加の要因と、今後はどのような対策を検討されているのか、お伺いいたします。","respondent":"廣田子ども育成課長","answer":"２月１日に行いました青少年問題協議会で、私どももこの報告ついて大変衝撃を受けたところです。４署の警察の方々と情報共有する機会がありますので、また、今後検討していきたいと思っているところです。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"次に、私立保育園のおむつのことについて、お伺いをいたします。１００％園で回収をされていると認識しておりますが、されていないところに対して、区の対応をお伺いいたします。","respondent":"中元保育支援課長","answer":"そのほかの家庭的保育事業等で１園、認証で１園、合計で１４５園中３園が従来どおりの持ち帰りです。全園に対して、今回の厚生労働省等の通知は東京都を通して届いておりまして、それを全園のほうに区から周知をして、協力等依頼をしています。","id":"exchange-010"},{"speaker":"安藤委員","kind":"確認","question":"２月２７日、文教委員会の請願審査でこの点を伺ったところ、多少は変わることもあると。あるとしたら、どんな声で、区はどのように対応したのでしょうか、伺います。","respondent":"初貝保育教育運営担当課長","answer":"しかるべき対応をするということと、民営化後に、それぞれの園でアンケートを実施しております。その中でお声が届いたものに関しては適切に対応しています。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"アンケートの中に先ほど紹介したような、給食がこんなことになってしまったという声などはあったのでしょうか、伺います。","respondent":"初貝保育教育運営担当課長","answer":"アンケートの中では、今民営化しているところの中では、いろいろな項目があるのですけれども、おおむねきちんと移管をされていて、その保育の内容に関しても満足されているというような声が届いているというところです。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問","question":"改めて、給食の質を下げない業務委託というのだったら、区立と同じメニューを実施させるべきではないでしょうか、伺いたいと思います。それができないなら、こうした手法はやめて直営に戻すべきではないでしょうか、伺います。","respondent":"初貝保育教育運営担当課長","answer":"今のお尋ねですけれども、もちろん給食に関しては、栄養面のバランス、そういったところも、きちんとバランスの取れた食事を提供しているというところで実施しているです。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"声も把握した上でさらに質問していきたいとは思いますが、区立園をわざわざ民営化する方針の撤回を求めて、次の質問に移りたいと思います。それとも実際入園している子どもの人数で掛けて出しているのか、どちらなのか、伺います。","respondent":"中元保育支援課長","answer":"延長保育を実施している保育所に対する保育士１人分の人件費相当額としての延長保育充実加算が約５億円。毎月１か月ごとに園のほうから、それを保育支援課のほうで審査をさせていただき、支払いをしています。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"配置基準の検討は国の責任という説明と矛盾しているのではないでしょうか、伺います。１歳児へのさらなる加算や、ほかの年齢児にも加算を行っていただきたいのですが、いかがか尋ねました。","respondent":"中元保育支援課長","answer":"区の加算ですが、こちらは１歳児の部分に少しでも充実した保育を行っていくために、誘導するためにこの補助金の上乗せを行っているところです。国において現在も議論がされているところですので、区といたしましては、そちらの動向を注視してまいりたいと考えているところです。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"改めて配置基準の引上げを国に求めるとともに、区も１歳児のみでなく独自に配置基準を引上げ補助することを求めますけれども、いかがでしょうか。区独自の配置の加算を行わない理由、できない理由、何かあるのか伺いたいと思います。","respondent":"中元保育支援課長","answer":"毎年配置基準について要望されているですので、そちらのほうで国のほうに、間接的ですが要望を届けているところです。安全確保の保育支援員というものの予算を今、園児の安全確保、健康確保をしていただければと考えているところです。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"その実施を求めましたが、１歳児への区独自加算をしていますということを理由に、定員割れに特化して補助をする考えはないと拒否をされました。品川区が行えない理由、何か理由があるのか伺いたいと思います。","respondent":"中元保育支援課長","answer":"保育所において一時預かり事業を実施した場合の補助額の拡充や、小規模保育事業、空きスペースを活用した一時預かりを実施した場合の補助を行います。様々な保育ニーズに合わせた事業を実施した場合に補助をすることが、実際の保育の質の向上につながると考えているものです。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"とても冷たい、ほかの区ではやっているわけです。本当に経営努力しろと、本当に冷たい答弁だと思いますけれど、ぜひ実施を改めて求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"松永委員","kind":"確認","question":"初めに、２１７ページの高齢者安否確認事業の長寿お祝い事業について伺います。区内共通商品券と伺っておりますが、また、この商品券についてはどのようにして届けられているのか確認したいと求めました。","respondent":"寺嶋福祉計画課長","answer":"長寿を祝福して敬老の意を表するという目的で実施されている事業でございまして、品川区からは区内共通商品券で、同時に。事業が始まってからは、コロナ禍になる前までは、この３年間に関しては簡易書留による郵送でお届けするという手法を取らせていただいております。","id":"exchange-019"},{"speaker":"松永委員","kind":"確認","question":"他区も確認をさせていただいたのですが、１００歳以上であり、対象年齢や祝い品につきましては様々でございました。そして予算額はどのくらいになったら検討されるのか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"対象年齢の変更というご質問だと思いますけれども、男女ともに平均寿命が８０歳を超えて、はや５年以上たっているという状況です。少なくともまだ１０年以上は人口増が続くということもありますので、今の段階では特にまだ、年齢の変更をするということは検討しておりません。","id":"exchange-020"},{"speaker":"松永委員","kind":"質問・要望","question":"次に、２３７ページの認知症高齢者支援事業の約２,０００万円について伺います。初めに、この認知症検診の推進について伺います。","respondent":"川原高齢者地域支援課長","answer":"委員お尋ねの認知症検診推進事業、品川区もの忘れ検診について、令和５年度の予算の概要についてご説明をします。今年度と同様に、対象の年齢は７５歳を迎える方を予定しています。","id":"exchange-021"},{"speaker":"松永委員","kind":"質問","question":"そこで伺います。本区におきまして、どれくらいの方がこの認知症患者と言われてしまったのか、その件数も分かればお願いします。","respondent":"川原高齢者地域支援課長","answer":"投薬治療を開始された方もいらっしゃれば、在宅介護支援センターに情報提供をして、ご家庭での支援も含めてご相談に乗っていただいたり。要介護・要支援認定を受けている高齢者のうち、約１万４,０００人に達しておりまして、高齢者人口の約１７％を占める割合となっています。","id":"exchange-022"},{"speaker":"松永委員","kind":"質問","question":"続きまして、認知症の理解について伺いたいと思います。それともまた新たにステップアップ、いわゆるスキルアップをするような項目等というのはあるのでしょうか示すよう求めました。","respondent":"川原高齢者地域支援課長","answer":"寄り添った支援をより行っていくにはどうしたらいいかという会議を新たに開催してございまして、こちらのほうも現時点で４回、実施をしています。約５８名の方にご参加をいただいているところです。","id":"exchange-023"},{"speaker":"澤田委員","kind":"質問","question":"第３款民生費、第２項児童福祉費、第６目保育支援費についてお伺いします。アプリのダウンロード数は把握されているのでしょうか、どのような周知活動をされているのでしょうか示すよう求めました。","respondent":"廣田子ども育成課長","answer":"今現在のダウンロード数が２万１,９９０件というふうに把握しております。広報紙でありますとか、子育て中の方がいらっしゃるような講演会等の案内にＱＲコードを入れて、ダウンロードしていただくような周知をしています。","id":"exchange-024"},{"speaker":"澤田委員","kind":"質問","question":"気になった方、関心を持った方がすぐダウンロードできるように、さらに取り組んでいただくなどというのはいかがでしょうか。区の見解を説明するよう求めました。","respondent":"廣田子ども育成課長","answer":"ご提案の内容につきまして、これからアプリをリニューアルしますので、今ダウンロードするとまた、リニューアルになりますので、新しいアプリのときに周知のところで参考にさせていただこうかと思います。","id":"exchange-025"},{"speaker":"澤田委員","kind":"質問・要望","question":"しっかりと支援の情報を受け取っていただくためにも、しながわパパママ応援アプリのより一層のブラッシュアップを、改善を要望いたします。その中の項目４にある、チャートやすごろくのように進んでいき、ぜひ区の考えを説明するよう求めました。","respondent":"廣田子ども育成課長","answer":"令和５年度に、アプリのリニューアルを考えておりまして、令和５年１０月頃にできたらいいなと準備をしているところなのですが、今、ほかの区のアプリの状況なども検証しているところですので、委員ご提案の内容も含めまして、取り組ませていただこうと考えています。","id":"exchange-026"},{"speaker":"澤田委員","kind":"質問・要望","question":"求めていた支援があることすら知らなかったというお声もありますので、ぜひアプリのさらなる改善、ブラッシュアップを要望して次の質問に参ります。現在の私立幼稚園の介助員の予算は、どの事業に計上されているのでしょうか示すよう求めました。","respondent":"中元保育支援課長","answer":"私立幼稚園の介助員の予算ですが、２６９ページの中ほどから下のところに、私立幼稚園費とございまして、そこの私立幼稚園経費の中に、私立幼稚園振興費等補助金がございまして、その中に計上しています。","id":"exchange-027"},{"speaker":"澤田委員","kind":"質問・要望","question":"特別支援を要する児童を受け入れている私立幼稚園に対して、補助金の拡充を要望いたします。区の見解を説明するよう求めました。","respondent":"中元保育支援課長","answer":"対象園児数の増加を見込みまして、２０人分の予算を計上しておりましたものを来年度は２５人分ということで、区としましても増額を見込んでおります。区のほかに東京都補助というものもございまして、そちらも私立幼稚園特別支援教育事業費補助金ということで、申し添えします。","id":"exchange-028"},{"speaker":"澤田委員","kind":"質問","question":"次に、同じ２６５ページの特別支援巡回相談についてお伺いします。特別支援巡回相談事業の、区立幼稚園、区立保育園、私立幼稚園、私立保育園、それぞれの実施の状況を示すよう求めました。","respondent":"初貝保育教育運営担当課長、中元保育支援課長","answer":"嘱託医の巡回相談は、公設公営の保育園で１９回実施しております。次に、臨床発達心理士による巡回相談ですけれども、公設公営の保育園につきましては１５８回、公設民営保育園などでは１０回実施しております。 私立保育園における１月末の実績ですが、臨床発達心理士によるものが認可保育園で１６０回、地域型保育事業で５回、認証保育園で１１回です。学校心理士の巡回相談が認可保育園で６０回の実績となっています。","id":"exchange-029"},{"speaker":"澤田委員","kind":"質問・要望","question":"保護者の３者間で、話し合う場や仕組みの持てる環境のためにも、ぜひキンダーカウンセラーの配置を要望いたします。伺います。","respondent":"松山障害者支援課長","answer":"巡回相談は、保育所からの申請に基づき行っているものでして、保育所等訪問支援については、保護者からの申請に基づき行っております。まだ少し周知が不足しておりますので、今後、様々な媒体を通じて周知をし、使っていただくよう促してまいります。","id":"exchange-030"},{"speaker":"いながき委員","kind":"提案","question":"お尋ねは、２０件ある在宅介護支援センターの常駐の方の人数、職種を教えてください。こういったものも、ぜひ品川区でも取り入れてほしいなという、最後の１つは提案ですとの意見を述べました。","respondent":"菅野高齢者福祉課長","answer":"そこに地域包括支援センターの機能も加えて、様々な相談に対応できる体制と、在宅介護支援センターという名前をそのまま掲げているという状況です。今申し上げました連携を基に、権利擁護などに努めるなど、高齢者の在宅での介護を支えるために機能している次第になっています。","id":"exchange-031"},{"speaker":"いながき委員","kind":"質問・要望","question":"地域包括という名前なわけですから、ぜひとも今後、考えていただきたいなと思います。都合３人置くという意味ですか、１つのセンターに１人いればいいということでしょうか、お尋ねをします。","respondent":"菅野高齢者福祉課長","answer":"１人ずつ置くということになっておりますので、おおむね区では、６,０００人当たりにその職種が１人ずつということの配置になっております。","id":"exchange-032"},{"speaker":"いながき委員","kind":"提案","question":"ケアマネ１人当たりが抱える高齢者の人数は何人ですか。自宅で暮らしている高齢者の様子を見に行く頻度は何回ぐらいか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"たしか１人当たり３５人か４０人と、そこにのっとって、在宅介護支援センターや居宅介護支援事業所のほうはケアマネジメントをしている状態です。","id":"exchange-033"},{"speaker":"いながき委員","kind":"質問","question":"高齢者、どうしても世代間で少し差が出てしまうというようなことが起きないような配慮、施策はどういったことがありますでしょうか。もともとの趣旨である多世代交流、いわゆるごちゃ混ぜの施設にしてほしいなと思うのですが、伺います。","respondent":"川原高齢者地域支援課長","answer":"今現在、平面図の部分の１階の入り口のすぐ近くに地域交流スペースというどなたでも入れるスペースを設けさせていただきました。道路から中身が見えるような形でどなたでもお訪ね、お気軽にどうぞという雰囲気を出したいというところをまず、第一に考えてあります。","id":"exchange-034"},{"speaker":"いながき委員","kind":"質問・要望","question":"何かそういったことはできますでしょうか。そこで、その見解を伺います。","respondent":"川崎障害者施策推進課長","answer":"こちらのほう、障害者差別解消支援地域協議会を設置しまして、地域の実情に応じた差別解消の取組を進めております。令和５年度に向けて、そこを検討している最中ではありますので、検討はしてまいります。","id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"２１７ページ、重層的支援体制、２２１ページ、グループホーム、２３５ページ、福祉人材確保、２３９ページ、高齢者クラブ。この作品集の発表会があったと伺っていますが、どういう状況だったか説明を求めました。","respondent":"菅野高齢者福祉課長","answer":"今年度新規事業として募集をしましたところ、１６４作品の応募がありました。メッセージを送った方と、メッセージを送られた事業所の方を対象に、表彰式を実施させていただきました。","id":"exchange-036"},{"speaker":"藤原委員","kind":"質問","question":"目的等、これ読めば分かりますので、どういう状況だったのですかと。利用者と、そして介護してくださる方がどういう感じだったかということを伺いたかったのです。","respondent":"菅野高齢者福祉課長","answer":"おおむね、１０年ぐらい前に比べると、かなり賃金は改善されてきたのではないかと類推しているところです。ただ、区内の事業所が少しでもサービスが継続できて、サービス提供できるように支援していかなくてはいけないと感じているところです。","id":"exchange-037"},{"speaker":"藤原委員","kind":"質問・要望","question":"求めないところもあるし、事業者も含めて、事務的手続が増えてしまうからということで我慢してしまうところもあるのです。その辺についていかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"区独自の支援金等ができないかというお話についてです。内容的には、３年を経過した職員を対象に１０万円を支給するという事業で、令和２年度より開始していると聞いております。","id":"exchange-038"},{"speaker":"藤原委員","kind":"質問・要望","question":"でも、この方がお話ししているではないですか。その点についても伺います。","respondent":"菅野高齢者福祉課長","answer":"人と人との対面の仕事であるということで、今ＤＸ化が進められている中で、なかなかそういった部分については難しいというところは認識しております。全く同じ手法でというところはあれなのですけれども、いろいろ工夫をしながら、この事業を継続できたらと思っているところです。","id":"exchange-039"},{"speaker":"藤原委員","kind":"質問","question":"私が伺うのは、この手を挙げてくれる事業者自体あるのですか。その辺については、いかがか尋ねました。","respondent":"川崎障害者施策推進課長","answer":"令和５年度の施政方針にありましたように、都有地、そして民有地の活用に向けた情報収集に努めております。区としてもできるのかというのは研究しながら、今後、グループホームについても進めていきたいと考えています。","id":"exchange-040"},{"speaker":"藤原委員","kind":"質問・要望","question":"その辺の分析、そしてこれからの課題、そういう点についてお伺いします。その中において、もうどんどん具体的に動いていっていただきたいと思っているのですけれども、態勢的にはどうなっているのか尋ねました。","respondent":"川原高齢者地域支援課長、寺嶋福祉計画課長","answer":"私のほうから、委員よりご質問いただきました高齢者クラブの人数と、現状と課題についてのご回答です。そういったところで、何かできる新規加入のものをＰＲをしていきたいというところは、図っていきたいと考えています。 重層的支援体制整備事業ですけれども、連携の仕組みをつくる内部の検討の時間が長いので、進んでいるという段階です。","id":"exchange-041"},{"speaker":"芹澤委員","kind":"提案","question":"養育費の支援を区が独自でしたらいいのではないかというような提案をさせていただいて、翌年から実施をしていただいていると認識をしています。昨年の決算特別委員会でも確認をして、その確認をしますが、その民間保証会社の初回料の補助というこの２パターンだったと思いますとの意見を述べました。","respondent":"飛田子育て応援課長","answer":"そういうところで、丁寧に対応していきたいと思います。来年度も、相談員を配置しまして、そういう相談に丁寧に応じていきたいと考えております。","id":"exchange-042"},{"speaker":"芹澤委員","kind":"質問","question":"それを区がわざわざ排除することはないのではないですかというようなお話をさせていただきました。品川区では、統計よりも高く受給率があるという状況を目指すべきだと思うのですが、もう一度ご見解を説明するよう求めました。","respondent":"飛田子育て応援課長","answer":"令和５年１月現在の状況ですと、相談のほうで事前相談を受けているところが５０件ありまして、公正証書の作成は１２件ほどいただいているところです。どういうふうにしていったらいいか、また、そういうところは検証していきたいと考えております。","id":"exchange-043"},{"speaker":"芹澤委員","kind":"質問・要望","question":"大体月額で４万円ぐらいの相場だと伺っていますけれども、年間にすると約５０万円。区の補助なしに入るようになる仕組みができるわけですから、ぜひこれは前向きに乗り出してほしいと求めましたが、最後ご見解を説明するよう求めました。","respondent":"飛田子育て応援課長","answer":"その中にはひとり親の支援というところで、こういう支援がありますよ、ひとり親の自立に向けてやっているところです。そういうところで、相談等に応じまして、今後の施策に生かしていければと考えております。","id":"exchange-044"},{"speaker":"芹澤委員","kind":"質問・要望","question":"ぜひやりたいな、というふうに思えるような制度の設計をしていただきたいということで、これは要望で終わります。超短時間就労についてお伺いをします。","respondent":"松山障害者支援課長","answer":"これから東京大学の近藤先生を中心にノウハウをいただきながら、区内の就労環境の分析に当たるです。区内、区外とも、今のところ想定しておりますので、特に限定して民間だけということではございません。","id":"exchange-045"},{"speaker":"芹澤委員","kind":"提案","question":"併せて、いろいろ、残念ながら障害者が就労できる環境には至らなかったというケースもこれから多分多数出てくるのだと思います。そういった横の展開、連携というのもご提案しますが、ご見解を説明するよう求めました。","respondent":"松山障害者支援課長","answer":"多様な仕事の切り出しのときの対応についてお答え申し上げます。この機会に、働く幸せを感じられるということにしていきたいと思っていますので、積極的に取り組んでまいります。","id":"exchange-046"},{"speaker":"せらく委員","kind":"質問","question":"区立保育園の電子化推進経費について、こちらプレス発表にありました保育園業務支援システムの導入の部分に当たりますでしょうか。こちらについては、どのような形でＩＣＴ化をしていくというようにお考えか、連絡アプリでということですが、具体的に説明を求めました。","respondent":"初貝保育教育運営担当課長","answer":"品川区の区立保育園の中で、保育園業務支援システムというものを導入しようというところで、今ご提案させていただいているところです。","id":"exchange-047"},{"speaker":"せらく委員","kind":"質問","question":"入退室と連絡帳アプリはそれぞれ別のシステムで既存にあったところなのですが、そちらと、例えば一体にするということはお考えでしょうか。説明を求めました。","respondent":"初貝保育教育運営担当課長","answer":"今想定しているところといたしましては、来年度、保護者への連絡等々と、記録の一元管理を予定しております。ほかのところも、一体的に管理ができるような形で導入を図っていくような形で、連絡帳のところは切替えをするというようなところで考えております。","id":"exchange-048"},{"speaker":"せらく委員","kind":"意見","question":"保育士の日誌をはじめとした、書類もペーパーレスにするということだと思うのですけれども、日々の保育の記録、日誌なりを入力する端末は、例えばクラスに１台など、どのように確保するように想定をしていらっしゃいますかとの意見を述べました。","respondent":"初貝保育教育運営担当課長","answer":"端末のお話ですけれども、端末は、現在園でも使える端末を配備しています。そちらをまずは活用して、入力をするというような形で考えております。","id":"exchange-049"},{"speaker":"せらく委員","kind":"質問","question":"その端末は保育園に１台あって、それを保育時間が終わった後などに時間を確保して、入力していくという形になるのでしょうか。分かれば説明を求めました。","respondent":"立木保育課長","answer":"保育園では、２人に１台ずつは必ずあるようになっていまして、順次１人１台ずつ使えるような形で、配分調整をかけているようなところです。","id":"exchange-050"},{"speaker":"せらく委員","kind":"確認","question":"例えば、園児のお昼寝中は、遊び保育はなくなりますが、寝姿勢や呼吸の確認などをひっきりなしに行っているので、気が抜けないと思います。お昼寝のＡＩカメラなどといったツールもありますが、こういったツールを補助的に利用することについて、区のお考えを説明するよう求めました。","respondent":"初貝保育教育運営担当課長","answer":"は保育士によって、あおむけ寝の徹底でありましたり、室内環境を適切に保つことを実施しております。保育の質の向上というところを含めて、今後さらなる情報収集を進めてまいりたいと考えております。","id":"exchange-051"},{"speaker":"せらく委員","kind":"質問・要望","question":"私も前回の決算特別委員会の中で、導入を要望させていただいていたので、前進をするということをすごくうれしく思っています。前回課題として上がっていた費用面、保管場所、メーカーについては、現状どのようにお考えか尋ねました。","respondent":"初貝保育教育運営担当課長","answer":"区立保育園でのサブスクリプションに関しましては、新年度にテスト導入をするというところで、各種課題を整理しています。基本的には保護者負担というところになりますけれども、その他の課題についても今整理して、スタートに向けて準備をしています。","id":"exchange-052"},{"speaker":"せらく委員","kind":"質問・要望","question":"次に、第２子以降の保育料について、認証保育所の助成の拡充に関して伺います。私立幼稚園においての第２子、第３子への保育料、預かり保育の完全無償化についてはいかがか尋ねました。","respondent":"中元保育支援課長","answer":"現在３歳以上の方は無償化対象ということで、保育料は、ほぼかからないという形にはなってあります。周辺区の状況等も見ながら、どのような形でほかの区が助成制度を設けているのかなども調査研究してまいりたいと考えているところです。","id":"exchange-053"},{"speaker":"せらく委員","kind":"質問","question":"私立幼稚園の保育支援員の雇用費補助が新規事業として発表されていますが、現在の支援員の状況について伺います。今回の事業で、支援員の配置、どういったところで変化があるか説明を求めました。","respondent":"中元保育支援課長","answer":"こちら私立保育園に、保育支援員というものを新年度予算で計上させていただいているところです。各組、区としましても体制を一層支援するということで、保育支援員の配置を行えるように補助制度を今現在予算計上しているものです。","id":"exchange-054"},{"speaker":"せらく委員","kind":"質問","question":"幼稚園の預かり保育について伺いたいと思いますが、まず、幼稚園は先生１人に対して児童数も多いと思います。通常保育時と預かり保育時での先生に対する児童の数、また、交代や補助者の体制を伺いたいと思います。","respondent":"中元保育支援課長","answer":"幼稚園の配置基準は、国の文部科学省の基準がありまして、３５名に対して１名の幼稚園教諭という配置基準があります。当然３５名より少ない人数でのお預かりと実際なってありますので、そちらにつきましても、幼稚園教諭の方お一人という形で配置をしているものです。","id":"exchange-055"},{"speaker":"せらく委員","kind":"質問","question":"幼稚園だと３歳から５歳児が中心になると思いますが、事故防止や先生１人の負担を思うと、追加の支援員の役割が重要だと考えます。私立幼稚園での預かり保育での補助支援員についてのお考えを伺います。","respondent":"中元保育支援課長","answer":"預かり保育に係る事業費全体に対して、私立幼稚園全園平均で約７０％までの費用が、東京都と品川区の補助金で現在充当されているところです。そのお渡ししているお金等で、園のほうで必要な方を配置していただくという形で、今運営しています。","id":"exchange-056"},{"speaker":"せらく委員","kind":"質問","question":"は心配がある方にご案内をしていき、週に一、二回預かりというケースを想定していることと伺いました。バッチ、お昼寝用品など園で用意するものは、このモデル事業でも園で用意するように予算として含まれているのか尋ねました。","respondent":"中元保育支援課長","answer":"在園児の方の場合と同じルールで、保護者の方に用意していただくものと、園で用意するものとご案内をします。園で用意するものにつきましては、今回の予算で計上しているものの中からお渡ししたお金で、園で用意していただくということで考えております。","id":"exchange-057"},{"speaker":"せらく委員","kind":"質問・要望","question":"最後に、出産育児一時金について伺います。改めてこちらについて伺えますか。","respondent":"池田国保医療年金課長","answer":"出産育児一時金につきましては、国民健康保険の部分では４２万円から５０万円にということで、４月１日から改正する予定になってあります。国のほうで今のところ４２万円から５０万円に引き上げるということでやってありますので、実際には大都市、決して定かではないです。","id":"exchange-058"},{"speaker":"せらく委員","kind":"質問・要望","question":"品川区で出産した皆さんの声をぜひしっかり聴いてほしいと求めました。これで質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"横山委員","kind":"質問・要望","question":"具体的には、品川区内の警察署にどのように共有がされていて、例えば大森少年センターなどでどういった支援が行われているのでしょうか。全ての子どもたちを地域での支援や見守りに確実につなげていってほしいと強く要望いたしますが、区が把握している現状を説明するよう求めました。","respondent":"長谷川児童相談所移管担当課長","answer":"通告に基づき対応する機関となりますので、要保護児童地域対策協議会等の場を活用して、しっかりと情報把握に努めてまいります。青少年の健全育成に関しましては、青少年協議会とも情報共有しながら、仕組みの構築について検討してまいります。","id":"exchange-060"},{"speaker":"横山委員","kind":"質問・要望","question":"今年２月の第１０回教育・保育施設における子どもの安全管理講座をオンデマンド受講し、ＮＨＫ報道局科学文化部の秋山度記者からお話を伺いました。情報を整理した上で、現場とメディアとの情報共有を進めていただきたいと要望いたしますが、区のお考えを説明するよう求めました。","respondent":"中元保育支援課長","answer":"テレビ、新聞、ＳＮＳ等のメディアにより、様々な情報を取得し、お子様の安全についての啓発が行われることは望ましいと考えています。今後も様々な機会を捉えて、お子様の安全を守っていきたいと思っているところです。","id":"exchange-061"},{"speaker":"横山委員","kind":"質問・要望","question":"３点目に、障害者虐待防止対策費、障害者理解・普及啓発事業についてお伺いをいたします。以前よりも優先順位をもう１段階上げていく必要性があるかと思いますが、区のお考えを説明するよう求めました。","respondent":"菅野高齢者福祉課長、松山障害者支援課長","answer":"そこで区では、虐待防止のため施設内にて実施する研修の共通プログラムを作成して、説明会を実施しております。身体拘束廃止研修について、施設長と従事職員と２回に分けまして、研修等も実施させていただいている次第です。 講演会のほか、手話理解普及啓発についても、来年度ぐるっぽで実施する予定です。障害者７団体中心に作っていただいた当事者目線での冊子につきましても、もう１段階、またさらに広く周知してまいりたいと考えております。","id":"exchange-062"},{"speaker":"横山委員","kind":"質問・要望","question":"区内のコミュニケーションも難しい状況が続いておりました。引き続き進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"松澤委員","kind":"質問","question":"は昨年度の決算特別委員会で質問しました、「品川“くるみ”認知症ガイド」の再編集についてお聞きいたします。「品川“くるみ”認知症ガイド」の再編集、これはどのような計画で進んでいるのか、今お答えできる範囲で説明を求めました。","respondent":"川原高齢者地域支援課長","answer":"現段階の予定のお話ではありますが、当事者の声を聴き、令和５年度より「品川“くるみ”認知症ガイド」の作成検討会議を開催する計画でおります。","id":"exchange-064"},{"speaker":"松澤委員","kind":"質問","question":"要は「品川“くるみ”認知症ガイド」が基盤になるわけですから、すばらしい冊子になることをお祈りしております。４,９６２人中、２４６人受診があった、そのうちの５４人を支援につなぐことができたというお話は伺いました。","respondent":"川原高齢者地域支援課長","answer":"認知症専門医との検討委員会というものを開催していく中で、今後に取り組んでいかなければいけない事項として挙がったことが２点あります。１点目が、訪問看護ステーションとの連携を考えてございまして、アウトリーチを図る手段を現在検討しています。","id":"exchange-065"},{"speaker":"松澤委員","kind":"質問","question":"うちの母もちょうど７５歳だったので、私は大丈夫ですというので受けなかった方が、結構いらっしゃったのです。区のほうで何か受診につながる取組ですか、そういったお考え、そのようなお考えを説明するよう求めました。","respondent":"川原高齢者地域支援課長","answer":"今、そういった認知症カフェでもの忘れ検診の情報発信を行うなど、様々な場での広報の活動を実施してまいりたいと考えています。お医者様からも７５歳の患者様がいらっしゃったときには声かけをぜひお願いしますという形で、引き続きご相談をさせていただきたいと考えています。","id":"exchange-066"},{"speaker":"松澤委員","kind":"質問","question":"私もかかりつけ医というのですか、医者の発言力というのですか、そうなんだと信じてしまう部分があります。それについてご見解を説明するよう求めました。","respondent":"川原高齢者地域支援課長","answer":"認知症検診に限らず、日頃の町場のドクターからのお声かけの後押しというご質問です。引き続き品川と荏原の両医師会にご相談をさせていただいて、お声かけを図っていただくようにお願いをしてまいりたいと考えています。","id":"exchange-067"},{"speaker":"松澤委員","kind":"質問","question":"次に、新規事業になります、絵本の読み聞かせについてお聞きいたします。そこで、例えば、どこでこのような取組を開催していくのか、また、読み聞かせをすることによって何が分かるのか、詳しく説明を求めました。","respondent":"川原高齢者地域支援課長","answer":"令和５年度、新規に始まります認知症予防を目的とした絵本読み聞かせ講座の開催場所ですが、こちらは荏原文化センターでの開催を予定しています。年に２回、ワンクール３か月、計１８回の講座を６月と１０月の開催という形で現在考えているところです。","id":"exchange-068"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私からは、２３９ページ、補聴器購入費助成事業、２４９ページ、ファミリーサポートセンター運営費について伺っていきます。昨年６月、私ども公明党の一般質問で、補聴器購入費の助成制度の導入を求めました。","respondent":"川原高齢者地域支援課長","answer":"助成開始まで期間を設けている理由としては、助成前の６月を今現在予定しておりますが、現在検討しています。補聴器の専門店の方もお招きしまして、補聴器のデモですとか、そういった形ができるかというところを今検討している状況です。","id":"exchange-069"},{"speaker":"あくつ委員","kind":"質問・要望","question":"他自治体の導入事例を確認しますと、もしくは本人非課税、もしくは区で独自に定めている所得制限がありました。対象者の拡大も視野に入れていただきたいと、これが私どもの考えですが、その辺りのご見解を伺わせてほしいと求めました。","respondent":"川原高齢者地域支援課長","answer":"購入後、その購入した証明書をもって助成をするという予定を考えてあります。やっとスタートの時点に入る予定ではありますので、また、どのような方が申請になられるかというところをしっかりと検証してまいりたいと思います。","id":"exchange-070"},{"speaker":"あくつ委員","kind":"質問","question":"同じ建物ですから民生委員や成年後見センターがあって、比較的いろいろな方に声がかけやすくて、提供会員が集まりやすいという話も伺いました。この辺り、２つのファミリーサポートセンターの提供会員、依頼会員数の比較などの事実関係、そして区の認識を伺いたいと思います。","respondent":"染谷子ども家庭支援センター長","answer":"平塚ファミリーサポートセンターにつきまして、現在の提供会員が１７１名で、大井ファミリーサポートセンターが２５３名となっているところです。そういった要因の部分も含めて、提供会員のこれからの促進に向けて、委託事業者と検討を進められればと考えています。","id":"exchange-071"},{"speaker":"あくつ委員","kind":"質問・要望","question":"もう一度伺いたいのですが、特に平塚ファミリーサポートセンターの提供会員の募集の周知も徹底していただきたいというお声もいただいております。そう簡単には改善はできないと思いますけれども、ぜひそういったご答弁をいただきたいなと思うのですが、お考えを伺いたいと思います。","respondent":"染谷子ども家庭支援センター長","answer":"取り組める方法がないかというところにつきましても、委託事業者に現状を確認しつつ、検討できればと考えているところです。周知啓発を行っていくということは重要であると考えていますので、広報紙以外の媒体の活用も含めて、積極的な広報を行っていきたいと考えています。","id":"exchange-072"},{"speaker":"あくつ委員","kind":"質問・要望","question":"もう事業ができているわけですから、根本的に見直していただきたいということが今日の質問の趣旨ですが、最後のご答弁をお願いして終わります。","respondent":"染谷子ども家庭支援センター長","answer":"委託事業ということで、区として実施している事業ですので、委託事業者と状況を確認させていただき、また協議させていただきたいとは思いますけれども、区として実施する事業として見直しができないかというところについては、検討させていただきたいと思います。","id":"exchange-073"},{"speaker":"おくの委員","kind":"質問","question":"返済が滞っている方もいらっしゃると聞きましたけれども、どのような理由でできなくなっているのでしょうか。この点伺います。","respondent":"飛田子育て応援課長","answer":"合計金額は約６,３００万円、そのうち滞納されている方は８７人おりまして、合計が約１,８００万円ほどとなっております。返済できない理由としましては、失業とか、ご病気、また多重債務が原因で、なかなか払うことが難しいという声も聞いております。","id":"exchange-074"},{"speaker":"おくの委員","kind":"質問","question":"そこで伺いますが、返済ができないほど生活に困っているような方には、返還を全部あるいは一部免除してはいかがでしょうか。かつての制度によるものなのですけれども、今の制度に合わせて免除してほしいと私は思うのですが、いかがか尋ねました。","respondent":"飛田子育て応援課長","answer":"そういった過去、また、今ももちろん返済をしている方もいますので、そのような方の公平性等も考えると、免除は非常に難しいと考えております。やむを得ない事情のある方には、お話を聞きながら、延納や、またさらに分割をするなど、柔軟な対応を行って返済をお願いしています。","id":"exchange-075"},{"speaker":"おくの委員","kind":"質問","question":"そこでさらに伺います。いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"おくの委員","kind":"質問","question":"私としては、趣旨を活かして無償教育へ一歩近づいていってほしいと考えています。高校生のみならず、大学生に対しても給付制奨学金制度を設けることを考えていくべきではないかと思うのですけれども、その点いかがか尋ねました。","respondent":"飛田子育て応援課長","answer":"大学生の給付型の奨学金についてですが、国で令和２年度より高等教育の就学支援新制度が開始しております。区独自の大学生向けの奨学金を実施する予定はございませんが、国が実施している様々な支援策の動向などを注視してまいりたいと考えています。","id":"exchange-077"},{"speaker":"おくの委員","kind":"質問・要望","question":"これがなぜ品川区では実施ができないのでしょうか。私は不十分だと思っているのですけれども、その点いかがか尋ねました。","respondent":"飛田子育て応援課長","answer":"独自に出している自治体はまだあまり多くありませんが、やはり課題としては、いろいろ様々なことが考えられております。区独自、また単費で実施することはまだまだ課題は多いと思いますので、また国の動向や他区の動向を見ていきたいと考えております。","id":"exchange-078"},{"speaker":"おくの委員","kind":"質問・要望","question":"ぜひこれは実現する方向でいってほしいと求めました。大学生に、その一歩として給付制の奨学金制度、これを求めて質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"小芝委員","kind":"質問","question":"私からは、２３１ページ、在宅高齢者支援事業についてお伺いいたします。在宅介護認定者の数、要介護者全体の中で在宅介護認定者の占める割合、３つについてお伺いいたします。","respondent":"菅野高齢者福祉課長","answer":"現在、認定者数約１万５,０００人程度です。それに対して、在宅の高齢者数は１万２,０００人弱と認識しておりまして、残りの２５％の方が施設入所されていると認識しているところです。","id":"exchange-080"},{"speaker":"小芝委員","kind":"質問","question":"その大体２割以下ですか、要介護３以上の方ですので、大体５,０００人前後ぐらいではないかなと思います。そういった方の生活の状況、分かる範囲で構いませんので、教えてほしいと求めました。","respondent":"菅野高齢者福祉課長","answer":"区では２０か所の在宅介護支援センターや、区内１３か所に支え愛・ほっとステーション等があります。少しでも介護認定の申請につながって、必要な方に介護サービスが提供できるように努めていきたいと、情報収集に努めているところです。","id":"exchange-081"},{"speaker":"小芝委員","kind":"質問","question":"この利益を受けることができるわけですが、大体どのくらいの年間の件数なのかを教えてください。そのような方へのサービス、ほかにはどういったものがあるのかも含めて、教えてほしいと求めました。","respondent":"菅野高齢者福祉課長","answer":"こちらにつきましては、介護保険の認定で非該当と判定された６５歳以上の高齢者で、手すりの設置や段差の解消などが対象工事となっております。令和４年度も、令和３年度と同程度で、その辺りは検証していかなければいけないと感じているところです。","id":"exchange-082"},{"speaker":"小芝委員","kind":"質問・要望","question":"施設で亡くなる方は１０８万人、７０年の歳月を経て、この数字に如実に表れていると言えると思います。あることは承知はしておるのですが、その辺り、区のお考え等ありましたら教えてほしいと求めました。","respondent":"川原高齢者地域支援課長","answer":"私ども高齢者地域支援課では、６５歳以上の高齢者、多種多様で参加依頼を呼びかけてあります。シルバー大学での学びの支援ですとか、また認知症予防に合致したプログラムを引き続き提供して、検討してまいりたいと考えています。","id":"exchange-083"},{"speaker":"木村委員","kind":"確認","question":"私からは、２１７ページ、高齢者安否確認事業からの質問です。高齢者等とありますけれども、この等とは何を意味しているのか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"主に地域で見守りが必要と思われる高齢者の方を、地域で緩やかに見守っていただくということを目的に実施している事業です。あまり厳密に６５歳以上と限定はしておりませんので、６５歳未満でありましても、等とつけさせていただいているものです。","id":"exchange-084"},{"speaker":"木村委員","kind":"質問","question":"これがいつ頃から始まった事業で、高齢者の皆さんの反応はどのように聞かれているのでしょうか。これも説明を求めました。","respondent":"寺嶋福祉計画課長","answer":"参考までに、１１町会から始まったのですけれども、現在５４の町会に参加していただいているです。今年度も新たに３町会に加わっていただきまして、活発に活動していただいていると、このような状況です。","id":"exchange-085"},{"speaker":"木村委員","kind":"質問・要望","question":"民間企業についてもお尋ねをしますけれども、現在区と、この見守り協定をしている企業は、大体何社ぐらいあるのか、あるとすればどのような事業なのか、差し支えない範囲で結構ですので、お答えをほしいと求めました。","respondent":"寺嶋福祉計画課長","answer":"先月の末時点で２１の事業所、団体と協定を締結しておりまして、３月１日付で新たに２社加わりまして、現在２３社による協定締結となっております。","id":"exchange-086"},{"speaker":"木村委員","kind":"質問","question":"次に、長寿お祝い事業についてですが、お聞きをいたします。無論高齢者が必要としている商品等であろうと思いますけれども、どのようなものをお祝いとして出しているのか、これも説明を求めました。","respondent":"寺嶋福祉計画課長","answer":"長寿お祝い事業につきましては、８８歳、米寿、９０歳、卒寿、９９歳、１００歳、１０１歳以上の方に区内共通商品券をお届けしている事業です。安否確認を兼ねた事業となっておりますけれども、昨今コロナなので、この３年間は郵送による対応という形になっております。","id":"exchange-087"},{"speaker":"木村委員","kind":"質問・要望","question":"高齢者の方々に喜ばれている事業だとは思いますけれども、喜びの声や感想など、何か寄せられたようなことはあるかどうか、そしてその喜びの声などがあれば、お聞かせほしいと求めました。","respondent":"寺嶋福祉計画課長","answer":"訪問、接触のきっかけが増えたというような、これは届けた側からのご感想をいただいたことがあります。１件、２件ではなく、大変喜ばれている事業です。","id":"exchange-088"},{"speaker":"木村委員","kind":"質問・要望","question":"これは令和４年度が３万６,０００円で、令和５年度も同じだと思いますけれども、この事業自体を取りやめるようなことは考えていないのでしょうか。そして、これはなぜ続けるのか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"審査をさせていただいて、高齢者のグループの方にカードをお送りする、そのカードの紙代と郵送費のみで実施をしている事業です。今後も実施を予定しています。","id":"exchange-089"},{"speaker":"木村委員","kind":"質問・要望","question":"歌は腹から声を出すため、健康にはとてもよいと思っています。大変今厳しい状況の予算でありますが、それを続けていくためには何が必要なのか、それをお聞かせほしいと求めました。","respondent":"川原高齢者地域支援課長","answer":"こちらの継続について、どのように図っていくかです。活動の場を、こういった場所がありますよということを引き続きＰＲ、周知を図ってまいりたいと思います。","id":"exchange-090"},{"speaker":"木村委員","kind":"質問・要望","question":"ぜひとも、高齢者の皆さんのためにも、このような事業が続くこと、私も歌が大好きでありますから、ぜひ続けてほしいと求めました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"こんの委員","kind":"質問","question":"２点目が２３９ページ、２６９ページ、この３点からお伺いしたいと思います。こうしたものがどうなっているのか、それから併せて、この申請についての課題がありましたらば説明を求めました。","respondent":"中元保育支援課長","answer":"具体的に申し上げますと、１月から３月にご利用いただいた分については、翌月の４月１５日頃を交付申請の締切りとしているものです。申請していただいたものを審査いたしまして、４月末にお支払いするという流れで、今事務を行っているものです。","id":"exchange-092"},{"speaker":"こんの委員","kind":"質問・要望","question":"ですから、利用した翌月の１５日までにその領収書が手元に来ない。申請日数に余裕を持たせた、こうした申請にしていただきたいと思うのですが、いかがか尋ねました。","respondent":"中元保育支援課長","answer":"１つ懸念されますのが、申請が遅くなると、当然申請された方への助成金のお支払いもその分後になってしまうというところはあります。周知のほう、今後は、もう少し分かりやすいところにご案内するように検討してまいりたいと考えているところです。","id":"exchange-093"},{"speaker":"こんの委員","kind":"質問・要望","question":"高齢者向けのスマホ教室ですけれども、今年度の８月に本格実施をされて半年がたちますが、この事業の実施状況を確認させてほしいと求めました。併せて確認ですけれども、募集の案内だとか、応募についての方法、この辺も確認したいと求めました。","respondent":"川原高齢者地域支援課長、中元保育支援課長","answer":"こちらは８月の実施ですが、講座のほうは１３７名の方にご出席いただいたことと、こちらは４５７人の方にご参加いただきました。空いている回へのご移動でのご協力の依頼などを丁寧に行いまして… 先ほどのベビーシッターの支払い等の期限のホームページの表現につきましては、今後検討し、対応してまいりたいと考えています。","id":"exchange-094"},{"speaker":"こんの委員","kind":"質問・要望","question":"今現状を伺いまして、この対策については進めていただきたいという考えですが、これからスマホを買おうかなと思っていらっしゃる方もいると。このデジタルデバイド対策を推進というところでは、ステップアップの講座も今後は必要ではないかなと思うのですが、その辺の所見をお願いいたします。","respondent":"川原高齢者地域支援課長","answer":"そしてこの講座に参加した方が、新たに同じスマートフォンを購入したというような実績も出ている形です。来年度また実施をして、もしくは再来年度で、新たな企画を検討してまいりたいと思います。","id":"exchange-095"},{"speaker":"西村委員","kind":"質問","question":"２６９ページ、２３３ページのさわやかサービスと、順不同で伺ってまいります。保育園の入園状況について伺います。","respondent":"立木保育課長","answer":"令和５年度の保育園の入園申請状況について、簡単にお答えします。やはり０歳よりは１歳から入るというようなことが、今のところ見られるというような状況にはなっていると考えております。","id":"exchange-096"},{"speaker":"西村委員","kind":"質問","question":"次に、新しく始まる一時預かり事業について伺ってまいります。一言お言葉いただけますか尋ねました。","respondent":"中元保育支援課長","answer":"児童福祉法の改正を受けました、レスパイト目的でも利用できる一時預かり事業です。私立保育園に加えまして、補助の対象とすることで、保育施設における一時預かりの実施を誘導してまいりたいと考えているものです。","id":"exchange-097"},{"speaker":"西村委員","kind":"質問","question":"ＩＣＴ化が進むことは、現場の先生方にとっては手書き文化で抵抗があると、以前保育士の方々より伺ったことがあります。今回区立園４０園で導入するに当たりまして、現場の声、課題があったら説明を求めました。","respondent":"初貝保育教育運営担当課長","answer":"今までも電子連絡帳の導入であったり、ＩＣＴを活用した教育教材の導入など、様々な電子化やＩＣＴの導入を段階的に図ってまいりました。操作ができるような形の視点も含めて、適切に選定、導入を進めてまいりたいと考えております。","id":"exchange-098"},{"speaker":"西村委員","kind":"質問","question":"さらに次は、保育士たちの働き方改善のために、社会保険労務士を活用した労務状況分析業務等委託事業として伺ってまいります。私立認可園１０園程度に対する試験的な実施を行うとありますが、また、それが今後どのように変わるのかを伺います。","respondent":"立木保育課長","answer":"そういったところを勘案しながら、委託予定であります社会保険労務士会といろいろ打合せをしながら、１０園選んでいきたいと考えています。働きやすさを出して、それを保育の質の向上につなげていこう、そのような目的で始めるものです。","id":"exchange-099"},{"speaker":"西村委員","kind":"質問・要望","question":"そこで、私立幼稚園の長期休暇について伺います。伺います。","respondent":"立木保育課長","answer":"こちらは、現在、三季休業中に私立幼稚園の在園児の方が就労等でご利用される場合に、区立保育園３２園ほど用意をしています。令和３年度の実績になりますが、私立幼稚園在園の方の一時保育の利用が２１６件、１,１１３日ご利用いただいたという形になってあります。","id":"exchange-100"},{"speaker":"西村委員","kind":"質問・要望","question":"私立幼稚園ＰＲ経費について伺ってまいりますが、こちら私立幼稚園が頑張ってホームページをつくりましても、告知や周知が大変なところです。私立幼稚園ガイドなどをホームページに作成したり、私立幼稚園の魅力を伝える取組をぜひ背中を押してほしいと求めましたが、ご意見を伺います。","respondent":"中元保育支援課長","answer":"それを区のホームページとリンクさせたりなどをして、そのようなリニューアル費用についての補助金を今予算計上しています。保護者への情報発信力の強化を目指してまいりたいところです。","id":"exchange-101"},{"speaker":"西村委員","kind":"質問・要望","question":"次にさわやかサービス、最後に伺わせてほしいと求めました。こちら改めて伺います。","respondent":"寺嶋福祉計画課長","answer":"買物支援につきましては、要支援の認定を受けた方につきましては、生活援助というサービスの中で買物の代行ができることになっております。同行はできないのですが、代行は可能ということになっております。","id":"exchange-102"},{"speaker":"西村委員","kind":"質問・要望","question":"ぜひとも地域の事情に合わせた、こういった買物で困っていらっしゃる難民の方がいらっしゃらないのか、お調べいただきたいと考えています。こちらは要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、２３３ページの特別養護老人ホーム運営費に関わって、特別養護老人ホームと老人保健施設増設を求めて質問します。年齢別に、７０代以上で、各年代の申込者と入所できた人数、また、介護度別に、要介護３以上の申込者と入所できた人数を伺います。","respondent":"菅野高齢者福祉課長","answer":"特別養護老人ホームの入所申込みは、年に２回申込みを実施しまして、調整会議を行わせていただいております。１２９人中５１人で４０％、要介護度５が、６３人中２１人で３３％となっております。","id":"exchange-104"},{"speaker":"のだて委員","kind":"質問・要望","question":"９０歳でも約半分が入れない、要介護５でも３分の２が入れない状況で、特別養護老人ホームと老人保健施設は足りているという認識でしょうか。伺います。","respondent":"菅野高齢者福祉課長","answer":"９０代だから、半分の方が９０代にもかかわらず入れないとか、要介護５だから入れないなどとは言えないというところです。判定が、一概には要介護度が高くついているからといって、すぐに入れるとは言えないと認識しているところです。","id":"exchange-105"},{"speaker":"のだて委員","kind":"質問・要望","question":"伺います。この待機者をゼロにする目標を持って、そのためにいつまでにどれだけつくるかの計画をつくることを求めますが、いかがか尋ねました。","respondent":"菅野高齢者福祉課長、寺嶋福祉計画課長","answer":"在宅介護支援センターのケアマネジャー等の情報など、また違った対応などもしていますので、できるだけ皆さんが住み慣れた地域で住み続けられるようにというところで努力してまいります。令和６年度以降の第九期、第十期におきまして、特別養護老人ホームの定員を１５０から２００に増やすというふうに計画上定めております。","id":"exchange-106"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ処遇改善していただきたいと思うのですけれども、これで十分だと考えているのか、伺います。ぜひ区としても改善してほしいと求めましたし、国にも介護報酬アップを求めてほしいと求めました。","respondent":"寺嶋福祉計画課長、菅野高齢者福祉課長","answer":"整備計画につきましては、目標を持ってということで、第八期の中で目標を定め、第九期に向けて現在進めているところです。 介護職員の処遇改善につきましても、今国のほうで、第九期の介護保険事業計画に向けて審議等進めておりますので、その動向を注視していきたいと思います。","id":"exchange-107"},{"speaker":"のだて委員","kind":"質問・要望","question":"今の計画では足りないので求めておりますので、ぜひ進めて増設してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-108"},{"speaker":"せお委員","kind":"質問","question":"２３１ページ、２４９ページ、児童相談所移管推進事業をお伺いします。当初予算が増えている、この理由をまず説明を求めました。","respondent":"松山障害者支援課長","answer":"就労移行支援等のうち、就労移行支援サービスについて、区内外の事業者が増えております。中でも精神障害、発達障害の方で、就労、働きたいという方が多い状況で、給付費の増を見込みまして、予算額を増額して計上させていただいたものです。","id":"exchange-109"},{"speaker":"せお委員","kind":"質問","question":"一般質問でも伺いましたが、超短時間就労についてです。もう１点、ですから、実態調査としてアンケートを実施することも有効かと思います。","respondent":"松山障害者支援課長","answer":"調整していますが、今後継続した就労を支援する仕組みを構築するということを目標に、まずは品川区の就労環境を分析するということになっております。","id":"exchange-110"},{"speaker":"せお委員","kind":"質問・要望","question":"文教委員会に所属していた頃も何度か要望しておりますが、愛の手帳の判定は障害児関連の施設でいかがでしょうか。業務の見直しの検討だけは行っていただきたいのですが、見解を伺います。","respondent":"長谷川児童相談所移管担当課長","answer":"外部委託を検討する場合、継続性が担保できる委託機関を見つけることは容易ではないこともあり、委託の実績は。児童相談所設置市としての事務である愛の手帳の判定につきましては、国において基準の統一化に向けた調査研究が進められていると認識しており。","id":"exchange-111"},{"speaker":"高橋（伸）委員","kind":"質問","question":"２２１ページ、同じく２２１ページ、２０２５年デフリンピック大会東京開催周知啓発についてお伺いいたします。最初に２２７ページ、心身障害者福祉会館運営費についてお尋ねをいたします。","respondent":"松山障害者支援課長","answer":"心身障害者福祉会館の建て替えの検討についてお答え申し上げます。まだ代替地検討までは至っておりませんが、いずれ代替地を検討して、検討する必要があると考えております。","id":"exchange-112"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"もう１点なのですけれども、来年度の予算の中で、屋上の花壇の改修が入っているのです。それは地域、当該町会の要望など、そのようなものがあっての改修なのかというお尋ねをしたいと思います。","respondent":"松山障害者支援課長","answer":"心身障害者福祉会館の屋上花壇の改修についてお答え申し上げます。少し破損が見られましたので、これを撤去しまして、また新たに車椅子用の花壇を新設するというものです。","id":"exchange-113"},{"speaker":"高橋（伸）委員","kind":"質問","question":"続いて、手話理解促進についてお尋ねをします。１１５万円余の予算計上があって、これが少ないのかどうか、この予算規模についてのお考えをお伺いしたいと思います。","respondent":"松山障害者支援課長","answer":"障害児者総合支援施設ぐるっぽにおきまして、夏休み手話講座と、それから区民向け講座を初めて開始するということになりました。そちらを積算したものです。","id":"exchange-114"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"大体約４０万円の中で、恐らく啓発ですから、予算的にこの程度でいいのかなと私思ったのですけれども。一番格好なことだと思うので、その辺含めて、来年度のことを教えてほしいと求めました。","respondent":"松山障害者支援課長","answer":"２０２５年のデフリンピック大会東京開催の周知啓発について、お答え申し上げます。金額は少ないですが、様々な手法を使いまして、効果的な周知を図っていきたいと考えています。","id":"exchange-115"},{"speaker":"たけうち委員","kind":"質問","question":"２３３ページの高齢者災害対策支援事業費の福祉避難所施設備蓄品配備等、それから２５３ページの児童手当給付金について伺います。そこで、２３３ページの福祉避難所施設備蓄品配備等とありますが、この「等」の事業内容と予算額を説明するよう求めました。","respondent":"菅野高齢者福祉課長","answer":"私からは、福祉避難所施設備蓄品配備等の「等」の部分についてお答えします。こちらについては、福祉避難所施設の介護職員宿舎借上げ助成６５万１,０００円分がついております。","id":"exchange-116"},{"speaker":"たけうち委員","kind":"質問・要望","question":"実績はどのようになっているのかというのも、併せてお知らせほしいと求めました。コロナのほうもいろいろと５月８日から２類から５類に変わったりとか、今、ご見解を教えてほしいと求めました。","respondent":"菅野高齢者福祉課長","answer":"１８人以下の小さい介護サービス、デイサービスなどをやっている事業所等が検討していると手を挙げてはいただいているのですけれども。感染状況を見ながら、私たちとしても好事例等を示しながら、施設の支援をしていきたいと考えているところです。","id":"exchange-117"},{"speaker":"たけうち委員","kind":"質問・要望","question":"２３７ページで外国人に対して、また、こことの関連もしっかり備えながら進めてほしいと求めました。こうした動きを区として今どのように捉えているか、また何か東京都のほうの情報が入っているかどうか、お聞かせほしいと求めました。","respondent":"飛田子育て応援課長","answer":"令和６年１月に一括で６万円ということで所得制限なしで考えているが、これはまだ予定ですというふうにおっしゃっていました。区としましては、現在国も都もこのように様々な支援策を検討しておりますので、今後の動向などを注視してまいりたいと考えております。","id":"exchange-118"},{"speaker":"たけうち委員","kind":"質問・要望","question":"私たち公明党もこの４月の統一地方選挙の重点政策の一つとして、１８歳までの延長、党として取り組ませていただいているところです。こうしたことをしっかり出しながら進めていただきたいと思うのですが、その辺のお考え、また決意を教えてほしいと求めました。","respondent":"飛田子育て応援課長","answer":"品川区０歳から１８歳、月５,０００円で年間６万円ということで、諸費用も含めますと総額４１億７,７５０万円ほどかかるということです。ですので、そういうところでは、なかなか財政的な観点からも非常に難しいかとは考えております。","id":"exchange-119"},{"speaker":"たけうち委員","kind":"意見","question":"試算をしていただいているということは、その本気度が伝わってまいりましたので、期待しております。どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-120"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２２５ページの認知障害者の日常生活用具について、それから、５５１ページの地域包括支援センターについて伺いたいと思います。この人工呼吸器装着者の電源確保を使い勝手のよいものに当事者や業者などの意見も聞きながら改善してほしいと求めましたが、いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"この追加しました蓄電池の情報につきましては、改めて再度周知させていただきたいと考えています。災害時安全に在宅で避難ができるように、個別計画の作成についても進めていきたいと考えていますので、再度周知をさせていただきたいと考えています。","id":"exchange-121"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"残りの７０人余の増設はいつまでにどのようにしていくのか、伺いたいと思います。どのような類型にするのか、日中サービス支援型になるのか、このことについても伺います。","respondent":"川崎障害者施策推進課長","answer":"品川区総合実施計画上にもありますけれども、１２月末時点で新規開設４か所、定員１９名増となっております。グループホームにつきまして、出石つばさの家なのですけれども、こちらのほうは介護サービス包括型のグループホームということで予定しております。","id":"exchange-122"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２,５００万円の補助というのが、結局２,５００万円になってからは何か所だったのですか。当事者や家族が求めるグループホーム、もうそういう形で計画的に増設が必要だと思いますが、その点についても伺います。","respondent":"川崎障害者施策推進課長","answer":"重度対応、そして高度な高齢化もありますので、そういった方々に対応していくための実態というのを私どももお話ししています。ですので、そこの部分は丁寧に説明しつつ、安定的に運営していける事業者の確保にも努めていきたいと考えております。","id":"exchange-123"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１７年もたっても、２３区では品川区だけしかありませんし、東京全体でも品川区だけしかないのではないでしょうか。このチームアプローチについて、品川区はどう考えているか伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"そういったケースが起きたときには、保健師、社会福祉士、主任ケアマネ、チームを組んで対応しています。在宅介護支援センターからも、区の保健師のほうに相談等が寄せられて、こちらのほうで連携をとって対応させていただいている次第です。","id":"exchange-124"},{"speaker":"渡部委員","kind":"質問・要望","question":"２４５ページ、児童センターのところで伺っていきます。その後第二期の子ども・子育て支援事業計画のほうに何か反映されたときに、こういう方向性というのが出てくるのか、少しその辺を教えていただきたい。","respondent":"廣田子ども育成課長","answer":"今児童センター２５館全部が４０年、５０年になっている中で、職員全体であったりというところの整理をしたという段階です。今後の方向性については保育園のほうの在り方検討がこれから始まっていくかと思うのですけれども、まず内部の整理をしたというような考え方です。","id":"exchange-125"},{"speaker":"渡部委員","kind":"質問・要望","question":"ここはリンクしているというのは分かるのだけれども、ではどういう方向性があってどうこうでというのは、実は外の人は分からないわけですね。新しい計画が出てくるわけですから、少し確認をさせてほしいと求めました。","respondent":"廣田子ども育成課長","answer":"委員おっしゃるとおりで、今後生かされていく予定となっております。それをグルーピングをして、そこは地域にお示しするというのは早い段階でしようと考えていますので、その段階で少し周知がされるかと思います。","id":"exchange-126"},{"speaker":"渡部委員","kind":"質問","question":"もう造って４０年とか５０年とかたっているわけだから進んでいくのだろうと思うのですが、これから計画が出ていく中で、取りあえずこの在り方が出た。図書館と一緒にというのがあったり、保育園との兼ね合わせが当然あると思うのですけれど、その辺の考え方というのを少し教えてもらえれば。","respondent":"廣田子ども育成課長","answer":"どことコラボしてもできるような考え方を整理しておいて、順番が来たらゴーという形で進めていくような、今の段階では我々はそういう検討を早めにしていくというところです。","id":"exchange-127"},{"speaker":"渡部委員","kind":"質問","question":"ただ、教室が足りなくてというよりも、では２教室だけ当てがっているだけで回っていくのかなという心配があったりするわけです。ですから、子どもたちが本当に居心地のいい放課後を過ごすためのことも考えてほしいと思うのですが、何かお考えがあれば。","respondent":"廣田子ども育成課長","answer":"ご指摘のとおり、すまいるスクールはかなりきゅうきゅうしています。そういう面についてもよその区ではやっているので、それも含めてそういう事態が来たときは対応できるようにという検討も併せて少しずつしています。","id":"exchange-128"},{"speaker":"渡部委員","kind":"質問・要望","question":"誰が何人入ったかはいいのですけれども、いわゆる入園には指数があって、やはり４０点では入れないような地域がまだ品川区にはあるのかどうなのか。あるのだったらどの辺なのか、少し説明を求めました。","respondent":"立木保育課長","answer":"おおむね４０点、フルタイムの保護者の方は４０点というのが標準なのですけれども、それ以下でも入れているという園が増えてまいりました。東品川、あと一部人気のある園等では、やはり４０点を超しているような形が今のところまだ続いているような状況です。","id":"exchange-129"},{"speaker":"渡部委員","kind":"質問・要望","question":"そこはまた新たな園を作るべくお願いしたいですし、まだ足りないところは進めていただくよう要望させていただいて、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-130"},{"speaker":"高橋（し）委員","kind":"質問","question":"それをクリアするためにはどうすればいいのかお尋ねします。クリアするために現在何を進めているのか尋ねました。","respondent":"立木保育課長","answer":"幼保連携型認定こども園に関しましては、保育教諭という職の資格が必要になります。国と特別区のほうの動向を見ながら、これからどのような形で進めていくかというところを検討するという考え方で、今やっているところです。","id":"exchange-131"},{"speaker":"高橋（し）委員","kind":"質問","question":"ぷりすくーる西五反田が就学前教育の時代の先頭を走っていたということで、品川区も全国で有名でありました。残念ながら、今回少々止まってしまっているぷりすくーる西五反田と都内の西五反田保育園との関係を含めて、今後の展開をお伺いします。","respondent":"立木保育課長","answer":"ぷりすくーる西五反田に関しましては、幼保連携型認定こども園化を目指している区の方針ということは一つあります。隣に立地しております西五反田保育園というところをやはり一つ一体的に考えていく必要があるだろうということで、今検討を進めているところです。","id":"exchange-132"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"令和５年度には５か所増やすという先ほどご答弁がありましたので、大変歓迎しております。特別に支援が必要なお子さんを受け入れる体制を整備していくことが必要だと思いますが、まずその点、担当課の方針を伺います。","respondent":"立木保育課長","answer":"区でも特別支援には力を入れてございまして、特に来年度から医療的ケアの項目に関しても対応を拡充をしていくというところがあります。","id":"exchange-133"},{"speaker":"高橋（し）委員","kind":"質問","question":"ところで、障害者の支援ということでお尋ねしますけれども、現場の保育士たちは、残念ながら特別支援の専門家ではありません。保育所等訪問支援を行っている事業者は区内でどれぐらいあるのか尋ねました。","respondent":"松山障害者支援課長","answer":"保育所等訪問支援の事業所についてですけれども、区内では１か所、品川児童学園のみです。","id":"exchange-134"},{"speaker":"高橋（し）委員","kind":"質問","question":"保育園の園長先生にきちんと理解を深めてもらうことや、あるいはもう一つ保育所の管理部局と連携をとって、工夫の余地があるかと思います。その３点について、見解といいますか、進め方をお願いします。","respondent":"松山障害者支援課長","answer":"今後ですけれども、私立保育園所管と連携をとりまして、私立保育園園長会でもご案内をする予定です。保育所等訪問支援の事業所ですけれども、児童発達支援センターが２か所目もできることから、進めてまいりたいと考えています。","id":"exchange-135"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"障害者の所管でも、また保育の所管でも一緒なので、ぜひ連携して共通認識を持って進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-136"},{"speaker":"若林委員","kind":"確認","question":"それから、事項別明細等を確認して、助成期間は通年とあります。４月の購入分からに対しての助成制度化かというところの確認。","respondent":"川原高齢者地域支援課長","answer":"人口と、１年で８０人相当となるだろうという形で見込ませていただき、この人数を設定をさせていただいたところです。医師がその方に対して補聴器が必要と認めた場合には、お医者様の判断により助成が可能という形のスキームを現在検討しています。","id":"exchange-137"},{"speaker":"若林委員","kind":"質問・要望","question":"何でしょうか、少しそこは７月の開始まで時間がありますので、またご検討をほしいと求めました。しっかりと何らかの拡充の準備をしておいていただきたいということが要望の一つで、お考えをお聞きしたいと思います。","respondent":"川原高齢者地域支援課長","answer":"引き続き助成に対しての申請の時期についても、改めて検討してまいりたいと考えています。医師会の方と、今のところ検討段階ではありますが、また補聴器の販売員の方のそれぞれの立場での意見を聞きながら考えてまいりたいと考えています。","id":"exchange-138"},{"speaker":"鈴木（博）委員","kind":"質問","question":"２６５ページ、保育所の応募状況についてお伺いしてまいりますので、よろしくお願いいたします。令和４年度の病児保育の現況についてお伺いします。","respondent":"初貝保育教育運営担当課長","answer":"インフルエンザのお子様をお預かりした実績といたしましては、令和４年の２月、４月の合計で１４人という実績です。急性胃腸炎が１２１人、気管支炎が１１３人、インフルエンザなどが合計で３２４人という実績になっております。","id":"exchange-139"},{"speaker":"鈴木（博）委員","kind":"質問","question":"しかも５類に変更されて、品川区の病児保育のグラウンドデザインを検討するべきだと思われますが、いかがでしょうか。まだまだ認知が十分ではない病児保育事業そのものの存在の積極的な広報、各施設に点在し、いかがか尋ねました。","respondent":"初貝保育教育運営担当課長","answer":"検討を図っていきたいと思います。今後の病児保育の利用状況の推移などを踏まえ、需要に即した病児保育の提供ができるように努めてまいりたいと考えております。","id":"exchange-140"},{"speaker":"鈴木（博）委員","kind":"質問","question":"医療的ケア児の預かりも時代の趨勢と思われますが、現在、検討等は行われているのでしょうか。ご説明をお願いいたします。","respondent":"初貝保育教育運営担当課長","answer":"今ご質問いただきました病児保育での医療的ケア児の受入れに関しましては、スペース的な問題でありましたり人的な課題、そういったところをどのような形でクリアして園児の安全を担保するかなどといった課題や、他自治体などの動向を研究いたしてまいりたいと考えております。","id":"exchange-141"},{"speaker":"鈴木（博）委員","kind":"質問","question":"その方向を伺いたいと思います。各施設が独自の判断として、子どもの健全な発育・発展を阻害するような過剰な感染対策に固執しないような指導も含めて、区のご見解を伺います。","respondent":"初貝保育教育運営担当課長","answer":"新型コロナの状況が落ち着いてまいりましても、感染症が園で発生した際の他の園児への感染を防ぐための消毒など、適切な対応を行ってまいります。","id":"exchange-142"},{"speaker":"鈴木（博）委員","kind":"質問","question":"集中できない、寝付けない、夜起きてしまうなどのストレス症状を示す子どもが約３分の１から２分の１見られたという報告もあります。どのように対応されてきたのでしょうか、今後５類移行後、区のお考えを説明するよう求めました。","respondent":"初貝保育教育運営担当課長","answer":"行動が制限される中でも、集団を分けるなどといった工夫をしながら園での活動を実施してきた次第です。子どもの心の問題に関しましては、今後も園児の様子などを注意深く観察いたしまして、子どもの心に寄り添った保育をしてまいりたいと考えております。","id":"exchange-143"},{"speaker":"鈴木（博）委員","kind":"質問","question":"いわゆる登園許可が必要な具体的な感染症と主な対策に挙げられているような疾患に対する対応は、コロナ禍の現在、今後どのように変わるのでしょうか。登園許可証はもう既に廃止されていますけれども、今後の保育園の感染症の登園許可の扱いはどうなるのでしょうか、ご説明をお願いします。","respondent":"初貝保育教育運営担当課長","answer":"新型コロナウイルス感染症の流行前から、区立保育園においては品川区立保育園保健マニュアルに従った対応しております。それぞれの感染症に対する登園の目安をお示した登園届というものを保護者の方に記入をしていただき、提出をしていただいてです。","id":"exchange-144"},{"speaker":"鈴木（博）委員","kind":"質問","question":"１つは今でもそれは続いているのでしょうか。今後、保育職員に対する感染症研修はどのような形で続けられるのか尋ねました。","respondent":"初貝保育教育運営担当課長","answer":"最初のご質問ですけれども、登園届は今も園で実施しています。令和４年度におきましては、ウェブでの研修を実施しておりまして、延べ１０６名の方が受講しております。","id":"exchange-145"},{"speaker":"田中委員","kind":"質問・要望","question":"そして２４５ページ、プレイパーク運営費を特定整備路線予定地の活用を求めて質問します。予約方法について伺いたいと思います。","respondent":"松山障害者支援課長","answer":"いわゆる地域拠点相談支援センターのたいむを除きまして、計画相談、１２か所のうち５か所が精神の方に対応していただいているところです。その旨、たいむからご利用者へ丁寧にご説明しているのですけれども、再度丁寧にたいむから説明させていただきたいと考えています。","id":"exchange-146"},{"speaker":"田中委員","kind":"質問・要望","question":"最近は精神疾患を患う相談者が増えてきていると伺います。特に若い世代についてはどのような支援につながったのか、伺います。","respondent":"櫻木生活福祉課長","answer":"具体的なやり方ですが、例えばレシートを１か月分お持ちいただいて、家計簿を実際に一緒に伴走して作成するような支援を行っているところです。特に若者という観点というよりは、そのような形で全般として対応しています。","id":"exchange-147"},{"speaker":"田中委員","kind":"質問・要望","question":"この家庭は周りの方に一生懸命助けを求めて、様々なネットワークを駆使してリサイクル品を集めて、どうにか負担が発生せずに済みました。このようなときにも、区での支援がすぐにつながればと思うのですが、現在ある支援策について伺いたいと思います。","respondent":"櫻木生活福祉課長","answer":"ご相談、ご質問の内容ですが、１つは不動産等の資産がある生活困窮者への対応です。３点目が生活困窮世帯の生活用品ということで、例えばそのようなご案内で一時的な資金を賄っていただくというのも考えられるのかなと考えています。","id":"exchange-148"},{"speaker":"田中委員","kind":"提案","question":"生活者ネットワークが２０１８年からヤングケアラー支援、具体的支援を求めてきました。これまで家事支援やレスパイト保証を求めてきたので、ぜひ何かあればと思いますとの意見を述べました。","respondent":"染谷子ども家庭支援センター長","answer":"ヤングケアラーに対する具体的な支援ですけれども、既にこちらのほうで来年度想定しております事業の中に、家事援助を行うための訪問支援につきまして、国の財源を活用しながらヤングケアーのいるご家族にも入れていくということは想定しているものです。","id":"exchange-149"},{"speaker":"石田委員","kind":"質問","question":"４４４ページ、そして５１１ページ、介護保険について伺いたいと思います。令和４年度、あと滞納処分の執行停止数、それぞれ伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"それともう一つが、短期証と資格証の世帯ですけれども、資格証の世帯につきましては、１月末現在では４７世帯。それと短期証対象世帯につきましては１,１２７世帯です。","id":"exchange-150"},{"speaker":"石田委員","kind":"質問","question":"差押え件数は、滞納処分、執行停止と一緒になっていますか。差押え件数と滞納処分の執行停止数を説明するよう求めました。","respondent":"池田国保医療年金課長","answer":"執行停止の金額ですけれども、今年度は約２億円の執行停止という形になっているところです。件数につきましては、およそ３,４２０件が今年度の執行停止の件数となっております。","id":"exchange-151"},{"speaker":"石田委員","kind":"質問","question":"そうすると、差押え件数はさっきおっしゃった１３９件ということでいいのか尋ねました。","respondent":"池田国保医療年金課長","answer":"１３９件で結構です。","id":"exchange-152"},{"speaker":"石田委員","kind":"質問・要望","question":"この間、高過ぎる国保料を引下げこそと幾度となく求めておりますけれども、国が定める算定賦課の基準を自治体が条例で変えることはできません。厚生委員会だったり先日の補正予算で確認したところ、自治体にその考えを押しつける法的根拠はないと思うのですけれども、少々確認したいと求めました。","respondent":"池田国保医療年金課長","answer":"申請を受けてやるものが減免という指導がありますので、求められている一律での減免ということについては、それは確かなものではないということでお答えしたところだと思います。","id":"exchange-153"},{"speaker":"石田委員","kind":"質問・要望","question":"なので国がどうこうというのではなく、区として減免を行うことは可能だ。その理由を明確にお答えほしいと求めました。","respondent":"池田国保医療年金課長","answer":"５割減額、その部分で今回求められているものについては、条例としては今のところやる考えはないということでお話をさせていただいているところです。","id":"exchange-154"},{"speaker":"石田委員","kind":"質問","question":"区独自で考えて、それは国保法第７７条でできるので、そのやらない理由というのが何でなのかという納得のいく説明がいつもされないのです。国保料の減免を区として行っていくことは、こういう状況ではいよいよ重要だと思いますけれども、いかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"国民健康保険というのは相互扶助により運営されているというところで、何度も説明させていただいているところではあります。特定の対象者、あらかじめ、条例で求められていることに対しての減額については考えていないです。","id":"exchange-155"},{"speaker":"石田委員","kind":"質問・要望","question":"この公平性の観点というところからも、ほかの子どもたちと同様に、子どもの国保料の無料化を求めますけれどもいかがでしょうか。やっている自治体もありますので、ぜひ実施してほしいと求めましたけれども、いかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"それから区長会のほうでも認識しておりまして、それと保険料について申出をさせていただいて、さらに拡大するような形での申出もさせていただいているところです。","id":"exchange-156"},{"speaker":"石田委員","kind":"質問・要望","question":"そして、本当にもう今回は今までにない大幅値上げですから、それを引き下げることは可能ですので、ぜひそこに踏み出していただきたい。潤沢な財政を使ってやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-157"},{"speaker":"塚本委員","kind":"質問","question":"それから５４９ページの一般介護予防事業について伺っていきたいと思います。現在までの運用実績がどうだったかということをお伺いするのと、利用人数等はどの程度見込んでいるのか示すよう求めました。","respondent":"松山障害者支援課長","answer":"それぞれ１週間程度ショートステイをご利用いただいたです。今年度は、実績に応じて年間８人を見込んでいたところなのですけれども、令和５年度については年間６人程度ということでご利用を見込んでおります。","id":"exchange-158"},{"speaker":"塚本委員","kind":"質問・要望","question":"この医療ショートステイについては要望がかねてよりあって、利用できる、できないという実態もまだ残されているかと思います。この利用について、今後のそういった呼吸器なども含めた利用の拡大について、区としての今後の取組の姿勢等を伺いたいと思います。","respondent":"松山障害者支援課長","answer":"区としては可能な限り受け入れていただくように医療機関にお願いしていますが、希望される方全てに対応できているわけではございません。医療機関の状況が少しずつ落ち着いてくる状況を見据えまして、受入先の選択を広げるため、区内の医療機関に再度協力を求めていく姿勢です。","id":"exchange-159"},{"speaker":"塚本委員","kind":"質問・要望","question":"次に、２４３ページの子育て支援推進費なのですけれども、今日もパパママ応援アプリの件でほかの委員からもありました。うちの会派からも、今年度新しくするという、どういったところを改善していこうとしてリニューアルするのかということ初めにお伺いいたします。","respondent":"廣田子ども育成課長","answer":"今８年ほどたっているのですけれども、もう少し何がどこにあるか情報を集めるというようなことができないかところが、まず大きく一つあります。","id":"exchange-160"},{"speaker":"塚本委員","kind":"提案","question":"いろいろな技術も、いわゆるパーソナライズされた情報の発信というのがやはり求められているのかなと思って、何歳になったときにこうと。ぜひこのパパママ応援アプリの中で検討していってはいかがか、検討できないかなというところでのご提案なのですけれども、いかがか尋ねました。","respondent":"廣田子ども育成課長","answer":"少し検討はしてみたいとは思うのですけれど、全項目プッシュで入れているのですけれども、事業がたくさんあるともうすごくうるさいのです。ご提案の内容についても検討の中で入れさせていただいて、何がいいかというのは考えていきたいと思います。","id":"exchange-161"},{"speaker":"塚本委員","kind":"質問・要望","question":"まず考え方として、パーソナライズというのを意識した情報発信ということでご検討ほしいと求めましたので、よろしくお願いしたいと思います。増額の理由というか、増額によって使われるこの事業の使途について、最初にお伺いいたします。","respondent":"川原高齢者地域支援課長","answer":"充足率、令和４年度も４,４００人を超える方に継続的にご利用いただいているトレーニングの機能のものを、１クラス追加いたしました。","id":"exchange-162"},{"speaker":"塚本委員","kind":"質問","question":"恐らく多くの方が定員オーバーしてしまって、この予防事業が、今度２０２５年問題もあと２年後には来ると。やっていますかというところが１つと、なかなか難しいのかという、そこのところの区の見解をまずお伺いいたします。","respondent":"川原高齢者地域支援課長","answer":"一つ一つの事業に関しては、どれくらい効果が見込まれたかというのを、大体１クール長いと６か月間とかを継続して実施する事業ですので。介護予防の観点でこちらが主に事業として実施しなければいけないかというところを今後検証してまいりたいと考えています。","id":"exchange-163"},{"speaker":"塚本委員","kind":"意見","question":"事業の拡大につながっていくということになると思いますので、ぜひそこら辺の効果検証ということをしっかり今後取り組んでいただいて、この予防事業をより拡充できる方向でというふうにお願いをして終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-164"},{"speaker":"鈴木（真）委員","kind":"確認","question":"それが今回、急に八潮南で障害者施設、福祉施設というのが出てくるのはどういうわけなのかということで、この点を確認させてください。状況、それから運営全体としての何か課題があれば、その点についても説明を求めました。","respondent":"川崎障害者施策推進課長、松山障害者支援課長","answer":"今、八潮にこの通所事業ピッコロがございまして、ピッコロの対象者の拡充ということで整備いたします。やはり近年の障害の重度化、高齢化、この１年ほど検討してきた中で予算を計上させていただいたものになります。１０月以降、現指定管理者である社会福祉法人福栄会が丁寧に引継ぎを行いまして、利用者と契約を個々に締結しながら円滑なサービスを提供しています。","id":"exchange-165"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"１桁の人数だったのではないかと思いますし、利用者の希望に応えられるような施設を作っていただきたいということはお願いいたします。やはりプライバシーの問題はありますけれども、カメラの設置等も必要なのではないかと考えるのですが、その辺はどう考えたらいいのか尋ねました。","respondent":"松山障害者支援課長","answer":"総合支援施設におけるカメラの設置についてのご提案です。今後指定管理者と協議しまして、プライバシーに配慮しつつ、安全面の観点から検討していきたいと考えています。","id":"exchange-166"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"そこら辺を確認したかったので、移転するのか、そこら辺を教えてください。そのぐらいの展開をしていってもいいのではないかと思うのですけれども、その辺についてはいかがか尋ねました。","respondent":"川崎障害者施策推進課長、松山障害者支援課長","answer":"ピッコロの件なのですけれども、今回の拡充は２０名程度ということで予定しております。ピッコロの移転かどうかというところなのですけれども、跡地も含めまして、隣接している施設の状況を踏まえて今後検討してまいります。 総合支援施設のカフェレストランの活用についてのご質問です。今後も地域活動支援センターのイベント、いろいろな工夫をすることで集客を図り、地域の皆さんに愛されるレストランにしていきたいと思っています。","id":"exchange-167"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それからもう一点ですけれども、自立生活援助運営費助成が３３４万６,０００円。これは新しい予算が出てきて、事項別明細を見ると、その援助を提供する事業者への運営費助成と出ていたのですが、この点について少し説明を求めました。","respondent":"松山障害者支援課長","answer":"精神障害者の方がお一人暮らしをされる場合に、やはり理解力や生活力が十分でないために、一人暮らしの選択をできないという方がいらっしゃいます。ちょうど事業者に呼びかけたところ、精神障害者サポート２４の委託先のソレイユが引き受けていただいて委託するものです。","id":"exchange-168"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ソレイユというのは精神障害者の関係を随分やっていただいていると思います。１か所ではなくていろいろなところに生活していらっしゃると思うので、うまく進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-169"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/756395?Template=document&Id=1168#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":123796,"voices":378}},{"id":"r05-20230313-3","meetingId":"r05-c-budget","date":"2023年3月13日","dateIso":"2023-03-13","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時３５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を155件整理しています。","topics":[{"id":"topic-01","title":"予算特別委員会","agenda":"予算特別委員会","exchanges":[{"speaker":"澤田委員","kind":"質問","question":"２８７ページ、不妊治療助成事業、３０１ページ、普及啓発費、この２点についてお伺いします。そこで、品川区の出生数、また出生率の、ここ数年の動きはいかがか尋ねました。","respondent":"若生健康課長","answer":"３,５３６人となっておりまして、令和３年は前年度比２６７人の減、割合では約７％の減となっております。令和３年が１.１５と、こちらも令和３年は、前年から０.０６ポイント減少しています。","id":"exchange-001"},{"speaker":"澤田委員","kind":"意見","question":"令和５年１月から、顕微授精等の生殖補助医療について保険適用を可能とし、また令和４年４月まで遡り助成することとなりました。現在、品川区としても、令和５年度の不妊治療助成事業として約１,６００万円の予算が計上されていますが、その内容をお知らせくださいとの意見を述べました。","respondent":"若生健康課長","answer":"令和５年度予算案に計上しております不妊治療費１,６００万円余の内容についてです。こちらは、一般不妊治療費が３００万円弱、特定不妊治療費が１,３００万円強ということになってあります。","id":"exchange-002"},{"speaker":"澤田委員","kind":"質問","question":"令和４年度の助成金の予算額はどれぐらいあったのでしょうか。実績として、助成件数や助成金額をお教えいただけますか尋ねました。","respondent":"若生健康課長","answer":"令和４年度の予算額ですが、こちらは３,８００万円余、助成予定件数は、一般不妊治療が７０件、特定不妊治療が６６０件です。一般不妊治療が２２件で金額にして１００万円余、特定不妊治療が７５４件、３,０００万円余となっています。","id":"exchange-003"},{"speaker":"澤田委員","kind":"質問・要望","question":"そうしましたら、令和５年度と令和４年度の予算の差額はどのようにお考えでしょうか。ぜひ、それらに当たる助成に充当していただきたいという望みを込めまして、区としての見解を説明するよう求めました。","respondent":"若生健康課長","answer":"令和４年３月末までに治療を開始し、１回に限り、助成が継続されるということになってあります。そうした認識の下で、他自治体の動向なども注視しながら、助成制度の在り方を引き続き研究してまいりたいと考えています。","id":"exchange-004"},{"speaker":"澤田委員","kind":"質問・要望","question":"精神的にも苦しいものですので、４３歳以降の子どもを望む方への支援もぜひご検討いただければという要望で、こちらの内容は終わります。続きまして、３０１ページ、普及啓発費についてお伺いいたします。","respondent":"品川品川区清掃事務所長","answer":"ごみの追っかけ隊など、清掃自動車の後ろをずっと追いかけていって、ごみの流れを見学するというようなものも用意しております。それから環境のこと等といった講座をやるというようなもの、ほかにもまだ様々あるのですが、用意しています。","id":"exchange-005"},{"speaker":"澤田委員","kind":"質問","question":"そこで、ＡＩチャットボットを導入するのはいかがでしょうか。現在、正しいごみの捨て方を簡単にお伝えする手段として、品川区としても取り入れてみてはいかがか尋ねました。","respondent":"品川品川区清掃事務所長","answer":"こういうもので、例えば外国語の対応といったものも現在しているようなところです。ただ、まだまだＡＩの認識といったところが少し弱いところもあったりするというところもありますので、導入の方向に向けていろいろと研究して。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問","question":"９価ワクチンが追加されることで、これまでの２価・４価ワクチンはどのような扱いになるのか、伺います。９価ワクチンの１５歳未満の接種回数の変更など、区民へのお知らせは改めて個別通知されるのか、伺います。","respondent":"坂野保健予防課長","answer":"分科会で出てまいりました９価ワクチン、２価と４価はこのまま、サーバリックスとガーダシルはそのままです。ただ、これは２回に変更になる可能性が高いというようなことを書いて、詳しくはホームページを見てくださいというふうにしております。","id":"exchange-007"},{"speaker":"新妻委員","kind":"確認","question":"ホームページを見ていただくだけということなのか、個別通知をされるのかというところを、もう一回確認させてください。２価・４価にするのか、９価にするのかというのは、かかりつけの先生と相談の上で決めていくという判断でよろしいのか尋ねました。","respondent":"坂野保健予防課長","answer":"キャッチアップの対象者に対して正確な周知を図っていきたいと考えておりまして、通知が来ましたら、適切に対応してまいりたいと思います。医師と被接種者等がよく相談した上で９価のＨＰＶワクチンを選択しても差し支えないというふうに、資料では記載があります。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"次に、３１１ページの奨学金返還支援助成について伺います。そして、何人分を予測しての予算であるのか、区内企業への周知をどのようにして行うのか、伺います。","respondent":"遠藤商業・ものづくり課長","answer":"区内企業において、人材確保、雇用確保がかなり大きな課題となっていることを認識しております。固定費である奨学金の返済を支援することで、今回、中小企業の若手技術者の採用・雇用定着に結びつけるという形で実施させていただいたところです。","id":"exchange-009"},{"speaker":"新妻委員","kind":"提案","question":"９件を超えた場合には、また区がしっかりとご提案していただき、拡充もしていただきたいことも要望させてほしいと求めました。昨年３月の予算特別委員会、１１月の決算特別委員会で、食品ロス削減についての分かりやすい周知で動画や漫画の啓発を求めました。","respondent":"河内環境課長、品川品川区清掃事務所長","answer":"令和４年６月の農林水産省の発表では、まだまだ５２２万ｔ以上のロスが出ているということで、取り組んでいきたいと考えています。令和４年度は４期にわたりまして３か所で行っておりましたが… 粗大ごみリユースの件ですが、大体月１５０件から２００件程度、交換が行われております。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"消費者センターとしてはどう考えているのか、伺います。この件について、都市計画課など関連部署と連携しているのかも伺います。","respondent":"遠藤商業・ものづくり課長","answer":"今回の本橋開発についての私どもへの問合せですけれども、今のところ２件、情報提供というところでいただいているところです。定期的といいますか、情報が入ってきたらお知らせする、逆に情報があれば向こうから来るというようなことでさせていただいているところです。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"消費者センターとしては問題があるのではないかと考えていないのかということを伺ったので、教えてください。指導という言葉が適切なのか分かりませんけれども、働きかけなどを行うよう求めますけれども、併せて伺います。","respondent":"遠藤商業・ものづくり課長","answer":"東京都から、何らかこちらにまた問合せなり、あるいは「こういうふうにしてください」というような部分もあるのかなと考えているところです。まちづくり部門と連携しておりますが、二か月に１回ほど、区民に被害が及ばないようにと考えているところです。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"高騰が続く間は、こちらは継続すべきだと思いますけれども、いかがでしょうか。それと、銭湯のほうは、１月１０万円という金額の根拠は何なのかというのを伺いたいと思います。","respondent":"遠藤商業・ものづくり課長、若生健康課長","answer":"補正予算で、商店街装飾灯維持支援金ということで３０％の上乗せをさせていただいたところです。１本当たり１万３,４４０円という形になるのですけれども、恐らく今回についても… 今年度、補正予算でつけさせていただきました、浴場に関する物価高騰の支援金の月１０万円の根拠です。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"週末、銭湯の方にお話を伺ったのですけれども、「もちろん、ないよりあったほうがいいですよ。伺いますけれども、区の独自財源を使って追加や増額など、公衆浴場と装飾灯へのさらなる支援を行うよう求めたいのですけれども、いかがか尋ねました。","respondent":"黒田財政課長","answer":"いわゆる物価高騰に対する支援につきましては、区の必要な事業を積み上げまして、その財源として今回予算としてご提示しているものです。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"地域で猫を保護する活動をされている方々のお話を伺うと、何よりも命を大事にしたいという思いで頑張っておられるなと感じます。伺いたいのですが、これはもう明確な法律違反、罪なのではないかと思うのですけれども、いかがか尋ねました。","respondent":"舩木生活衛生課長","answer":"故意にというか意図的に毒餌で動物を殺すというか、それは委員ご指摘のとおり、動物虐待に該当するかと思います。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"極端に言えば石を投げられたりということもあったそうで、「なかなか女性１人でこうした活動をするのは大変なんですよね」という話も伺いました。雌が１万２,０００円、雄が７,０００円、伺いたいと思います。","respondent":"舩木生活衛生課長","answer":"その辺が１つ、誤解を招いてしまうことかと考えていますが、区としても啓発を充実・強化させていきたいと考えています。大体、区のモデル事業では１万円と１万８,０００円という助成ですので、この辺りも含めてしっかりと対策を考えていきたいと考えています。","id":"exchange-016"},{"speaker":"松永委員","kind":"質問","question":"１６５万円について、２９７ページのカラス及び外来種対策事業について、３０３ページのカラス対策ネット購入費について伺いたいと考えています。２７９ページのウォーキングマップアプリ運用保守等について伺います。","respondent":"若生健康課長","answer":"累計で言えば平成２８年度以降、１万５,０００件以上のダウンロード数ということで、かなりの区民の方々にご利用いただいていると認識しています。","id":"exchange-017"},{"speaker":"松永委員","kind":"質問","question":"そこでコースを増やすということは考えているのでしょうか。距離的には分からないのですが、そういったところもあったほうがいいと思うのですけれども、区の見解を説明するよう求めました。","respondent":"若生健康課長","answer":"２１コースということで設定させていただいて、ご利用いただいて、楽しんで気軽に運動を習慣づけていただくということを目的にやってあります。そういったところ、新たな機能についても、ご意見を踏まえまして様々検討していきたいと考えています。","id":"exchange-018"},{"speaker":"松永委員","kind":"質問","question":"この冊子以外にもこうした似顔絵があったと思うのですけれども、どのように変えているのでしょうか。もし森澤区長の似顔絵ができていれば、ネット上も含めて修正されたほうがいいと思うのですが、伺います。","respondent":"若生健康課長","answer":"こちらは、冊子も濱野前区長が平成２８年４月ということで、このまま出させていただいているものですが、今後こういったところのリニューアルについても検討してまいりたいと考えています。","id":"exchange-019"},{"speaker":"松永委員","kind":"質問・要望","question":"次に、２７９ページの健康ポイント事業について伺います。厳正な審査の上、執り行われているとは思うのですけれども、当選者数はどのくらいなのか、アバウトでいいので教えてほしいと求めました。","respondent":"若生健康課長","answer":"お一人１口から応募していただいて、それを、こちらで口数に応じて抽せんする。令和３年度につきましては、アプリにお申込みいただいた方については、２,４００名ほどからお申込みいただいているというようなところです。","id":"exchange-020"},{"speaker":"松永委員","kind":"提案","question":"そこで提案です。割引５００円とか、ぜひ品川区でも外れがないような形にしていただきたいと提案いたしますが、いかがか尋ねました。","respondent":"若生健康課長","answer":"現在、区内の商店街等々、そういった仕組み等を整えるといったところも検討課題として考えてあります。こういったポイント事業は今後広がりが出てくるかと思いますので、そういったところも、ご意見を参考に検討させていただきたいと思います。","id":"exchange-021"},{"speaker":"松永委員","kind":"確認","question":"次に、２９７ページのカラス及び外来種対策事業について伺います。品川区のホームページを確認させていただいたところ、桜の被害が大きく取り上げられているのは、クビアカツヤカミキリと把握しております。","respondent":"河内環境課長","answer":"その後のモニタリングなどによりまして防御ラインを設定いたしまして、そこから上陸できないようにということで取組を進めているところです。","id":"exchange-022"},{"speaker":"松永委員","kind":"質問","question":"本区では、アメリカザリガニ、アカミミガメが、品川区内で発見されている場所というのは、把握はされているのでしょうか。飼っていなければ飼っていなくていいのですけれども、そうした外来生物についてどのように対応していかれるのか、最後に説明を求めました。","respondent":"河内環境課長","answer":"ポイントですが、今までどおり飼うことはできるのですが、放流が禁止されているという点です。例えば戸越公園の池などに、そういったところも含めまして、重点的にパトロールをしながら対策を進めていきたいと考えているところです。","id":"exchange-023"},{"speaker":"江野下委員","kind":"提案","question":"私からは、２７９ページの健康づくり支援事業についてお伺いします。今、松永委員からも質問がありましたが、また違った観点から、質問や提案をしますとの意見を述べました。","respondent":"若生健康課長","answer":"今年度については、前年比でいうと１４３％増という実績になってございまして、これはアプリを入れたことがかなり大きな要因かなと考えています。","id":"exchange-024"},{"speaker":"江野下委員","kind":"確認","question":"好評ということで、確認が取れました。昨年の８月１日から今年の１月３１日までの６か月となっているので、年度初めからなど、もう少し早い時期からの実施はできないのか尋ねました。","respondent":"若生健康課長","answer":"実施期間につきましては、これは年度ごとで実施している事業でございまして、利用者向けの説明会などを丁寧にやったり。すぐの対応がなかなか難しいところではありますけれども、今後、利用者の意見なども聞きながら研究してまいりたいと思います。","id":"exchange-025"},{"speaker":"江野下委員","kind":"質問","question":"金券ですから、簡易書留となると１件４００円ぐらい。これは先日、松澤委員も触れましたが、区内共通商品券がデジタル商品券であれば、アプリ内で全て完結できるのではないか尋ねました。","respondent":"若生健康課長","answer":"そういった対応はされていないというところで、そういうところも踏まえて、商店街の所管とも意見交換していきたいと思います。","id":"exchange-026"},{"speaker":"江野下委員","kind":"質問","question":"「区民とともに進める新時代のしながわ」ですから、地域でも「昨日、区長からメッセージをいただいたよ」などといったら話題にもなると思います。先ほども松永委員が質問された、森澤区長の似顔絵ですか、こういった似顔絵などもあると面白いかと思いますが、いかがか尋ねました。","respondent":"若生健康課長","answer":"様々、今、検討を進めているところです。それから、そういったところも参考にしながら、今後も幅広い世代で健康づくりの動機づけが高まるような仕掛けを考えてまいりたいと考えています。","id":"exchange-027"},{"speaker":"江野下委員","kind":"提案","question":"「健康づくりをつうじてしながわ再発見」とも記載されていますので、提案ですが、新たにロゲイニングを取組に入れてはいかがでしょうか。いかがか尋ねました。","respondent":"若生健康課長","answer":"今年度もイベントの実施のところで参加いただいた方で、銭湯のスタンプラリーというのも、アプリで行っているところです。今後そういったご意見も踏まえまして検討していきたいと考えています。","id":"exchange-028"},{"speaker":"田中委員","kind":"質問・要望","question":"何人体制で実施を予定しているのか、区としてどのような人材を確保するよう委託事業者に求めるのか、伺います。以上、５点伺います。","respondent":"柏木品川保健センター所長","answer":"歳入の審査の際にもお答えいたしましたが、まだ検討中ではありますけれども、育児用品の調達や配達等については委託ということで考えてあります。今、契約の方法をどうしようかというのも検討していますが、そういうものも盛り込んでいけたらと考えています。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"予算を拡充してほしいという思いを込めて確認しますが、ここ３年間の不妊・去勢手術件数をお知らせください。以前、エコフェスのブースで譲渡会もされていたと思うのですけれども、現在、区が把握している区内譲渡会の実施状況を伺います。","respondent":"舩木生活衛生課長","answer":"そういった中で、予算の範囲内で活動が行いやすいような、より柔軟な支援の在り方について、現状、検討を進めているところです。機械的に１モデル地区当たり１０頭という頭打ちをすることではなく、活動を推進していただいている、様々な支援の在り方について検討しています。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"精神保健事業、避難行動要支援者の個別計画策定について伺います。たしか、私の探し方が下手で探し切れなかったので改めて伺いますが、なぜ精神障害者の個別計画は次年度に計上となったのか尋ねました。","respondent":"榎本荏原保健センター所長","answer":"優先度の考え方として、計画作成のときにしっかり確認して進めていく予定になっておりますので、その辺りも考えてあります。そういったことも含めて、よりしっかり伝わるようにということで、今、検討を進めているところです。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問・要望","question":"会議録で、消費者センターでは消費者庁からの通知に従い、資格を持つ専門相談員が相談を受ける体制を取っていると確認しました。相談時間や窓口の周知についても併せて伺います。","respondent":"遠藤商業・ものづくり課長","answer":"体制といたしましては、会計年度任用職員を６人雇っておりまして、そのうち３人が常時相談に乗っているような形で対応しています。二つか三つの中からどれかを持っていることという形になっているのですが、今、手元にご用意できなくて申し訳ございません。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"相談がないということだったのですけれども、区のホームページ等で相談体制が整っている様子が全く見えません。相談窓口があるということが多分周知されていないと思うので、そういった周知と、当事者に寄り添う姿勢というのをぜひ見せてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"やはり小石がぶつかったり、何か物が当たったりすると破損するということが多い場合があるのですが、これは義務づけていいのでしょうか。説明を求めました。","respondent":"河内環境課長","answer":"こちらの設置義務の件ですが、経済的なバランスで言いますと、売電することによりまして、１０年程度で元は取れると言われております。そういったことをご活用いただきながら、こういった再生可能エネルギーの推進に向かっていく必要があるかなと考えているところです。","id":"exchange-034"},{"speaker":"須貝委員","kind":"質問","question":"南側に建たないという保証ができるのですか。南、東南、南西方向が特に日照に関わりますが、本当に大丈夫なのか尋ねました。","respondent":"河内環境課長","answer":"地軸の関係で、そういったものが保証されるかどうかというのは、なかなか建物の形状によりまして工夫があるものと認識しております。その中で、この条例の中では、発電量について一定の工夫を凝らしながら、２kWを目安にして進めるという位置づけになっているところです。","id":"exchange-035"},{"speaker":"須貝委員","kind":"質問","question":"こういうのは無責任なやり方だと私は思うのですが、どうなのですか。日照が阻害された場合に、それなりの賠償金というのを逆に請求されるのではないかという心配もするのですが、どうか尋ねました。","respondent":"河内環境課長","answer":"後天的な要因で日照権が妨げられた場合ですが、個々のそういう案件として取扱いをするものと考えております。その上でも、また社会全体では重要と考えておりますので、そういったところも解決しながら進めていくことが肝要かと考えているところです。","id":"exchange-036"},{"speaker":"須貝委員","kind":"意見","question":"どういうふうに工夫して、私は、それなりの誠意を持ってしっかりした位置づけをするべきだと思います。もう一度、ご見解を説明するよう求めました。","respondent":"河内環境課長","answer":"こちらの条例につきましては、都が推進する条例です。区の中でのそういった紛争につきまして、個々で懸案する事項だとは認識しておりますが、こことはまた切り離して考えるものと考えております。","id":"exchange-037"},{"speaker":"須貝委員","kind":"質問","question":"日本経済や企業や国民にとって、どのような影響があるのですか。区として考えていらっしゃるのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"大企業の賃上げについてですけれども、いわゆる物価が高くなりまして、そういう部分での賃上げに、政府のほうで経済団体などへの要請などもございまして、賃上げを進めていると考えているところです。","id":"exchange-038"},{"speaker":"須貝委員","kind":"質問","question":"それからパートタイマーだって、ではどれだけ上がるのですか。ご見解を説明するよう求めました。","respondent":"遠藤商業・ものづくり課長","answer":"賃上げをすることへの経済の影響ですけれども、一長一短はあるのかなと考えているところです。なかなか一言でまとめるというのは難しいところですけれども、中小企業にとってみては、なかなか賃上げが難しいというところは聞いているところです。","id":"exchange-039"},{"speaker":"須貝委員","kind":"質問・要望","question":"だって、それだけふだん十分もらっているのですから。商業・ものづくり課ですけれども、この辺も、中小企業をしっかり支援するような対策というのはあるのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"最近では、外国の影響というのもあるというところで、区でどうこうというのはなかなか難しいというところがあります。引き続き、補正予算なども検討しながら、中小企業の下支えをしていきたいと考えているところです。","id":"exchange-040"},{"speaker":"須貝委員","kind":"質問","question":"そこでお聞きしたいのですが、プレミアム付区内共通商品券は普及事業ということでやっていますが、これは主に、目的としてはどういうことを主眼として考えていらっしゃるのか、説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"こちらは商店街の支援策ですので、消費啓発ということで、商店街にお客さんを集めるということでさせていただいているところです。","id":"exchange-041"},{"speaker":"須貝委員","kind":"質問","question":"これを今やるべきなのでしょうか。その人たちを支援する意味でも、ましてスーパーで物が買えないというのも少し不可解な気がするのですが、ご見解を説明するよう求めました。","respondent":"遠藤商業・ものづくり課長","answer":"あくまでも商店街の支援という形でやらせていただいているところでございまして、低所得者層に対する商品券というところになりますと。２３区の中で１８区ほど、非常に大事な、商店街にとって重要な施策と考えているところです。","id":"exchange-042"},{"speaker":"須貝委員","kind":"質問","question":"それで、皆さんが一番手の届く商品を買うというのは、やはりスーパーになるではないですか。そういう方向だけでいいのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"この事業を実施されていますので、いわゆる区民の方の支援ということになりますと、いろいろなほかの方法等あろうかと思います。産業支援というところでは、少し考え方がずれる部分もあろうかと思いますので、私からはこちらで、以上という形にさせていただければと思います。","id":"exchange-043"},{"speaker":"須貝委員","kind":"質問","question":"そこでも買って、でもそこでも買わない人は別のお店で、そのまま個店で買うではないですか。ここでは買わないでくれというのは、私はそろそろ見直すべきだと思いますが、再度ご見解を説明するよう求めました。","respondent":"遠藤商業・ものづくり課長","answer":"プレミアム付商品券を、様々な形で魅力のあるものにしていかないといけないということは事実ですので、こちらにつきましては、商店街連合会と一緒になって考えていきたいと考えています。","id":"exchange-044"},{"speaker":"せらく委員","kind":"質問","question":"２９３ページ、生活衛生費の、動物の愛護の部分、３０３ページ、収集運搬事業について質問します。そういったご相談に対しての、区の対応を伺います。","respondent":"舩木生活衛生課長","answer":"トイレの設置、また周辺の清掃を行うといったところのルールをきちんと守っていただくように、指導しています。残念ながら被害を受けていらっしゃる区民の方には、猫が近寄らないような忌避剤のサンプルのご提供などをして、監視・指導を行っているところです。","id":"exchange-045"},{"speaker":"せらく委員","kind":"質問","question":"区には、去勢の費用面や地域猫の制度がありますが、ほかにもサポートをしたほうがいいのではないでしょうか。伺います。","respondent":"舩木生活衛生課長","answer":"活動が充実していくような方向で、今、検討しています。様々なところでは、しっかりと周知などといったところに努めていくのが必要かと考えていますので、引き続き進めてまいりたいと考えております。","id":"exchange-046"},{"speaker":"せらく委員","kind":"意見","question":"ジモティーを実際に見たところ、０円のものや５,０００円のものがあって、その価格の決定方法。もう一点、現在までの利用者にはどのような方がいらっしゃるか、説明を求めました。","respondent":"品川品川区清掃事務所長","answer":"基本的にはもう、１日たたないぐらいで、すぐにホームページに載せるというような方法を取ってあります。基本的には車で来る方が多いと思うのですが、自転車で来て引き取っていくという方もいらっしゃって、大分、幅広い方々に利用していただいております。","id":"exchange-047"},{"speaker":"せらく委員","kind":"質問","question":"決済の種類の想定はされていますでしょうか。ありましたら説明を求めました。","respondent":"品川品川区清掃事務所長","answer":"電子決済の部分につきましては、いろいろ今、検討中でございまして、他区等でもやっている事例等も見まして、決済できるものを幅広く、できれば広げていきたいとは考えております。","id":"exchange-048"},{"speaker":"横山委員","kind":"提案","question":"２点目に、産業連携推進事業費、創業支援施設等経費についてお伺いいたします。店舗ニーズに対して空き家活用の検討を進めていただきたいのですが、現状と課題について確認させてくださいとの意見を述べました。","respondent":"若生健康課長、遠藤商業・ものづくり課長","answer":"夜間の実施ということについては、トリム体操連盟のトリムクラブという各地区の自主的な活動で行われていると認識していますが、現状。これは毎週やっている活動ですので、こういったところで何か情報提供を区でできるところがあれば… 具体的な話がないと、私どもは専門家のカタリストなどを多数抱えているところですので、まずはご相談いただければと考えているところです。","id":"exchange-049"},{"speaker":"横山委員","kind":"質問","question":"３点目に、母子保健指導事業費についてお伺いいたします。そこでお伺いいたしますが、品川区の産後ケアの種類とそれぞれの利用率を説明するよう求めました。","respondent":"柏木品川保健センター所長","answer":"産後ケアのお問合せです。産後ケア事業を始めてから５年以上経過していますので、対象者や利用回数等も含めて、内容を検討することとしています。","id":"exchange-050"},{"speaker":"横山委員","kind":"質問・要望","question":"要望で終わらせていただきます。女性が安心して子どもを産み育て、健康で長生きができるよう、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"松澤委員","kind":"提案","question":"その際、父親学級にＮＰＯの導入もあるのではないかと提案しております。どれだけの受講があるのか、近年の状況を説明するよう求めました。","respondent":"柏木品川保健センター所長","answer":"父親学級への変更以降ですけれども、令和２年度は８６５名、令和３年度は８７０名、令和４年度は７４７名の参加になっております。なお、令和２年度以降は密を避けるために、１回の参加人数を減らして実施している状況になります。","id":"exchange-052"},{"speaker":"松澤委員","kind":"質問","question":"人数も大体８００人ぐらいですか、平均して来ることが分かりました。できれば、母親学級、両親学級、父親学級と、通常でも開催するべきと考えますが、ご見解を説明するよう求めました。","respondent":"柏木品川保健センター所長","answer":"今考えてありますのは、これまでの父親学級の蓄積もありますので、内容についてもその辺は検討していきたいと考えています。まず厚生労働省が昨年３月に、「父親に対する相談支援及び両親学級への参加促進について」という通知を出していますので、まずは考えてあります。","id":"exchange-053"},{"speaker":"松澤委員","kind":"質問・要望","question":"技術というか、知識というのですか。この意識の共有をしっかり伝える、そういった講座をしっかりと設けてほしいと求めましたけれども、ご見解を説明するよう求めました。","respondent":"柏木品川保健センター所長","answer":"実施している父親学級では、産後の体と心の変化、あとはマタニティブルーと産後鬱等も行っております。お互いよく話をして子育てをしていきましょうということを、お話しさせていただいているところです。","id":"exchange-054"},{"speaker":"松澤委員","kind":"質問・要望","question":"どうしても妻が、上の長女のために一生懸命頑張って、双子が生まれた瞬間に何もやる気がなくなったと。たしか２時間半ぐらい開催していますけれども、ぜひ共有していただきたいと考えますが、ご見解をお願いします。","respondent":"柏木品川保健センター所長","answer":"オンライン開催等の見解ですけれども、両親学級のオンライン開催については、国からも必要に応じて活用するようにという通知があります。","id":"exchange-055"},{"speaker":"あくつ委員","kind":"質問","question":"２８９ページ、５１３万２,０００円、発送等について伺ってまいります。プレス発表では申請受付が７月からになっておりますが、なぜ７月からなのか、説明を求めました。","respondent":"若生健康課長","answer":"時間を見込んでいるというところで、７月開始とさせていただいてありますが、４月以降の購入分を対象とするということで予定しています。","id":"exchange-056"},{"speaker":"あくつ委員","kind":"質問・要望","question":"この６年間で８回の質疑を行いまして、様々な角度から、その必要性について繰り返し要望してきたものです。購入費助成の対象物はこの２種類に限定するということなのか尋ねました。","respondent":"若生健康課長","answer":"現在、事業実施に向けて調整中でございまして、例えばウィッグ以外の附属品や帽子などというところも助成している区があります。がんの種類によって、最初は様々ですけれども、区としては、まず使用頻度が高いと思われるものから始めていくというところで考えてあります。","id":"exchange-057"},{"speaker":"あくつ委員","kind":"質問・要望","question":"繰り返しになりますが、そこのところをもう一度、幅広く認めていただきたいというところを確認させてほしいと求めました。どうしても伸びてきてしまったり、ぜひ実質的な経済的支援を行ってほしいと求めましたが、いかがか尋ねました。","respondent":"若生健康課長","answer":"ただ、今後、事業を実施していく中で、当事者や関係者の意見も伺いながら、対象の拡大については検討していきたいと考えています。助成額の上限が１０万円、１人当たり年間２回というような内容だというお話ですが、見極めて検討していきたいと考えています。","id":"exchange-058"},{"speaker":"あくつ委員","kind":"質問・要望","question":"最後に受診勧奨について伺います。５がん検診のほかのところ、来年度予算案の中には反映されたのかどうかというところで、最後に確認させてほしいと求めました。","respondent":"若生健康課長","answer":"所管としても検討を進めておりまして、実は来年度の予算の検討の段階で、この１月に再勧奨通知をお送りしたところです。ほかのがんについても、今回の勧奨の結果等を踏まえまして、また検討していきたいと考えています。","id":"exchange-059"},{"speaker":"あくつ委員","kind":"質問・要望","question":"がんになったとしても、自分らしく品川区で生活をしていただいて、働き続けていただきたい。その１つの手段として、アピアランスケアの支援、受診勧奨の拡充、さらに推進をお願いしたいということをお願いいたしまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"おくの委員","kind":"質問","question":"「気候変動に適応する取組」とは、気候変動を諦めるということでしょうか。気候変動を受入れ、むしろ二酸化炭素などの温室効果ガスを削減しなくてもよいというふうになることだと思いますけれども、この点、いかがか尋ねました。","respondent":"河内環境課長","answer":"環境基本計画の基本目標１の内容ですが、気候変動が起こっているという状況の中で、最も大切にしなくてはいけないのは、原因となるＣＯ２の削減です。","id":"exchange-061"},{"speaker":"おくの委員","kind":"質問","question":"内容を伝えていく、啓発していくというようなことでいいのか尋ねました。","respondent":"河内環境課長","answer":"は啓発で、原因物質の究明を行うという点について、それから環境課の事業でも都の事業でやっておりますが、例えば断熱化などといったものにも取り組んでいくという内容になっております。","id":"exchange-062"},{"speaker":"おくの委員","kind":"質問","question":"それから、冬でも最高気温は２５℃を超え、熱中症となる人が出る可能性と、天気予報の画像とともに書かれています。もちろん人は生活できないのですから、この点、いかがか尋ねました。","respondent":"河内環境課長","answer":"この内容ですが、繰り返しになりますけれども、こうならないための取組として、区民・事業者の取組内容が４０ページには記載されているものです。こうならないための取組が、やはり重要と考えているところです。","id":"exchange-063"},{"speaker":"おくの委員","kind":"質問","question":"それから、同じく４０ページです。こういう再開発を前提とした取組を気候変動対策として挙げるのは、やはりあまりにも間違ったことではないかと思うのですけれども、いかがか尋ねました。","respondent":"河内環境課長","answer":"特に今後の再開発で重要なポイントといたしましては、今後、２０３０年、２０４０年を踏まえましたら、先鋭的な環境技術も発達してまいります。同じ開発をするにしても、現在よりもよりよい環境が得られるようにということで、区の取組として挙げたというものです。","id":"exchange-064"},{"speaker":"おくの委員","kind":"意見","question":"超高層再開発というのはどうしても、それを呼び込んでしまうだろうということです。そういう意味では、温暖化対策にはならないのではないかということを申し上げているのですけれどもとの意見を述べました。","respondent":"河内環境課長","answer":"１平米当たりの熱負荷の考え方ですが、建物や用途によって様々変わってまいります。該当するような考えではございません。","id":"exchange-065"},{"speaker":"おくの委員","kind":"質問","question":"それで、地球温暖化対策としては、二酸化炭素の削減を計画的に進めるということが大前提になると思うのですけれども、その点いかがでしょうか。そうなっていない今の素案の書き方というのは間違っていると私は思うのですけれども、いかがか尋ねました。","respondent":"河内環境課長","answer":"ＣＯ２の削減の方向性・考え方は委員と一致していると思います。それ以外のところでも、そういったものを推進しながら、総体の中でＣＯ２の削減に向かって取り組んでいくというような内容になっております。","id":"exchange-066"},{"speaker":"おくの委員","kind":"質問","question":"第１次の報告書は、第２作業部会でも、適応の限界に達するというような警告まで発せられています。このことを明確にした素案をつくるべきだということを申し上げて、私の質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"西村委員","kind":"質問","question":"２８７ページ、０歳児見守り・子育てサポート事業、２９７ページ、地域エコ活動推進事業、３０１ページの普及啓発事業と伺ってまいります。ご見解を説明するよう求めました。","respondent":"柏木品川保健センター所長","answer":"おむつ宅配の意義ですけれども、ご紹介をいただきましたとおり、品川区は、妊娠期間、子育ての施策を様々に実施しております。今回は、小さいお子さんをお連れですと、なかなか外出等もできずという部分での孤立化というものを防ぐための施策で計画しているものです。","id":"exchange-068"},{"speaker":"西村委員","kind":"提案","question":"例えばの提案ですが、すくすく赤ちゃん訪問で、保健師が父親に面談をすることはあるのでしょうか。お考えをお伺いしますとの意見を述べました。","respondent":"柏木品川保健センター所長","answer":"最初に、すくすく赤ちゃん訪問の際の父親との面談ですが、当然ご自宅にいる場合、あとはご家庭によっては両親でという場合もありますので、そういう場合は一緒にお話をさせていただいているところです。","id":"exchange-069"},{"speaker":"西村委員","kind":"質問","question":"今質問させていただいたのは、おむつ宅配のときに、父親や家族なども同席できるような仕組みはつくれないかというのをお伺いしました。もう一度お願いいたします。","respondent":"柏木品川保健センター所長","answer":"大変失礼いたしました。同席だからプラスで何とかというのは検討していないところですけれども、その際に、お困り事がないか等はお声がけさせていただきたいとは思います。","id":"exchange-070"},{"speaker":"西村委員","kind":"質問・要望","question":"どうしてもお母さんが対面に出てくる、ぜひ前向きにご検討ほしいと求めました。申込み制と書かれておりましたので、どう全件訪問していくのかというのも大変なことではないかと思いますが、最後に一言お願いいたします。","respondent":"柏木品川保健センター所長","answer":"委員ご指摘のとおり、このスキームをつくるのに非常に苦慮して、ですので、今まだ開始時期を正式に述べられないです。孤立化防止ですので、その目的を達成するためにきちんとした仕組みづくりをして、必ず何かあれば保健センター等と連携できるようにしてまいります。","id":"exchange-071"},{"speaker":"西村委員","kind":"提案","question":"次に、ごみの分別マナーなのですが、こちら、澤田委員からありましたけれども、また違う観点からも提案させてほしいと求めました。いろいろな区民の方にお伺いすると、汚れたものは洗浄しているのだということも知らなかったという現状があるのではないかと思っていますとの意見を述べました。","respondent":"河内環境課長、品川品川区清掃事務所長","answer":"三講座を環境講座の中に設けるとともに、そういったものはしっかり、特に家庭ぐるみの取組につなげてまいりたいと考えています。ごみの分別が脱炭素に向けて非常に有効な取組だという点を踏まえまして… まさに区の事業でやっている、ごみ・資源追っかけ隊というのが、そういうものでは区民にとって一番理解しやすいかなと思います。","id":"exchange-072"},{"speaker":"西村委員","kind":"意見","question":"だからこそ、同じ強度でずっと同じことをしなければいけないと思っています。こういった危険なごみを出す人がいなくなるように、私も活動を続けていきたいと思いますし、そういった意味での周知・啓発もお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"},{"speaker":"せお委員","kind":"質問・要望","question":"それはなぜか教えていただきたいのと、３点目、何年も前から医療費補助は１０地区分となって予算計上されています。これはなぜか尋ねました。","respondent":"舩木生活衛生課長","answer":"これが１９地区中、積算上は１０地区になっておりますけれども、こういった考えの下に積算をしていると。１０地区分しか設定していないのは、見ていないので、積算のところは１０地区と見込んでいるところです。","id":"exchange-074"},{"speaker":"せお委員","kind":"質問","question":"保護からＴＮＲのＴＮを行って、ボランティアの負担軽減のためにも譲渡につなげるという中央区の取組について、まず見解を伺います。品川区においても、地域の課題にそういったことがマッチしているかどうかも含めて、協議会のようなものを設置してはいかがか尋ねました。","respondent":"舩木生活衛生課長","answer":"シェルターをつくったとしても、その先もしっかり見据えないと、なかなか難しいというところです。それから３点目に、事業者からも、しっかりと責務があるということの啓発にご協力いただくなどという連携も検討してまいりたいと考えております。","id":"exchange-075"},{"speaker":"せお委員","kind":"意見","question":"中央区では、人と動物の調和の取れた共生社会を推進していくために、平成１７年度から、動物との共生推進員制度を創設しています。今ご答弁があったような、計画性のある５年後、１０年後といったところ、地域猫の取組をぜひお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-076"},{"speaker":"木村委員","kind":"質問","question":"私は、２８３ページの中ほどにあります受動喫煙防止対策費から質問いたします。本区でも多くの喫煙所を用意していただいているのに、なぜ受動喫煙防止対策費がかかるのか尋ねました。","respondent":"若生健康課長","answer":"これは法に基づいた対応ということで、例えば飲食店等への啓発の標識シールの掲示の確認や、こちらの対策をしています。もう一点、喫煙所の数につきましては、所管が違うので回答を控えします。","id":"exchange-077"},{"speaker":"木村委員","kind":"質問","question":"それでも２５５万円近くの予算が計上されていますけれども、この予算の使い道は、どのように配分しての予算になっているのでしょうか。そして、やはりこの事業はまだまだ必要ということですけれども、どのようになれば、その予算はもう必要なくなるのか、できれば説明を求めました。","respondent":"若生健康課長","answer":"まず啓発チラシ・グッズ等作成費用が３０万円強、飲食店への啓発資料の発送料等が３０万円弱、こちらの委託料が１９０万円強となっています。","id":"exchange-078"},{"speaker":"木村委員","kind":"質問","question":"皆さん努力されていると思いますけれども、その規則を守っていただけないとすれば、あとは何をどうすればよいとお考えでしょうか。中には、罰金を払えばいいだろうと開き直る方もいるかもしれませんけれども、現在の罰則など、罰金だけではなく何かあれば、また説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"木村委員","kind":"質問","question":"次に、２９１ページの、こころの健康づくり事業のうち、メンタルチームサポート事業、自殺予防対策事業の２点についてお伺いいたします。続けて伺いますけれども、この事業の効果について、区の評価もまた何かあれば説明を求めました。","respondent":"榎本荏原保健センター所長","answer":"多職種チームで継続的に支援を行っていくことで、安定して地域で暮らし続けられるように支援することが目的となっております。効果が見られたものの割合は７４％ございまして、多職種チームで支援を行っていくということで、一定の効果があったと認識しております。","id":"exchange-080"},{"speaker":"木村委員","kind":"質問","question":"直近の区の自殺者数ですけれども、その推移をお伺いいたします。そして、その自殺者数に対して区のお考えもお聞きしたいと思います。","respondent":"坂野保健予防課長","answer":"速報値ベースですが、５９人です。これに対する区の評価・認識ですが、令和４年、これは区としても非常に重く受け止めているところです。","id":"exchange-081"},{"speaker":"木村委員","kind":"質問・要望","question":"いろいろと大変でしょうけれども、自殺防止のために、ぜひとも本区の力を発揮してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"芹澤委員","kind":"提案","question":"２９９ページの資源回収・中間処理事業、２９７ページの環境啓発・推進事業についてお伺いいたします。職員さんが来た」と、子どもたちが憧れるようなイメージにしていただきたいと思うのですが、まずご見解を説明するよう求めました。","respondent":"品川品川区清掃事務所長","answer":"多分、やはり全体として考えていかなければいけないかなというところもあるし、そういった過程を１回通してからという形になるかと思います。","id":"exchange-083"},{"speaker":"芹澤委員","kind":"質問・要望","question":"資源化センターについてもお伺いしていきますが、その計画があるのか、まずお聞かせほしいと求めました。そこも当然、資源化センターにはまだまだ限られているとも伺っていますので、これもぜひ前向きにご検討ほしいと求めました。","respondent":"品川品川区清掃事務所長","answer":"設置はしているのですが、重さなどというところで、フルに置けるのかどうかといったところも検討していきたいと考えています。ですので、まず中身の機械の更新といったところを中心に進めていけないかというところで検討しております。","id":"exchange-084"},{"speaker":"芹澤委員","kind":"質問・要望","question":"エネルギーの循環というのですか、例えばＥＶチャージャーだと３０分ぐらいとまるわけですから、場内を見学していただくというような。個人の家での回収をやっているわけですから、可能性としてはできるのかなと思うのですが、それも併せてご見解を説明するよう求めました。","respondent":"品川品川区清掃事務所長","answer":"現実的に考えると、そういうところでの供給は可能ではないかなど、そんなところもいろいろ検討しながら考えていきたいと考えています。そういうところも含めながら、回収方法も検討していきながら、おむつのリサイクルを考えていきたいと思います。","id":"exchange-085"},{"speaker":"芹澤委員","kind":"質問・要望","question":"それで、品川区にそういった本社もあって、東京都の事業で一度採択されたようなこともあったかと伺っています。衛生的な問題が出てくると思うのですけれども、そういったご検討をひとつしていただきたいと思うのですが、ご見解を説明するよう求めました。","respondent":"河内環境課長","answer":"食品ロス５２２万ｔのうち、家庭ごみ、事業ごみは約半々ずつです。そういった両面に、こういった対応ができる技術でありましたところで、検討を進めてみたいと考えているところです。","id":"exchange-086"},{"speaker":"芹澤委員","kind":"意見","question":"今、技術で様々出ていますので、ぜひご検討ほしいと求めました。最後にお願いしますとの意見を述べました。","respondent":"河内環境課長","answer":"食品ロス削減の分野におきまして、そういうテクニカルな部分も次のステップで進めてみたいと考えています。","id":"exchange-087"},{"speaker":"こんの委員","kind":"質問・要望","question":"ワクチンは２種類で、希望者はどちらかを選択していただくことになると思いますけれども、そこでこの予算額は、何人分を想定されていますでしょうか。積算根拠も併せてお伺いしたいと思います。","respondent":"坂野保健予防課長","answer":"ただ、こちらは２回接種なので、１,３６０人掛ける２回という形になります。不活化ワクチンの分が１回１万円で、１,３６０人掛ける２回で２,７２０万円、これに事務費等を乗せまして予算の計上をしたものです。","id":"exchange-088"},{"speaker":"こんの委員","kind":"質問・要望","question":"なぜこの件数として予算が組まれたのか、お答えをほしいと求めました。先の話ですけれども、途中で補正予算などを組んでいくのか、その辺のお考えも併せてお伺いしたいと思います。","respondent":"坂野保健予防課長","answer":"この４％、２％ということの根拠なのですけれども、その辺の数字を参考にして斟酌したという形です。これを大幅に上回る数が来たときは、またそのときに補正予算等をお願いすることになろうかと思います。","id":"exchange-089"},{"speaker":"こんの委員","kind":"確認","question":"プレス発表では、４月から予診票の交付の受付開始、準備ができ次第、予診票発送、また７月から接種費用の一部助成開始とありました。申請から接種までのフローがどういう形になっているのか、その辺を確認したいと求めました。","respondent":"坂野保健予防課長","answer":"令和５年度の事業開始なのですが、４月から６月まで、システムの準備です。接種希望者にあっては、電子申請、あるいは紙ベースの申請でもよろしいのですが、４月１日から申請の受付を開始します。","id":"exchange-090"},{"speaker":"こんの委員","kind":"質問","question":"そうすると、予診票についてですけれども、申請した方のところに郵送してくださるという理解でよろしいでしょうか。申請をする手間や郵送される手間などというのを、もっと効率的にされたほうがいいのではないかと考えるところですけれども、いかがか尋ねました。","respondent":"坂野保健予防課長","answer":"これはダブり接種、２回接種してしまうのを防ぐために、取りあえず初年度はこれでやってみようということになりました。ただ、これで、もし、やはりあまりダブり接種などが起こらないのであれば、また方法については今後、見直しも検討していきたいと考えています。","id":"exchange-091"},{"speaker":"こんの委員","kind":"質問","question":"申請型を取る理由が今分かったわけなのですが、ダブルで接種してしまう危険性というのが、イメージがちょっと湧かないのですけれども。助成を受けるために申請するわけですから、また所管としても申請されるわけですから、もう少しご説明いただけますか尋ねました。","respondent":"坂野保健予防課長","answer":"なかなかうまく説明があれなのですけれども、あれは５年空けるというのがあるのですが、実は結構あるのです。ただ当然、利便性とのトレードオフにはなっているので、そこはもう、今後も見直しは検討していきたいと思います。","id":"exchange-092"},{"speaker":"のだて委員","kind":"質問","question":"私からは、３１３ページの商店街活性化事業費に関わって、買物難民支援について伺います。伺います。","respondent":"遠藤商業・ものづくり課長","answer":"スーパーが各地で閉店という話で、それに伴ってなかなか買物がですけれども、一部、区民の声という形で、私どもで具体的に伺っているのが、丸正大井町店が閉店になったということで、何とかならないかというようなことで伺っているところです。","id":"exchange-093"},{"speaker":"のだて委員","kind":"質問・要望","question":"この生鮮産品が商店街にとって重要だと考えてのことだと思いますが、今でも生鮮三品の商店が身近な場所にあることは重要だと考えているのでしょうか。伺います。","respondent":"遠藤商業・ものづくり課長","answer":"こちらは平成２５年に実施させていただいたものでございまして、支援内容といたしましては、生鮮三品支援対象品を公表・ＰＲして小冊子を作ったり。","id":"exchange-094"},{"speaker":"のだて委員","kind":"質問・要望","question":"こうした様々な効果を発揮しているということで、やはりそうしたところの支援をしていくというのが求められていると思います。買物難民の解消に向けて、移動販売への支援や、商店街への生鮮三品の出店支援などを実施してほしいと求めましたが、いかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"通常、買物難民支援というような話になった場合の対策といいますか、施策として一般的に言われているのが、１つは家まで届ける。ある程度の数が要るというようなところで実施しているというところは聞いているところですけれども、現状についてはここまでというようなところで。","id":"exchange-095"},{"speaker":"のだて委員","kind":"質問・要望","question":"それが、やはりほかの方々、子どもたちや障害を持っている方たちにも優しいまちになると思います。商業の面からも、ぜひ支援していっていただきたいと思うのですが、いかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"ただ、例えば丸正の後にはドラッグストアができるというような話も聞いているところです。あるいは、ほかのところも新しく入ってくるということも聞いていますので、その辺を見ながらという形で考えているところです。","id":"exchange-096"},{"speaker":"のだて委員","kind":"質問・要望","question":"都会でもこうした買物難民、経済産業省の定義では難民とは言わないかもしれませんが、買物弱者ですか、そういったところの支援を、区としても実施してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"渡部委員","kind":"確認","question":"事項別明細書を確認して、これは３６５日２４時間対応みたいな感じがするのだけど、そこまでこれはやっているのですかというところ。これは年に１回ですか、ずっとこれはやっていってもらえるという認識でいいのかどうか、併せて説明を求めました。","respondent":"舩木生活衛生課長","answer":"いつ発生してもすぐに対応が取れるように、３６５日２４時間というご指摘もございましたけれども、現状ではそういう体制を取っております。こちらは年４回ほど雨水ますに薬剤を投入し、こちらも、そういう意味では一定の成果を果たしていると認識しております。","id":"exchange-098"},{"speaker":"渡部委員","kind":"質問・要望","question":"１万円上がったりしているぐらいですから、そこは言っておきたいと思ったので、今日お話をさせていただきました。予算書を確認したときに、２０万円、５００件と書いてあった。","respondent":"遠藤商業・ものづくり課長","answer":"今年度までやっております新型コロナウイルス感染症対応中小企業支援特別助成、上限額２０万円、こちらの金額等については一緒のものです。","id":"exchange-099"},{"speaker":"渡部委員","kind":"質問・要望","question":"これもやっていけるのだというのは本当にうれしく思いますので、ここもまだまだ拡大していってもらいたいぐらい、お願いしたいと思います。区内の金融機関などは本当に区内の事業者との付き合いが深いですから、そういう方たちを対象にした、それに対するお考えをお聞かせいただけますか。","respondent":"遠藤商業・ものづくり課長","answer":"正直、どうしても、相談員だけでも対応できないようなかなり細かい部分も出てきているところです。翌年度の部分について毎年３月の下旬に、それから一部、国や都の施策についての説明会を実施する予定です。","id":"exchange-100"},{"speaker":"渡部委員","kind":"質問・要望","question":"一つ、最後に伺います。品川区が設計してやっているのですよねという確認と、今回、大崎のブライトコアホールのような使い方をするのか。","respondent":"遠藤商業・ものづくり課長","answer":"こちらにつきましては、日本郵政不動産からの賃貸という形で実施するものでございまして、私ども商業・ものづくり課で運営するものです。毎月１,１００万円の消費税掛ける、令和６年度からは１２か月、来年度につきましては５か月という形になるところです。","id":"exchange-101"},{"speaker":"高橋（し）委員","kind":"質問","question":"３０７ページ、モンゴル高専との科学技術交流事業、３０９ページ、品川区シルバー人材センター支援事業について伺います。この認識でよろしいか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"対応方法といたしましては、その分の経費をそれぞれの事業者に要求して、その分を払うという形になっているところです。","id":"exchange-102"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"人生１００年時代を迎えて、国を挙げて生涯現役社会の実現が求められる中、昨年１２月の段階で２,１７０名もいらっしゃいます。そういうことになってしまうのですが、その点においては、いかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"そういうものを拒むというのはやめなさいというＱ＆Ａ等も出ているところですので、こちらを活用して、ぜひともきちんと価格転嫁には応じていただければと考えているところです。","id":"exchange-103"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"特別区長会をはじめ、東京都市長会、東京都町村会および東京都と共に、国へ要望していくべきだと思います。令和５年度の特別区長会の要望には、国に要望をしていっていただきたいと思うのですが、いかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"今回のシルバー人材センターの関係ですけれども、シルバー人材センターで、それぞれ上部機関などがあると聞いているところです。そこから様々な要望等を出していますので、区として要望等を出す考えは今のところございません。","id":"exchange-104"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今要望が、国に要望を出していただきたいと、これは要望で終わります。この方々の働きぶりと、その方々が働きながら、どういう将来の夢を持って品川区で働いているかなどが分かれば、ご紹介ほしいと求めました。","respondent":"遠藤商業・ものづくり課長","answer":"現在働いている方、１０人余という形で来ていただいているのですけれども、かなり優秀な方がこちらにお見えになっていると聞いているところです。大変志の高い方が多くなっているというところですので、現在、本当に真面目に働かれていると感じているところです。","id":"exchange-105"},{"speaker":"高橋（し）委員","kind":"意見","question":"これは本当に、きちんと国際交流ができていく、すばらしい仕組みだと思っています。令和５年には、簡単にお話しいただいて、その実効性と見込みをお願いしますとの意見を述べました。","respondent":"遠藤商業・ものづくり課長","answer":"今までなかったコンピュータの工学、ＩＴ学科というものが設置されまして、令和７年が最初の卒業になるのかなと考えているところです。改めて今年の５月にも、大体３０人ぐらいが、品川区の予定で進んでいるところです。","id":"exchange-106"},{"speaker":"高橋（し）委員","kind":"質問","question":"非常に目立たない、地味であるものですが、品川区ならではの施策だと思います。継続とさらなる発展を期待して、質問を終わりにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"},{"speaker":"たけうち委員","kind":"質問","question":"２８９ページの眼科検診、それから定期予防接種の中の百日ぜき、それから胃がん検診で伺いたいと思います。平成３０年度の予算特別委員会で鈴木博委員が質問されていましたけれども、まだなっていないのかなと思うのですが、その辺の経緯を説明するよう求めました。","respondent":"若生健康課長、坂野保健予防課長","answer":"令和元年度から開始しておりまして、そういった対象の方にご案内をお送りして、区内の眼科機関で受診いただくということになってあります。開始が令和元年でございまして、かかりつけといいますか… これに関しましては、国で現在、ＤＴをやめてＤＰＴに変えていこうという議論が進んでおります。まだ分からないところなのですが、近いうちの法定化は、少なくとも俎上には上がっているというところは言えるかと思っています。","id":"exchange-108"},{"speaker":"たけうち委員","kind":"質問・要望","question":"食道や十二指腸など、これは、５０歳以上の方は胃カメラにシフトしていくという考え方があるのかどうかというのを教えてほしいと求めました。１０歳、１１歳くらいで発症してくると聞いておりますので、教えてほしいと求めました。","respondent":"若生健康課長、坂野保健予防課長","answer":"眼科検診につきましては、医師会等々のご要望等もございまして、区としても必要性を認識して実施しています。区といたしましては、バリウムと内視鏡、そういったことで現在のところは進めているところです。百日ぜきについてですけれども、ちなみに２０２２年は区内発生届ゼロということで、今なかなか難しい部分も若干あるのですが。","id":"exchange-109"},{"speaker":"たけうち委員","kind":"質問・要望","question":"これからマスクを取っていくようになりますので、ぜひよろしくお願いしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-110"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"さらに、かねてから要望している男子へのＨＰＶワクチンの接種費補助について、区のご見解を再度伺いたいと思います。ＤＰＴ３種混合ワクチンの追加接種への接種補助を要望いたしますが、区のご見解はいかがか尋ねました。","respondent":"坂野保健予防課長","answer":"国で効果等について検討を進めているということでございまして、引き続きではありますが、これを注視してまいりたいと考えております。国で現在、定期化の検討が進んでおりますので、そちらを注視してまいりたいと考えております。","id":"exchange-111"},{"speaker":"鈴木（博）委員","kind":"提案","question":"ここで言っているのは、５歳の時点での、ＭＲ、おたふく風邪と一緒に３種混合ワクチンを一緒にやったらどうかという提案です。区として情報提供をどのように進めていくおつもりか、伺いますとの意見を述べました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"現在の１２歳以上のオミクロン株対応ワクチンの接種率です。令和５年度、個別医療機関中心の体制へ移行を進めることが適当と先週末に示しましたので、国の方針に沿う形で検討を進めることになると思います。","id":"exchange-112"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"極めて複雑で分かりにくくなっており、接種希望者がワクチンの接種の対象者になっているかどうか、一々確認しなければならない状態です。今回も繰り返し要望したいと思いますが、区のお考えはいかがか尋ねました。","respondent":"柏木品川保健センター所長","answer":"先月、２月になりますが、品川保健センターの乳幼児健診の対象の保護者に、薬の飲ませ方、服薬に関するアンケートを実施しております。今後、アンケートの結果を踏まえて、薬剤師等の関係機関とも相談しながら検討してまいります。","id":"exchange-113"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"この２つの無料化を求めて質問したいと思います。共産党としても提案し続けていますけれども、これを無料にすべきだという考えはないのか、伺いたいと思いますとの意見を述べました。","respondent":"若生健康課長","answer":"そういったところでの協議が望ましいと考えており、現状で、区として無料化という考えはございません。小委員会や検討部会というところでは、そういったところを、５者で協議を重ねているというところになってあります。","id":"exchange-114"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"区からそれを提案して話し合うという、議題に載せるということをぜひしていただきたいと思うのですけれども、いかがでしょうか。実質的に無償化が図れるという答弁だったのですけれども、どういう計算で実質的に無償化と考えるのか、伺いたいと思いますとの意見を述べました。","respondent":"若生健康課長","answer":"は今後実施していく、出産後５万円といったところも組み合わせていきますと、出産費用については実質無償化が図られるものと認識しています。東京都内でいきますと、これは公的病院に限るのですけれども、５６万円ちょっとというような出産費用になっていると認識しています。","id":"exchange-115"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、ここのところを実際に品川区として、港区と同じように助成して、出産費用を無償にしてほしいということでずっと要望しています。ぜひとも品川区独自の、相差の３１万円まで、港区と同じように助成していただくよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-116"},{"speaker":"松本委員","kind":"質問","question":"２９７ページ、３０３ページ、有料ごみ処理券経費について伺います。こちらは何か法的な根拠、法令の根拠があるのか伺います。","respondent":"河内環境課長","answer":"カラスにつきましては６月あたりに巣を作り、こういったものの許可につきまして、許可業者がこういった行為に及ぶというところで特例です。ハトについてはこういったものはございません。","id":"exchange-117"},{"speaker":"松本委員","kind":"確認","question":"伺っているのが、もう一度確認したいのですが、それを許可していくというものだと思います。ここの部分は特に法令の根拠はなく、区が独自にそういうことをやっているという理解でよろしいのか、伺います。","respondent":"河内環境課長","answer":"こういった対応につきまして、都の基準も設けられているところではあります。威嚇行為があった場合には、業者をあっ旋し、区の予算でそういった対応をするということになっているところです。","id":"exchange-118"},{"speaker":"松本委員","kind":"質問","question":"そこまで見つけられなかったのですけれども、カラスのほうの基準というのは、どういった都の基準なのでしょうか。お願いします。","respondent":"河内環境課長","answer":"テリトリーの考え方なのですが、広域公害にわたってはとか、局所公害については区が受け持つということになっております。業者をあっ旋し、巣の撤去、またカラスの個体の捕獲を行うというものになっているものです。","id":"exchange-119"},{"speaker":"松本委員","kind":"質問","question":"商店街の方たちにお話を伺っていると、ハトをどうにかしてほしいという話はやはり出てくるのです。商店街や町会等に対する支援という形で、ハトに対する対策を考えていけないのか、お伺いいたします。","respondent":"河内環境課長","answer":"安全帯としてそこを認識していって、そこに繰り返しやってきて巣を作り、居つきというようなことをやるものです。再発防止もセットといたしまして、区民の方に情報提供することによりまして、きちんと対応していただいています。","id":"exchange-120"},{"speaker":"松本委員","kind":"質問・要望","question":"情報提供だけだと、なかなか難しいところもありますので、すぐにということではありませんけれども、ぜひ今後ご検討ほしいと求めました。最後に一言、何かあればお願いいたします。","respondent":"河内環境課長","answer":"もちろん事業者の方にとりましても同じ技術ですので、効果的なものがあれば、そういう事例も含めまして、情報を伝達しながら、キャッチボールしながら、こういったものに取り組んでいきたいと考えているところです。","id":"exchange-121"},{"speaker":"松本委員","kind":"質問","question":"食の中でも、食との関係で考えていくと、独身男性というのが１つ、大きな問題かと。今日お伺いしたいのは、特に高齢者向けの料理教室の実施状況、また定員と、近年の定員充足率が分かればお願いいたします。","respondent":"若生健康課長","answer":"高齢者向けの料理教室についての状況です。実施しておりまして、今年度１６名が参加ということで、男性が６名ということになってあります。","id":"exchange-122"},{"speaker":"松本委員","kind":"質問・要望","question":"そう考えると、単に料理教室と言っただけだと、なかなか行くことができないのかなと思うのです。何かプラスの付加価値をつけていくという考え方がないか、ぜひ要望したいのですけれども、お願いいたします。","respondent":"若生健康課長","answer":"男性、特に高齢者の料理教室への参加は、非常に区としても課題と感じてあります。委員ご指摘のような、ほかのところとのコラボといいますか、そういったところも踏まえまして、検討していきたいと考えています。","id":"exchange-123"},{"speaker":"若林委員","kind":"質問・要望","question":"それを、再商品化というのですか、再商品化したものの活用とか、販売というのでしょうか。今回１台設置したというところで、この企業との協定の内容と、今後の庁舎などへの増設の計画についてもお聞きしておきたいと思います。","respondent":"坂野保健予防課長、品川品川区清掃事務所長、河内環境課長","answer":"周知につきましては、今回の予防接種は定期接種ではないので、積極的な勧奨というのが、行政がすることがあまりできないのです。したがって… それから純粋にマテリアルリサイクルとしてプラスチック製品に変えていくというような手法があります。まだまだ研究中なところもありまして… 民間事業者と提携いたしまして、マイボトル型給水機、水を浄化して給水する機械を設置したものです。","id":"exchange-124"},{"speaker":"若林委員","kind":"質問・要望","question":"そういう要望をさせていただきましたので、帯状疱疹というものがどういう病気なのか、しっかりとお知らせしていただきたい。マイボトル給水機をどんどん使ってくださいということにつなげていってほしいということの観点で質問いたしましたので、また。","respondent":"河内環境課長、品川品川区清掃事務所長","answer":"それから、５台の件ですが、協定上、５台ということで、既に協定を締結しておりますので、その方向で、設置に向けてやってみたいと考えています。現在、１か月間ぐらいで大体ペットボトル３００本相当だというところで… プラスチック製品の再生品の販売についてですけれども、これは再生業者で独自で販売ルートを見つけてやっていくという流れです。","id":"exchange-125"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"最初に、２９５ページ、省エネルギー対策事業の高効率給湯器設置助成についてお伺いいたします。これは規模に応じて、エコジョーズは３万円の助成を受けることができることとなっておりますけれども、間違いないのかというのを確認したいと求めました。","respondent":"河内環境課長","answer":"こういったものの支援などが記されているとともに、構成要素の中に燃料電池も入っておりまして、こういったものの推進が必要と判断したものです。","id":"exchange-126"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"できる限り多くの区民の皆さんにお知らせしていただきたいということで、このような制度自体を知らない区民の方もこれから出てくると思います。あるいは、より効果的な方法の周知というのを、どういうふうに考えておられるのか、教えてほしいと求めました。","respondent":"河内環境課長","answer":"１つは、こういった手法があるということをしっかりと、エコルとごしを中心にいたしました啓発の中で発信していきたいと考えています。ＺＥＨ＋などの活用方法があることを、力強く発信することにより、全体の脱炭素に向けての取組を進めてまいりたいと考えているところです。","id":"exchange-127"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、２９７ページ、環境学習交流施設管理運営費の中の、エコルとごしについてお伺いいたします。お知らせほしいと求めました。","respondent":"河内環境課長","answer":"で多目的ホールが１００名の定員ということで、いかに今後の啓発の中でメニューを提供していくかというのが今の課題かと考えています。そういった啓発を含めまして、世の中のそういったものの推進に向けて、今後も邁進していきたいと考えているところです。","id":"exchange-128"},{"speaker":"高橋（伸）委員","kind":"提案","question":"これは、令和３年度から、中央区から森林環境譲与税について、都内連携、複数区での協働連携について提案がありました。特別区同士の連携先として、これから目星というのですか、今、現時点で決まっている区があるのかというのもお知らせほしいと求めました。","respondent":"河内環境課長","answer":"そういったところの整備を進めることによりまして、我が区も参画を検討しながら、今参加しています。都内６市町村の、みんなの連携の中で、こういった事業に取り組んでいる状況です。","id":"exchange-129"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これは要望として収めさせてもらいますので、ご検討をよろしくお願いいたします。続きまして、２９９ページ、木製粗大ごみのマテリアルリサイクルについてお伺いいたします。","respondent":"品川品川区清掃事務所長","answer":"木製だけで１,０００ｔぐらいまではリサイクルに回せるだろうということで、今、想定してやっているところです。ですので、おおむね４分の１程度はパーティクルボードになっていくのではないかという予想でおります。","id":"exchange-130"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"そうすると、そのことによって、温室効果ガスの削減量はどの程度か、それは大体で構いませんので、教えてほしいと求めました。","respondent":"品川品川区清掃事務所長","answer":"清掃工場の中でＣＯ２の割合を各清掃工場で出しておりまして、燃やすことによって重さの半分程度のＣＯ２が出ているですので、大体１,０００ｔぐらいからすると５００ｔぐらいのＣＯ２を削減できるのではないかと考えております。","id":"exchange-131"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"パーティクルボード利用によって抑制される新品の建築材料費や、温室効果ガス削減によって経済効果との比較はどのようになるのか。ある程度、試算というのがあると思うのですけれども、もしそういった試算が分かれば教えてほしいと求めました。","respondent":"品川品川区清掃事務所長","answer":"基本的にこの事業をやることによる効果という点では、区のリサイクル率が大体１％程度、削減できるのではないかと考えております。ですので、リサイクルに回せる部分があれば、それだけ分担金の金額が削減できるというようなことは考えております。","id":"exchange-132"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ今後も積極的にやってほしいと求めました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-133"},{"speaker":"吉田委員","kind":"質問・要望","question":"そこから伺います。補助金の性格を教えていただきたいのと、対応する支出は２９９ページあたりのリサイクル推進費関連でいいのか、伺いたいと思います。","respondent":"品川品川区清掃事務所長","answer":"補助金につきましては、基本的には啓発関係の部類で使用するものです。ですので、チラシの作成、それから看板の作成といったところで、作成費用についての一部補助をするものです。","id":"exchange-134"},{"speaker":"吉田委員","kind":"質問","question":"ごみの削減策を具体的に検討するためには組成調査を行うべきと考えますが、見解を伺います。もしこの調査の後、組成調査をしたということがありましたら、それについても、答えるよう求めました。","respondent":"品川品川区清掃事務所長","answer":"この作成に当たって組成調査は行っております。調査結果の報告等も、委員会等で、概略ですが、報告しているというものです。","id":"exchange-135"},{"speaker":"吉田委員","kind":"質問・要望","question":"ごみの分別については、区民の啓発を求めるご意見は、この委員会でも多く出ていると感じます。今、組成調査をされたということですけれども、家庭ごみ、事業系ごみ、どういうごみについて調査をされたのか、伺いたいと思います。","respondent":"品川品川区清掃事務所長","answer":"家庭ごみ、それから事業系ごみ、両方とも組成調査をしています。","id":"exchange-136"},{"speaker":"吉田委員","kind":"質問・要望","question":"例えば光学式選別機とか色彩選別機になるのでしょうか、などが必要で、その前に手選別が必要になるというような話も伺いました。それとも区が直接実施するのか尋ねました。","respondent":"品川品川区清掃事務所長","answer":"中間処理のところが非常に注目されているところですが、基本的には中間処理は委託を考えております。中間業者の中で、どう効率性が上がるかというところを研究して、これから進めていく内容ではないかと考えています。","id":"exchange-137"},{"speaker":"吉田委員","kind":"質問","question":"このプレス発表資料だと、委託費がどれくらいになるのかが分からないのですけれども、結局、手選別ですかと。だから、光学式選別を使っても、中間処理についての委託費はどこを見たら分かるのか尋ねました。","respondent":"品川品川区清掃事務所長","answer":"こちらに中間処理も含まれているというものです。お時間がかかって申し訳ございません。","id":"exchange-138"},{"speaker":"吉田委員","kind":"質問","question":"要は、制度を変更できないのかということを何度か伺っているのですけれども、今回の予算も従来どおり１６人という予定になっております。伺います。","respondent":"若生健康課長","answer":"区としては歯科健診を、これは成人歯科、それから障害者歯科と、着実にやっていきたいと考えています。障害者歯科健診は区内の歯科医師会に委託させていただいて実施しておりまして、今後、使いやすい制度への見直しは進めていきたいと考えています。","id":"exchange-139"},{"speaker":"吉田委員","kind":"質問・要望","question":"「こちらにいらしたらどうですか」と、区内の指定された歯科医師から指定されたら、それが区外の医者だったなどという事例があるのです。どうぞ積極的にご検討をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-140"},{"speaker":"大倉委員","kind":"質問・要望","question":"２８９ページ、帯状疱疹ワクチン、２９７ページ、環境学習交流施設、エコルとごし、３０３ページのカラスの対策で伺います。繁殖時期が３月から６月ということで、相談や苦情の件数など、どこに偏っているかなどが分かれば教えてほしいと求めました。","respondent":"坂野保健予防課長、河内環境課長、品川品川区清掃事務所長","answer":"ワクチン２種類、一般論で申しますと、シングリックスのほうが持続期間が若干長いと。シングリックスで８年ぐらいという研究成果もありますし… 現在の検討状況ですが、メンテナンスも含めて５台までご提供いただけるという中で、エコルとごしに１台です。今後、区民の目線に立ちまして… カラスによるごみの散乱の件です。そういう場所があった時点で、清掃職員が行って、周りの該当者に対して指導をして対応しています。","id":"exchange-141"},{"speaker":"大倉委員","kind":"質問・要望","question":"受けやすい環境をつくっていただきたいと思っているのですが、あえて、２つのワクチンを助成している意味について教えてください。そうしたところ、直接、店舗への指導などというのはどのようにされているのか尋ねました。","respondent":"坂野保健予防課長、河内環境課長、品川品川区清掃事務所長","answer":"ある効果を期待するのに、選択が２つある。ですから、区としては、医師の選択権を十二分に担保した状態で、どちらでもいいですよというご案内にしています。したがいまして、そういった場合には、補充ができるポイントがどこにあるかという点が非常に重要になってまいります。… ただ、そういう集積場などが汚い場合については、当然、区として環境を維持する観点からも、指導に入っているような状況です。","id":"exchange-142"},{"speaker":"大倉委員","kind":"質問・要望","question":"そういったごみが散乱しないように取り組んでほしいと求めましたが、どうでしょうかということと、選択権というところで分かりました。今、さらに環境対策を推進した品川区独自の取組として進めていくということもできるのかなと思うのですが、その点について説明を求めました。","respondent":"品川品川区清掃事務所長、河内環境課長","answer":"他の部署との連携ですが、当然いろいろ情報共有をしながら、連携できる部分については連携して、こういう対策は進めていきたいと考えております。 そういったことも含めまして、やはり啓発効果の高いところとの連携など、今後そういった感覚で進めてまいりたいと考えております。検討します。","id":"exchange-143"},{"speaker":"大倉委員","kind":"質問","question":"ウォーターサーバーだけではなくて、商店街との連携というところでぜひ進めていっていただけないかと思っての質問です。もう一回、お願いします。","respondent":"河内環境課長","answer":"公園の蛇口や水道栓までいろいろ出てまいりまして、やはり安心して飲めるようなお水も、そういうところも踏まえながら進めていければと考えています。商店につきましても同じようなことが言えるかと思いますので、よろしくお願いいたします。","id":"exchange-144"},{"speaker":"大倉委員","kind":"提案","question":"お店の中できちんと管理されたところでマイボトル運動というのが進められると、より安心安全かなと思いましたので、提案させていただきました。そういった取組が、もったいないプロジェクトと併せてどんどん進んでいくといいなと考えていますので、ぜひとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-145"},{"speaker":"塚本委員","kind":"質問","question":"それで、もし時間があるようでしたら、２８９ページの新型コロナウイルスワクチン追加接種ということでお伺いします。この事業について、区民の声や、また区としての経済効果等の評価を、まず最初にお伺いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"昨年実施しましたキャッシュレス決済ポイント事業です。そういう部分では、特に１１月の閑散期に当たるところで、そういうところでは重々効果があったのかなと考えているところです。","id":"exchange-146"},{"speaker":"塚本委員","kind":"質問","question":"それと、先ほど、決済として使ったのが３億８,０００万円ぐらいですか。ぎりぎりまで使ってほしいと思ったところはあったのですけれども、そこについて、その辺についてのご説明があればお願いしたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"それから、当初、１２月１５日までということでやっていたところなのですけれども、１週間ほど前倒しで終了という形にさせていただいたところです。１日１,６００万円となりますと、時期的に１２月、このような形で終わらせていただいたところです。","id":"exchange-147"},{"speaker":"塚本委員","kind":"質問","question":"キャッシュレスポイント還元とデジタル商品券の違いをお伺いしましたけれども、経済施策というのでしょうか、これについての区の見解をお伺いしたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"特にこの３つがなかなか当てはまらない部分が多かったというところで、デジタルにしてくれと言うのが難しいというような話を聞いているところです。","id":"exchange-148"},{"speaker":"塚本委員","kind":"質問・要望","question":"なかなか区民の要望というか需要みたいなものを満たせないのかなというところが、今、キャッシュレスというところで出てきていると思います。区の施策なので主に中小企業ですけれども、企業側、中小企業のメリットというのはどういうものなのかというところをお伺いいたします。","respondent":"河内環境課長","answer":"そういったところの支援につながるような形で、今後、ＧＸの成長に沿うようなものをさらにやっていきたいと思います。現状の支援策ですが、そういったものを支援しておりますので、そういったものも踏み込んで検討していきたいと考えているところです。","id":"exchange-149"},{"speaker":"塚本委員","kind":"質問","question":"今、環境課からお答えをいただきましたけれども、産業連携推進事業、商業・ものづくり課のほうですけれども、この中で、いわゆるＧＸに関わるような取組というのはこれまであったのか、あるいは今後、予定等があるのか、現状についてお伺いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"なかなか、ＧＸについてこちらからお知らせしても、まだ反応が薄いというのが正直なところです。","id":"exchange-150"},{"speaker":"塚本委員","kind":"質問・要望","question":"今後、区内中小企業の競争力等々の向上のために、ぜひこういう施策も今後進めてもらいたい、進める必要があるのではないかと考えています。ぜひこういうものを前に進めていただきたいと考えているのですけれども、最後にご見解をお伺いいたします。","respondent":"河内環境課長","answer":"現在のＧＸを取り巻く状況ですが、親会社のというところで、グループ全体のＣＯ２の削減に向けてというような取組も非常に進んでいるところです。","id":"exchange-151"},{"speaker":"塚本委員","kind":"質問・要望","question":"残りは時間がないので、また何かの機会に質問させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-152"},{"speaker":"鈴木（真）委員","kind":"提案","question":"先ほど、私どもの会派の芹澤委員からいろいろ提案をさせていただきまして、時間がなくて要望し損なった部分を確認させてほしいと求めました。品川区は当然いろいろな支援をしていますけれども、この件に関しては何か方法がないのかというのは確認させてほしいと求めました。","respondent":"品川品川区清掃事務所長、遠藤商業・ものづくり課長","answer":"これについては、多分また事業者である東京都と東京ガスと調整しながら進めていくような形になるかと考えています。基本的には置場としては現在も活用しているということですので、なかなか… 現金勘定をするときに、信用金庫なり郵便局に行くと、両替の手数料がかかるというような話になっているところです。そこの費用等を考えてご検討いただくという形になるのかなと思っているところです。","id":"exchange-153"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"商店街支援ですから、区として税金を使っている関係からすると、区民の方にする還元が弱くなるのではないかという声がありました。ある程度、積極的な展開もしていくべきではないかと思うのですが、その点についてもお答えほしいと求めました。","respondent":"遠藤商業・ものづくり課長","answer":"海外進出の推進事業ですけれども、こちらは平成２１年度から実施させていただいたところですが、平成２８年度で終了という形になっているところです。私どもでは国際化対応の部分での専門家相談員を配置しておりまして、週１回、相談などを受け付けさせていただいています。","id":"exchange-154"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"そうすると、その辺は自分たちにとってどうなのかということからの発想だったのです。少し頭の中に入れておいていただいて、そういう時期が来たらぜひ進めてほしいと求めました。","respondent":"つる委員長","answer":"以上をもちまして、本日予定の審査は全て終了いたしました。","id":"exchange-155"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/756395?Template=document&Id=1170#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":124973,"voices":350}}]);
